static _Atomic int g_q4_inflight;        // game command buffers committed and not yet completed (GPU keep-alive, keepalive_start)
static dispatch_semaphore_t g_ka_idle;   // signalled when g_q4_inflight drops to 0
/* iOS rejects GPU submissions from a background app (kIOGPUCommandBufferCallbackErrorBackgroundExecutionNotPermitted): the command buffer is dropped, and render targets and uploaded content are lost with it.
   iOS refuses GPU work from a background app; while the app is not active every commit waits here and resumes in the foreground. */
static pthread_mutex_t g_bg_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_bg_cv = PTHREAD_COND_INITIALIZER;
static _Atomic int g_app_inactive;
void mtl_app_active(int active) {
    pthread_mutex_lock(&g_bg_mu); atomic_store(&g_app_inactive, !active); pthread_cond_broadcast(&g_bg_cv); pthread_mutex_unlock(&g_bg_mu);
}
static void bg_gate(void) {
    if (!atomic_load_explicit(&g_app_inactive, memory_order_relaxed)) return;
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    pthread_mutex_lock(&g_bg_mu); while (atomic_load(&g_app_inactive)) pthread_cond_wait(&g_bg_cv, &g_bg_mu); pthread_mutex_unlock(&g_bg_mu);
    MLOG("App not in the foreground: GPU submission was paused for %.1f s, resuming now", (clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0) / 1e9);
}
static void ubc_wait_all(void);
static int par_chain_commit(id<MTL4CommandBuffer> cb, TotkCommitOptions *o);   // TOTK_PAR_ENCODE (nvn_par_encode.h): suspended chunks committed with the replay's command buffer
static void q4_commit(id<MTL4CommandBuffer> cb, TotkCommitOptions *o) {
    ubc_wait_all();   // TOTK_UB_COPY_THREAD: uniform copies queued before this commit are in memory before the GPU can read them
    bg_gate();
    gpu_budget_check("commit command buffer");
    atomic_fetch_add(&g_q4_inflight, 1);
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) { (void)f; if (atomic_fetch_sub(&g_q4_inflight, 1) == 1 && g_ka_idle) dispatch_semaphore_signal(g_ka_idle); }];
    if (!nogpu()) { if (par_chain_commit(cb, o)) return; id<MTL4CommandBuffer> buffers[] = {cb}; [g_q4 commit:buffers count:1 options:o]; return; }
    for (MTL4CommitFeedbackHandler h in o->handlers) h(nil);
}
static void cb_commit(id<MTLCommandBuffer> cb) { bg_gate(); if (!nogpu()) [cb commit]; }
static void cb_wait(id<MTLCommandBuffer> cb) { if (!nogpu()) [cb waitUntilCompleted]; }
static uint64_t g_fence;                        // Highest committed fence value (incremented exclusively by the submit thread)
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static uint64_t g_done;                         // Highest completed fence value (written by the completion callback)
static _Atomic int g_last_commit_error;
static _Atomic int g_up_pending;
static void up_pending_wait(useconds_t poll_us);   // until every committed upload command buffer has completed (see g_up_slot_cv)

static pthread_mutex_t g_res_mu = PTHREAD_MUTEX_INITIALIZER;   // Dedicated lock for the residency set: res_add is called on paths that hold g_mu (arena_new), so it cannot share g_mu
static NSHashTable *g_res_objects;
/* TOTK residency accounting by registration site. The four macOS kernel panics (IOGPUFamily, after kIOReturnNoMemory)
   all show ~15 GB of wired memory on the 16 GB machine with totk-native on the Metal submission queue: the driver ran out
   of memory wiring what this residency set made resident. Live resident bytes are attributed to the res_add source line
   so unbounded growth can be located, and gpu_budget_check refuses to go on past a budget instead of handing it to the driver. */
#define RES_SITES 8192
static struct { uint64_t adds, removes, live_bytes; _Atomic uint64_t alive, alive_bytes; } g_res_site[RES_SITES];   // alive*: objects not yet deallocated (whether or not still resident)
/* Deallocation probe: an associated object whose dealloc runs when the Metal object itself is freed, so "removed from the
   residency set but still alive" (retained elsewhere) can be told apart from "freed". */
@interface NvAllocTrack : NSObject { @public int site; uint64_t bytes; } @end
@implementation NvAllocTrack
- (void)dealloc { atomic_fetch_sub(&g_res_site[site].alive, 1); atomic_fetch_sub(&g_res_site[site].alive_bytes, bytes); }   // runs while g_res_mu may be held (the residency set can hold the last reference): no lock here
@end
static char g_alloc_track_key;
static NSMapTable *g_res_site_of;   // resource (weak key) -> NSNumber source line
static uint64_t g_res_live_bytes;
static uint64_t g_res_dedup_skips, g_res_commits, g_res_commits_async;   // under g_res_mu
static _Atomic uint64_t g_res_commit_calls, g_res_removal_waits;      // res_commit calls; calls that left removal-only changes for later
static int res_dedup_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("TOTK_RES_DEDUP"); v = !(e && !strcmp(e, "0")); MLOG("TOTK_RES_DEDUP=%d: %s", v, v ? "re-adding a member or removing a non-member no longer marks the residency set for a commit" : "every add / remove marks the residency set for a commit (old)"); }
    return v;
}
static void res_add_at(id<MTLResource> r, int site) {
    if (!r) return;
    if (site < 0 || site >= RES_SITES) site = 0;
    pthread_mutex_lock(&g_res_mu);
    if (!g_res_objects) { g_res_objects = [NSHashTable weakObjectsHashTable]; g_res_site_of = [NSMapTable weakToStrongObjectsMapTable]; }
    /* TOTK (tvc97 3a5d46f, after nxnative df7badd): g_res_objects mirrors g_res exactly (only res_add_at / res_remove_body
       change g_res; an object in g_res is alive, so its weak entry is there). Adding a member again changes nothing and no
       longer marks the set for a commit. TOTK_RES_DEDUP=0 restores the old always-dirty path. */
    if (res_dedup_on() && [g_res_objects containsObject:r]) { g_res_dedup_skips++; pthread_mutex_unlock(&g_res_mu); return; }
    [g_res addAllocation:(id<MTLAllocation>)r];
    if (![g_res_objects containsObject:r]) {
        uint64_t sz = (uint64_t)r.allocatedSize;
        [g_res_objects addObject:r]; [g_res_site_of setObject:@(site) forKey:r];
        g_res_site[site].adds++; g_res_site[site].live_bytes += sz; g_res_live_bytes += sz;
        if (!objc_getAssociatedObject(r, &g_alloc_track_key)) {
            NvAllocTrack *tr = [NvAllocTrack new]; tr->site = site; tr->bytes = sz; atomic_fetch_add(&g_res_site[site].alive, 1); atomic_fetch_add(&g_res_site[site].alive_bytes, sz);
            objc_setAssociatedObject(r, &g_alloc_track_key, tr, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }
    atomic_fetch_or(&g_res_dirty, RES_DIRTY_ADD);
    pthread_mutex_unlock(&g_res_mu);
}
#define res_add(r) res_add_at((r), __LINE__)
static void res_remove_body(id<MTLResource> r) {
    if (!r) return;
    pthread_mutex_lock(&g_res_mu);
    if (res_dedup_on() && ![g_res_objects containsObject:r]) { g_res_dedup_skips++; pthread_mutex_unlock(&g_res_mu); return; }   // not a member: nothing to remove (see res_add_at)
    [g_res removeAllocation:(id<MTLAllocation>)r];
    if ([g_res_objects containsObject:r]) {
        int site = ((NSNumber *)[g_res_site_of objectForKey:r]).intValue; uint64_t sz = (uint64_t)r.allocatedSize;
        g_res_site[site].removes++; g_res_site[site].live_bytes -= sz < g_res_site[site].live_bytes ? sz : g_res_site[site].live_bytes;
        g_res_live_bytes -= sz < g_res_live_bytes ? sz : g_res_live_bytes;
        [g_res_objects removeObject:r]; [g_res_site_of removeObjectForKey:r];
    }
    atomic_fetch_or(&g_res_dirty, RES_DIRTY_REMOVE);
    pthread_mutex_unlock(&g_res_mu);
}
static int g_res_remove_no_pool; // GPU probe negative control only
static void res_remove(id<MTLResource> r) {
    if (!r) return;
    if (g_res_remove_no_pool) { res_remove_body(r); return; }
    /* Pool/texture finalization also runs on long-lived guest threads outside
       mtl_sub_begin/commit's autorelease scope. Foundation/Metal removal leaves
       temporary references there: S020 had 6104 removed pool wrappers still
       alive. Drain this call's temporaries; explicit owners, deferred fences and
       residency commit ordering remain responsible for resource lifetime. */
    @autoreleasepool { res_remove_body(r); }
}
/* Top registration sites by live resident bytes (caller must not hold g_res_mu). */
static void res_site_report(int top) {
    pthread_mutex_lock(&g_res_mu);
    uint64_t total = g_res_live_bytes; unsigned long nobj = (unsigned long)g_res_objects.count;
    int order[RES_SITES]; int n = 0;
    for (int i = 0; i < RES_SITES; i++) if (g_res_site[i].adds) order[n++] = i;
    for (int i = 1; i < n; i++) { int k = order[i], j = i; while (j > 0 && atomic_load(&g_res_site[order[j - 1]].alive_bytes) < atomic_load(&g_res_site[k].alive_bytes)) { order[j] = order[j - 1]; j--; } order[j] = k; }
    MLOG("Residency set breakdown: %lu objects, %llu MB by size at registration, GPU allocated %llu MB (by nvn_mtl.m registration line, live bytes descending)", nobj, (unsigned long long)(total >> 20), (unsigned long long)(g_dev.currentAllocatedSize >> 20));
    for (int i = 0; i < n && i < top; i++) {
        int k = order[i];
        MLOG("  line %d: resident %llu objects %llu MB (added %llu times, removed %llu times); objects not freed %llu, %llu MB", k, (unsigned long long)(g_res_site[k].adds - g_res_site[k].removes), (unsigned long long)(g_res_site[k].live_bytes >> 20),
             (unsigned long long)g_res_site[k].adds, (unsigned long long)g_res_site[k].removes, (unsigned long long)atomic_load(&g_res_site[k].alive), (unsigned long long)(atomic_load(&g_res_site[k].alive_bytes) >> 20));
    }
    pthread_mutex_unlock(&g_res_mu);
}
/* GPU memory budget: TOTK_GPU_BUDGET_MB, default half of physical memory on the Mac (0 disables; 40% until 2026-10-28, when it stopped an 18 GB M3 Pro at
   8.1 GB, far from the ~15 GB of the kernel panics). Checked before every
   submission and residency commit, in the no-submit mode too, so the growth is reported with its sites instead of
   exhausting wired memory. Off by default on iOS: there the system's per-app limit bounds GPU memory and ends only the app,
   and 40% of an iPhone 14 (2284 MB) stopped the game in the world while it used 3.6 of its 4 GB (2026-10-19). */
static uint64_t gpu_budget_bytes(void) {
    static uint64_t b; static int init;
    if (!init) {
        init = 1; const char *e = getenv("TOTK_GPU_BUDGET_MB");
        if (e) b = strtoull(e, NULL, 10) << 20;
        else if (TARGET_OS_IPHONE) b = 0;
        else { uint64_t phys = 0; size_t n = sizeof phys; if (sysctlbyname("hw.memsize", &phys, &n, NULL, 0) || !phys) MDIE("hw.memsize unavailable for the GPU memory budget"); b = phys / 2; }
        MLOG("GPU memory budget %llu MB (override with TOTK_GPU_BUDGET_MB, 0 disables)", (unsigned long long)(b >> 20));
    }
    return b;
}
/* For the settings menu's memory meter: what the GPU has allocated and the budget the game stops at (0: none). */
void mtl_gpu_memory(uint64_t *used, uint64_t *budget) { *used = g_dev ? (uint64_t)g_dev.currentAllocatedSize : 0; *budget = gpu_budget_bytes(); }
static void defer_drain(void);
static void stor_dump_(int force);
/* The hard stop (2026-10-28): the budget above is where the game starts releasing what it can and reports what grows;
   only past this one does it stop. A boss fight never seen before reached 10.1 GB on the 18 GB M3 Pro (render targets
   swinging 1 -> 7 GB and back) and was stopped at the 9216 MB budget; upstream (1dcf40d) dropped the guard entirely,
   but the four kernel panics happened at about 15 GB wired, so a runaway still has to end the game before that.
   TOTK_GPU_HARD_MB overrides; default three quarters of physical memory (13824 MB on 18 GB), never below the budget. */
static uint64_t gpu_hard_bytes(void) {
    static uint64_t h; static int init;
    if (!init) {
        init = 1; const char *e = getenv("TOTK_GPU_HARD_MB");
        if (e) h = strtoull(e, NULL, 10) << 20;
        else { uint64_t phys = 0; size_t n = sizeof phys; if (!sysctlbyname("hw.memsize", &phys, &n, NULL, 0)) h = phys / 4 * 3; }
        if (h < gpu_budget_bytes()) h = gpu_budget_bytes();
        MLOG("GPU memory hard stop %llu MB (over the budget the game releases what it can and goes on; override with TOTK_GPU_HARD_MB)", (unsigned long long)(h >> 20));
    }
    return h;
}
static _Atomic uint64_t g_budget_soft_until;   // over the budget but under the hard stop: no new wait for the running work until then
static void gpu_budget_check(const char *where) {
    uint64_t budget = gpu_budget_bytes(); if (!budget) return;
    uint64_t cur = (uint64_t)g_dev.currentAllocatedSize, now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (cur <= budget) { if (atomic_load_explicit(&g_budget_relief, memory_order_relaxed)) atomic_store(&g_budget_relief, 0); return; }
    /* What can be released goes before the game is stopped: old-size render targets (stor_sweep, at the end of this
       submission), cached interpolators of other sizes and retired MetalFX objects (mfx_present_tick). Nothing is released
       here (callers may hold g_mu); they free once the GPU is done with them, so an overrun of up to 10% is tolerated for
       up to three seconds after the first request. */
    uint64_t asked = atomic_load(&g_budget_relief);
    if (!asked) { atomic_store(&g_budget_relief, now); asked = now; MLOG("%s: GPU allocated %llu MB over the budget of %llu MB: releasing old-size render targets and cached MetalFX objects first", where, (unsigned long long)(cur >> 20), (unsigned long long)(budget >> 20)); }
    if (cur <= budget / 10 * 11 && now - asked < 3000000000ull) return;
    if (cur <= gpu_hard_bytes() && now < atomic_load(&g_budget_soft_until)) return;   // looked at less than a second ago
    /* TOTK_MFX: optional frame interpolation / per-object motion go first (paused near the budget at each present,
       mfx_present_tick); an overrun of at most 5% while they are being released does not stop the game. */
    if (cur <= budget / 20 * 21 && mfx_budget_grace(cur, budget)) {
        static uint64_t said; if (!said++ || said % 256 == 0) MLOG("[mfx] %s: GPU allocated %llu MB over the budget of %llu MB while frame interpolation is released; going on", where, (unsigned long long)(cur >> 20), (unsigned long long)(budget >> 20));
        return;
    }
    /* (upstream #614 / #616) Part of the overrun can be objects already retired and the staging of submissions still on the
       GPU, both freed when those submissions complete. Let the running work complete and release what it held (at most
       2 s; it stops early once nothing more completes), then look again: only memory still allocated after that stops the
       game. The submission being built is not committed yet, so its own fence is never waited for. */
    const uint64_t first = cur, t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    uint64_t done = __atomic_load_n(&g_done, __ATOMIC_ACQUIRE), quiet = t0;
    for (;;) {
        defer_drain();
        cur = (uint64_t)g_dev.currentAllocatedSize; if (cur <= budget) break;
        uint64_t t = clock_gettime_nsec_np(CLOCK_UPTIME_RAW), d = __atomic_load_n(&g_done, __ATOMIC_ACQUIRE);
        if (d != done || atomic_load(&g_q4_inflight)) { done = d; quiet = t; }
        else if (t - quiet > 20000000ull) break;   // nothing is running or completing any more
        if (t - t0 > 2000000000ull) break;
        usleep(500);
    }
    double waited_ms = (clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0) / 1e6;
    if (cur <= budget) {
        static unsigned spikes; spikes++;
        if (spikes <= 8 || spikes % 100 == 0)
            MLOG("GPU memory briefly over the budget (%u times, %s): %llu MB, %llu MB after the running submissions completed and retired objects were released, waited %.1f ms (budget %llu MB)",
                 spikes, where, (unsigned long long)(first >> 20), (unsigned long long)(cur >> 20), waited_ms, (unsigned long long)(budget >> 20));
        return;
    }
    if (cur <= gpu_hard_bytes()) {
        /* Over the budget, under the hard stop: go on, looking again (with the wait above) at most once a second so
           submissions are not held. The first time per episode the sites are reported, so what grew can be found. */
        static uint64_t episodes, said, last_episode_asked;
        int first = last_episode_asked != asked; last_episode_asked = asked;
        atomic_store(&g_budget_soft_until, clock_gettime_nsec_np(CLOCK_UPTIME_RAW) + 1000000000ull);
        if (first) { episodes++; res_site_report(8); stor_dump_(1); }
        if (first || ++said % 30 == 0)
            MLOG("%s: GPU allocated %llu MB over the budget of %llu MB, under the hard stop of %llu MB: going on (episode %llu)", where, (unsigned long long)(cur >> 20), (unsigned long long)(budget >> 20),
                 (unsigned long long)(gpu_hard_bytes() >> 20), (unsigned long long)episodes);
        return;
    }
    res_site_report(16);
    MDIE("%s: GPU allocated %llu MB exceeds the hard stop of %llu MB (%llu MB before waiting %.1f ms for the running submissions and retired objects); all four kernel panics happened at about 15 GB resident, refusing to keep submitting (adjust with TOTK_GPU_HARD_MB)",
         where, (unsigned long long)(cur >> 20), (unsigned long long)(gpu_hard_bytes() >> 20), (unsigned long long)(first >> 20), waited_ms);
}
// DM_RES_CHECK=1 (diagnostic): if textures / buffers the shader accesses through the argument block are not in the residency set, print the first 40 (textures are attributed to the actual allocation via parent texture / underlying buffer)
static int g_res_check_on;
static void res_check(id r, const char *what, int reg) {
    static int nbad;
    if (!g_res_check_on || !r || nbad >= 40) return;
    int is_tex = [r conformsToProtocol:@protocol(MTLTexture)], is_buf = [r conformsToProtocol:@protocol(MTLBuffer)];
    if (!is_tex && !is_buf) return;   // Samplers etc. are not allocations
    id<MTLResource> a = r; int hops = 0;
    if (is_tex) { id<MTLTexture> t = (id<MTLTexture>)a; while (t.parentTexture) { t = t.parentTexture; hops++; } a = t.buffer ? (id<MTLResource>)t.buffer : (id<MTLResource>)t; }
    pthread_mutex_lock(&g_res_mu); int ok = [g_res_objects containsObject:a]; pthread_mutex_unlock(&g_res_mu);
    if (!ok) { nbad++; id<MTLTexture> t = is_tex ? (id<MTLTexture>)r : nil;
        MLOG("[red] missing residency #%d: %s slot %d %s %p (parent chain %d deep) allocated %lu B storage %lu%s", nbad, what, reg, is_tex ? "texture" : "buffer", (__bridge void *)a, hops, (unsigned long)a.allocatedSize, (unsigned long)a.storageMode,
             t ? [NSString stringWithFormat:@" format %lu %lux%lu type %lu usage %#lx", (unsigned long)t.pixelFormat, (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.textureType, (unsigned long)t.usage].UTF8String : ""); }
}
/* TOTK_RES_BATCH (default 1): res_commit, called before every command buffer commit (each mid-submission chunk split in
   rp_begin_ex -> chunk_maybe_split -> mtl_sub_split, the end of a submission, uploads, readbacks), commits the residency set
   only when an allocation was added since the last commit. Removals alone wait: the end of the submission hands them to a
   background queue (res_commit_sub_end), so the replay thread no longer pays a kernel call (IOGPUMetalResidencySet commit)
   at a chunk split just because a completion handler retired a texture (defer_drain -> res_remove) meanwhile.
   Why it is equivalent for the GPU: residency sets attached to the queue apply what was committed when each command buffer
   is committed. Additions keep their exact old ordering (committed on the committing thread before the command buffer).
   A removal is only ever made after the submissions that used the allocation completed (defer_obj_release waits for their
   fence), so keeping it resident a little longer is harmless; it only holds the memory wired until the next commit
   (at most about one submission later). TOTK_RES_BATCH=0: every change, removals too, is committed at the next res_commit (old). */
static int res_batch_on(void) {
    static _Atomic int v = -1; int r = atomic_load_explicit(&v, memory_order_relaxed);
    if (r < 0) { const char *e = getenv("TOTK_RES_BATCH"); r = !(e && !strcmp(e, "0")); int expect = -1;
        if (atomic_compare_exchange_strong(&v, &expect, r)) MLOG("TOTK_RES_BATCH=%d: %s", r, r ? "the residency set is committed before a command buffer only when allocations joined it; removals are committed off the replay thread once per submission" : "every residency change is committed before the next command buffer (old)"); }
    return r;
}
static void res_commit(void) {
    atomic_fetch_add_explicit(&g_res_commit_calls, 1, memory_order_relaxed);
    int need = res_batch_on() ? RES_DIRTY_ADD : RES_DIRTY_ADD | RES_DIRTY_REMOVE;
    int d = atomic_load_explicit(&g_res_dirty, memory_order_acquire);
    if (!(d & need)) { if (d) atomic_fetch_add_explicit(&g_res_removal_waits, 1, memory_order_relaxed); return; }   // clean (or removals only): no lock, no ObjC
    gpu_budget_check("commit residency set");   // only when the set may have grown (q4_commit checks every command buffer too)
    pthread_mutex_lock(&g_res_mu);
    if (atomic_load_explicit(&g_res_dirty, memory_order_relaxed) & need) { if (!nogpu()) [g_res commit]; atomic_store(&g_res_dirty, 0); g_res_commits++; }
    pthread_mutex_unlock(&g_res_mu);
}
/* End of a submission (mtl_sub_commit, before its command buffer is committed): additions as in res_commit; removal-only
   changes go to a background serial queue, at most one commit queued at a time. Every 600 frames: commits per frame. */
static void res_commit_sub_end(uint64_t frame) {
    res_commit();
    static _Atomic int queued;
    if (res_batch_on() && (atomic_load_explicit(&g_res_dirty, memory_order_acquire) & RES_DIRTY_REMOVE) && !atomic_exchange(&queued, 1)) {
        static dispatch_queue_t q; static dispatch_once_t once;
        dispatch_once(&once, ^{ q = dispatch_queue_create("totk.residency-commit", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_USER_INITIATED, 0)); });
        dispatch_async(q, ^{ @autoreleasepool {
            atomic_store(&queued, 0);   // before the commit: a removal made while it runs queues another one
            pthread_mutex_lock(&g_res_mu);
            if (atomic_load_explicit(&g_res_dirty, memory_order_relaxed)) { if (!nogpu()) [g_res commit]; atomic_store(&g_res_dirty, 0); g_res_commits_async++; }
            pthread_mutex_unlock(&g_res_mu);
        } });
    }
    static uint64_t f0 = UINT64_MAX, c0, a0, w0, k0;
    if (f0 == UINT64_MAX || frame < f0) { f0 = frame; pthread_mutex_lock(&g_res_mu); c0 = g_res_commits; a0 = g_res_commits_async; pthread_mutex_unlock(&g_res_mu); w0 = atomic_load(&g_res_removal_waits); k0 = atomic_load(&g_res_commit_calls); return; }
    if (frame < f0 + 600) return;
    pthread_mutex_lock(&g_res_mu); uint64_t c = g_res_commits, a = g_res_commits_async, dd = g_res_dedup_skips; unsigned long nobj = (unsigned long)g_res_objects.count; pthread_mutex_unlock(&g_res_mu);
    uint64_t w = atomic_load(&g_res_removal_waits), k = atomic_load(&g_res_commit_calls); double nf = (double)(frame - f0);
    MLOG("residency frames %llu-%llu (TOTK_RES_BATCH=%d): %.2f commits/frame before command buffers, %.2f removal-only commits/frame in the background, %.2f commit points/frame clean or deferring removals (of %.2f checks/frame); %llu redundant adds/removes skipped so far, %lu objects",
         (unsigned long long)f0, (unsigned long long)frame, res_batch_on(), (double)(c - c0) / nf, (double)(a - a0) / nf, (double)(w - w0) / nf, (double)(k - k0) / nf, (unsigned long long)dd, nobj);
    f0 = frame; c0 = c; a0 = a; w0 = w; k0 = k;
}

@interface NvDeferredRelease : NSObject { @public id object; uint64_t fence; int keep_resident; } @end
@implementation NvDeferredRelease @end
static NSMutableArray<NvDeferredRelease *> *g_deferred;
static pthread_mutex_t g_deferred_mu = PTHREAD_MUTEX_INITIALIZER;
// Deferred release has two meanings that must be kept apart (the root of the GPU memory fault on the first frame on entering Travincal):
//   defer_obj_release = this object is retired: drop the reference after the submissions that used it complete, and remove it from the residency set;
//   defer_obj_unref   = only the reference I hold is no longer wanted, the object itself may still be in use (the view cache of a texture ID may hold the base texture itself): only drop the reference, leave the residency set alone.
// Previously only the former existed: when the view cache was invalidated, a texture that 'is still the current storage of some serial' was also removed from the residency set. Invalidation used to happen only when the base texture was really replaced, so it was never hit;
// after the transparency chain's in-place composite swapped the storage of two textures, each of the two live textures was removed once this way, and afterwards they are used as attachments and sampled every frame as usual - the GPU accesses non-resident memory.
static void defer_obj_release_ex(id obj, int keep_resident) {
    if (!obj) return;
    NvDeferredRelease *d = [NvDeferredRelease new]; d->object = obj; d->fence = g_fence + 1; d->keep_resident = keep_resident;
    pthread_mutex_lock(&g_deferred_mu);
    if (!g_deferred) g_deferred = [NSMutableArray array];
    [g_deferred addObject:d];
    pthread_mutex_unlock(&g_deferred_mu);
}
static void defer_obj_release(id obj) { defer_obj_release_ex(obj, 0); }
static void defer_obj_unref(id obj) { defer_obj_release_ex(obj, 1); }
static void defer_drain(void) { @autoreleasepool {   // also called from GPU completion handlers
    NSMutableArray<NvDeferredRelease *> *ready = [NSMutableArray array];
    pthread_mutex_lock(&g_deferred_mu);
    for (NSInteger i = g_deferred.count - 1; i >= 0; i--) {
        NvDeferredRelease *d = g_deferred[(NSUInteger)i];
        if (d->fence <= g_done) { [ready addObject:d]; [g_deferred removeObjectAtIndex:(NSUInteger)i]; }
    }
    pthread_mutex_unlock(&g_deferred_mu);
    for (NvDeferredRelease *d in ready) {
        id obj = d->object;
        if (!d->keep_resident && [obj conformsToProtocol:@protocol(MTLResource)]) {
            pthread_mutex_lock(&g_res_mu);
            int registered = [g_res_objects containsObject:obj];
            pthread_mutex_unlock(&g_res_mu);
            if (registered) res_remove((id<MTLResource>)obj);
        }
        d->object = nil;
    }
} }

static pthread_mutex_t g_bf_want_mu = PTHREAD_MUTEX_INITIALIZER;
static char **g_bf_want_keys; static size_t g_bf_want_n, g_bf_want_cap; static int g_bf_want_loaded;
void bf_want_note(const char *key) {
    const char *path = getenv("DM_NVN_BF_WANT");
    if (!path || !key || strlen(key) != 16) return;
    for (int i = 0; i < 16; i++) if (!((key[i] >= '0' && key[i] <= '9') || (key[i] >= 'a' && key[i] <= 'f') || (key[i] >= 'A' && key[i] <= 'F'))) return;
    pthread_mutex_lock(&g_bf_want_mu);
    if (!g_bf_want_loaded) {
        FILE *f = fopen(path, "r"); char line[64];
        if (f) { while (fgets(line, sizeof line, f)) { char *e = strpbrk(line, "\r\n"); if (e) *e = 0; if (strlen(line) != 16) continue;
                if (g_bf_want_n == g_bf_want_cap) { g_bf_want_cap = g_bf_want_cap ? g_bf_want_cap * 2 : 64; g_bf_want_keys = realloc(g_bf_want_keys, g_bf_want_cap * sizeof *g_bf_want_keys); }
                g_bf_want_keys[g_bf_want_n++] = strdup(line); } fclose(f); }
        g_bf_want_loaded = 1;
    }
    for (size_t i = 0; i < g_bf_want_n; i++) if (!strcmp(g_bf_want_keys[i], key)) { pthread_mutex_unlock(&g_bf_want_mu); return; }
    if (g_bf_want_n == g_bf_want_cap) { g_bf_want_cap = g_bf_want_cap ? g_bf_want_cap * 2 : 64; g_bf_want_keys = realloc(g_bf_want_keys, g_bf_want_cap * sizeof *g_bf_want_keys); }
    g_bf_want_keys[g_bf_want_n++] = strdup(key);
    FILE *f = fopen(path, "a"); if (f) { fprintf(f, "%s\n", key); fclose(f); }
    pthread_mutex_unlock(&g_bf_want_mu);
}

/* TOTK_REPLAY_FAST (default 1; =0 restores the old paths): one switch for the replay thread's CPU fast paths, so they can
   be A/B'd together (hle_nvn.c reads the same variable for its recording copies). */
static int replay_fast(void) {
    static _Atomic int v = -1; int r = atomic_load_explicit(&v, memory_order_relaxed);
    if (r < 0) { const char *e = getenv("TOTK_REPLAY_FAST"); r = !(e && !atoi(e)); atomic_store_explicit(&v, r, memory_order_relaxed); }
    return r;
}
// ---------- Memory pools ----------
static pidx g_pools;                            // TOTK: sorted by address (nvn_pool_index.h); buf is a non-owning (__bridge) id<MTLBuffer>
static pidx_query_cache g_pool_queries;          // all accesses hold g_mu, including invalidation and stats
static _Atomic int g_pool_query_on = -1, g_pool_query_check;
static uint64_t g_pool_query_checked;
/* TOTK: the replay resolves dozens of buffer addresses per draw (12k draws a frame in a shrine); each lookup took g_mu and
   searched the index, 0.5 ms of the submit thread a frame (Time Profiler, 1.4.3 shrine, 2026-10-21; about half of it the
   lock). Each thread keeps the last pools it resolved, valid while g_pool_gen (bumped under g_mu on every pool add / remove)
   is unchanged. Only a pool no other pool overlaps is kept, so a hit is the pool the locked search returns; it is already
   resident (pool_res ran), and only its removal takes it out of the residency set, which bumps the generation.
   TOTK_POOL_TLS=0 or flag pool_tls 0 turns it off; TOTK_POOL_TLS_CHECK=1 or flag pool_tls_check 1 compares every hit with
   the locked search. 32 entries halved the misses (10% -> 5%) but the longer scan cost as much, no net gain (2026-10-23).
   TOTK (port of nxnative 8a4b1dc, 2026-10-23): a first level direct-mapped by 4 KB page (POOL_TLS_PG entries) is looked at
   before the last-hit entry and the 8 recent ones; a hit in the recent list or in the locked search fills it. Uniform rings
   move to a new page every few draws but stay in one pool, so the page table plus the recent list answers more lookups
   without the lock than the 8 entries alone. Same validity rule (generation, non-overlapped pool). TOTK_POOL_PAGE=0 off. */
#define POOL_TLS_N 8
#define POOL_TLS_PG_BITS 10
typedef struct { uintptr_t lo, hi, base; void *buf; uint64_t gpu, gen; } pool_tls_ent;
/* One thread-local block: each _Thread_local variable is its own _tlv_get_addr call on Darwin, and the lookup touched two. */
typedef struct { pool_tls_ent e[POOL_TLS_N]; unsigned next, last; pool_tls_ent pg[1u << POOL_TLS_PG_BITS]; } pool_tls_t;   // next slot to fill; slot of the last hit (looked at first); pg: by 4 KB page
static inline unsigned pool_tls_pg_slot(uintptr_t a) { return (unsigned)(((uint64_t)(a >> 12) * UINT64_C(0x9E3779B97F4A7C15)) >> (64 - POOL_TLS_PG_BITS)); }
static int pool_page_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_POOL_PAGE"); v = !(e && !atoi(e)); } return v; }
static _Thread_local pool_tls_t g_ptls;
static _Atomic uint64_t g_pool_gen = 1;
static _Atomic int g_pool_tls_on = -1, g_pool_tls_check;
static uint64_t g_pool_tls_hits, g_pool_tls_misses, g_pool_tls_verified;   // statistics (the replay thread does nearly all lookups)
/* (upstream TOTK_POOL_HASH, a 256-entry per-thread table by 4 KiB page, is the same idea as TOTK_POOL_PAGE above and is
   not merged: one would only shadow the other.) */
static int pool_tls_on(void) {
    int v = atomic_load_explicit(&g_pool_tls_on, memory_order_relaxed);
    if (v < 0) { const char *e = getenv("TOTK_POOL_TLS"); int want = !(e && !atoi(e)), expected = -1;
        atomic_compare_exchange_strong(&g_pool_tls_on, &expected, want); v = atomic_load(&g_pool_tls_on);
        e = getenv("TOTK_POOL_TLS_CHECK"); if (e && atoi(e)) atomic_store(&g_pool_tls_check, 1); }
    return v;
}
static int pool_query_on(void) {
    int value = atomic_load_explicit(&g_pool_query_on, memory_order_relaxed);
    if (value < 0) {
        const char *env = getenv("TOTK_POOL_QUERY_CACHE");
        int initial = !(env && !atoi(env)), expected = -1;
        atomic_compare_exchange_strong(&g_pool_query_on, &expected, initial);
        value = atomic_load_explicit(&g_pool_query_on, memory_order_relaxed);
    }
    return value;
}
static NSMutableArray *g_keep;                  // Holds the buffer references (pidx_ent has non-owning pointers)
static uint64_t g_pool_adds;

#define C1_BANK_SIZE (4u << 20)
#define C1_DECL_SIZE (64u << 10)
static NSMutableArray *g_c1_banks;
static size_t g_c1_bank_off, g_c1_alloc_bytes, g_c1_data_bytes;
static uint64_t g_c1_count, g_c1_exclusive;
static NSMutableSet<NSString *> *g_c1_full;
static int g_c1_full_valid;
static os_unfair_lock g_c1_lock = OS_UNFAIR_LOCK_INIT;

// DM_UDC_SELFTEST=1 (diagnostic, checks DontCare behavior on a real A19 device): private-storage Depth32Float_Stencil8 / RGBA8 (1952x900) are first cleared to write known values,
// then Load + DontCare without drawing, read back and compared pixel by pixel, printing one result line
static void udc_selftest(void) {
    if (!getenv("DM_UDC_SELFTEST")) return;
    id<MTLCommandQueue> q = [g_dev newCommandQueue];
    for (int depth = 1; depth >= 0; depth--) {
        NSUInteger w = 1952, h = 900;
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:depth ? MTLPixelFormatDepth32Float_Stencil8 : MTLPixelFormatRGBA8Unorm width:w height:h mipmapped:NO];
        td.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; td.storageMode = MTLStorageModePrivate;
        id<MTLTexture> t = [g_dev newTextureWithDescriptor:td];
        id<MTLCommandBuffer> cb = [q commandBuffer];
        for (int pass = 0; pass < 2; pass++) {
            MTLRenderPassDescriptor *rp = [MTLRenderPassDescriptor renderPassDescriptor];
            MTLLoadAction la = pass ? MTLLoadActionLoad : MTLLoadActionClear; MTLStoreAction sa = pass ? MTLStoreActionDontCare : MTLStoreActionStore;
            if (depth) { rp.depthAttachment.texture = t; rp.depthAttachment.loadAction = la; rp.depthAttachment.storeAction = sa; rp.depthAttachment.clearDepth = 0.3125;
                         rp.stencilAttachment.texture = t; rp.stencilAttachment.loadAction = la; rp.stencilAttachment.storeAction = sa; rp.stencilAttachment.clearStencil = 0x5a; }
            else { rp.colorAttachments[0].texture = t; rp.colorAttachments[0].loadAction = la; rp.colorAttachments[0].storeAction = sa; rp.colorAttachments[0].clearColor = MTLClearColorMake(0.2, 0.4, 0.6, 0.8); }
            [[cb renderCommandEncoderWithDescriptor:rp] endEncoding];
        }
        id<MTLBuffer> out = [g_dev newBufferWithLength:w * h * 4 options:MTLResourceStorageModeShared];
        id<MTLBlitCommandEncoder> b = [cb blitCommandEncoder];
        [b copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:out destinationOffset:0
            destinationBytesPerRow:w * 4 destinationBytesPerImage:w * h * 4 options:depth ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone];
        [b endEncoding]; cb_commit(cb); cb_wait(cb);
        const uint32_t *px = out.contents; NSUInteger bad = 0; for (NSUInteger i = 0; i < w * h; i++) if (px[i] != px[0]) bad++;
        MLOG("UDC self-test %s %s %lux%lu first value %08x, differing from first value %lu / %lu", g_dev.name.UTF8String, depth ? "Depth32F_S8" : "RGBA8", (unsigned long)w, (unsigned long)h, px[0], (unsigned long)bad, (unsigned long)(w * h));
    }
}
/* TOTK: GPU keep-alive (default on on the Mac, TOTK_GPU_KEEPALIVE=0 turns it off; off on iOS, TOTK_GPU_KEEPALIVE=1 turns it on). A thread keeps up to two short spin kernels (one
   threadgroup) in flight on its own command queue while the game is submitting frames. The M4 GPU lowers its clock when it
   idles part of each frame: the same compute work took 10.9 ms back to back, 16.8 ms with 10 ms gaps and 10.9 ms again with a
   spinner in the gaps (standalone test). TOTK idles the GPU between frames because it waits for each frame before it submits
   the next, so the frame's GPU work ran ~25% slower (world scene GPU p50 12.1 -> 9.1 ms with the spinner). Costs one GPU core
   and power; it stops when no submission happened for 100 ms.
   The spinner only fills real gaps: it launches a kernel only while none of the game's command buffers is on the GPU
   (g_q4_inflight, counted in q4_commit), one at a time, sized to ~1 ms from its measured GPU time. With the screen locked
   the GPU stopped interleaving the two queues and the old always-two-in-flight 5 ms kernels (about 30 per world frame)
   held every game frame back to ~115 ms; now a game submission waits at most for one short kernel. */
/* 2026-10-20, adaptive: on the M3 Pro (18-core GPU, 120 Hz) the spinner bought nothing (frame p50 10.11 ms off vs 10.12 on)
   while it ran about 3.2 one-millisecond kernels a frame. TOTK_GPU_KEEPALIVE unset or "auto" (default): it starts on and
   hle_nvn.c (ka_auto_frame) measures the game's frame and GPU time with it on and off in alternating windows once the
   world is up, keeps whichever is faster (on needs a 3% gain) and checks again every few minutes. =1: always on (the
   behaviour before), =0: off. */
static _Atomic int g_ka_paused;   // the adaptive choice: 1 = idle (thread alive, no kernels)
int mtl_keepalive_mode(void) {    // 0 off, 1 always on, 2 adaptive
    const char *e = getenv("TOTK_GPU_KEEPALIVE");
    if (nogpu() || getenv("TOTK_HEADLESS")) return 0;
    if (!e || !*e || !strcmp(e, "auto")) return 2;
    return atoi(e) ? 1 : 0;
}
void mtl_keepalive_pause(int paused) { atomic_store(&g_ka_paused, paused != 0); }
static _Atomic uint64_t g_last_sub_ns;
// Diagnostic timing controls; defaults retain the existing 1 ms keep-alive.
// The private spin buffer never supplies game data.
static _Atomic int g_ka_target_us = 1000;
static _Atomic uint64_t g_ka_n, g_ka_us, g_ka_max_us;   // spin kernels completed, their summed / longest GPU time (us)
void mtl_keepalive_stats(uint64_t v[3]) { v[0] = atomic_load(&g_ka_n); v[1] = atomic_load(&g_ka_us); v[2] = atomic_exchange(&g_ka_max_us, 0); }
static void keepalive_start(void) {
    static int started;
    if (started || !mtl_keepalive_mode()) return; started = 1;   // not in standalone probes
    NSError *err = nil;
    id<MTLLibrary> lib = [g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\nkernel void keep(device float *a [[buffer(0)]], constant uint &n [[buffer(1)]], uint i [[thread_position_in_grid]]) { float x = a[i]; for (uint j = 0; j < n; j++) x = fma(x, 1.0000001f, 0.5f); a[i] = x; }\n" options:nil error:&err];
    id<MTLComputePipelineState> ps = lib ? [g_dev newComputePipelineStateWithFunction:[lib newFunctionWithName:@"keep"] error:&err] : nil;
    id<MTLCommandQueue> q = [g_dev newCommandQueue]; id<MTLBuffer> buf = [g_dev newBufferWithLength:4096 options:MTLResourceStorageModePrivate];
    if (!ps || !q || !buf) { MLOG("[red] TOTK_GPU_KEEPALIVE: could not build the spin kernel %s", err.localizedDescription.UTF8String); return; }
    { const char *us = getenv("TOTK_GPU_KEEPALIVE_US"); int v = us ? atoi(us) : 0; if (v >= 100 && v <= 1000) atomic_store(&g_ka_target_us, v); }   /* like flag keepalive_us, from the start */
    MLOG("GPU keepalive: short spin kernels (about %d µs each) run continuously on a separate queue so the GPU does not downclock when idle between frames (%s; TOTK_GPU_KEEPALIVE=0 disables, =1 always on)", atomic_load(&g_ka_target_us),
         mtl_keepalive_mode() == 2 ? "adaptive: once in game, measures on / off alternately and keeps the faster" : "always on");
    g_ka_idle = dispatch_semaphore_create(0);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        __block uint32_t n = 40000; dispatch_semaphore_t sem = dispatch_semaphore_create(1);   // ~1 ms on the M4 at full clock
        for (;;) @autoreleasepool {
            int target_us = atomic_load(&g_ka_target_us);
            if (!target_us || atomic_load(&g_ka_paused)) { usleep(TARGET_OS_IPHONE ? 100000 : 2000); continue; }   // iOS: 10 wakeups a second while idle, not 500
            uint64_t last = atomic_load(&g_last_sub_ns);
            if (!last || clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - last > 100000000ull) { usleep(TARGET_OS_IPHONE ? 100000 : 10000); continue; }   // the game is not rendering
            if (atomic_load(&g_q4_inflight) > 0) { dispatch_semaphore_wait(g_ka_idle, dispatch_time(DISPATCH_TIME_NOW, 2 * NSEC_PER_MSEC)); continue; }   // the game's own GPU work keeps the clock up
            dispatch_semaphore_wait(sem, DISPATCH_TIME_FOREVER);
            if (atomic_load(&g_q4_inflight) > 0) { dispatch_semaphore_signal(sem); continue; }
            uint32_t iters = n;
            id<MTLCommandBuffer> cb = [q commandBuffer]; id<MTLComputeCommandEncoder> ce = [cb computeCommandEncoder];
            [ce setComputePipelineState:ps]; [ce setBuffer:buf offset:0 atIndex:0]; [ce setBytes:&iters length:4 atIndex:1];
            [ce dispatchThreads:MTLSizeMake(32, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)]; [ce endEncoding];
            [cb addCompletedHandler:^(id<MTLCommandBuffer> c) { double ms = (c.GPUEndTime - c.GPUStartTime) * 1e3; static int said; if (said++ < 3) MLOG("TOTK_GPU_KEEPALIVE: one spin kernel %.3f ms", ms);
                uint64_t us = (uint64_t)(ms * 1e3); atomic_fetch_add(&g_ka_n, 1); atomic_fetch_add(&g_ka_us, us); uint64_t mx = atomic_load(&g_ka_max_us); while (us > mx && !atomic_compare_exchange_weak(&g_ka_max_us, &mx, us)) {}
                if (ms > 0.01) { double k = (target_us * .001) / ms; if (k > 2) k = 2; if (k < 0.5) k = 0.5; double m = n * k; n = m < 2000 ? 2000 : m > 400000 ? 400000 : (uint32_t)m; }
                dispatch_semaphore_signal(sem); }];
            bg_gate();
            [cb commit];
        }
    });
}
void mtl_init(void) {
    if (g_dev) return;
    if (runtime_boot_status) runtime_boot_status("Creating the Metal device","Preparing the GPU, command queues and graphics resources");
    g_present_probe = getenv("DM_PRESENT_PROBE") != NULL;
    const char *link = getenv("DM_PRESENT_LINK");
    g_dm_present_link = link ? atoi(link) : 1; if (g_dm_present_link < 0 || g_dm_present_link > 2) g_dm_present_link = 1;   // Default 1 (real-device same-process alternation: when load exceeds one display-link period, long frames 15% → 0 and frame intervals even out; no difference from 0 at a steady 60); DM_PRESENT_LINK=0 turns it off   // 1 = present on every tick of a 60 Hz display link; 2 = 120 Hz display link, the game presents a frame every other display-link tick (when behind, it can present on the next 8.33 ms display-link tick)
    const char *latency = getenv("DM_PRESENT_LATENCY");
    if (latency && atoi(latency) > 0) g_present_latency = atoi(latency);
    g_res_check_on = getenv("DM_RES_CHECK") != NULL;
    g_dev = MTLCreateSystemDefaultDevice();
    if (!g_dev) MDIE("No Metal device");
    if (!g_dev.hasUnifiedMemory) MDIE("A unified memory device is required (zero-copy memory pools)");
    g_q = [g_dev newCommandQueue];
    MTLResidencySetDescriptor *rd = [MTLResidencySetDescriptor new];
    rd.initialCapacity = 4096;
    NSError *re = nil;
    g_res = [g_dev newResidencySetWithDescriptor:rd error:&re];
    if (!g_res) MDIE("Failed to create MTLResidencySet");
    [g_q addResidencySet:g_res];
    { void crash_set_wait_dump(void (*fn)(void)); void mtl_wait_state_dump(void); crash_set_wait_dump(mtl_wait_state_dump); }
    dispatch_queue_attr_t feedback_attr = dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_USER_INTERACTIVE, 0);
    g_feedback_q = dispatch_queue_create("dm.nvn.mtl4-feedback", feedback_attr);
    MTL4CommandQueueDescriptor *q4d = [MTL4CommandQueueDescriptor new]; q4d.feedbackQueue = g_feedback_q;
    g_q4 = [g_dev newMTL4CommandQueueWithDescriptor:q4d error:&re];
    if (!g_q4) MDIE("Failed to create MTL4CommandQueue");
    [g_q4 addResidencySet:g_res];
    g_alloc_n = 3;
    for (int i = 0; i < 3; i++) {
        MTL4CommandAllocatorDescriptor *ad = [MTL4CommandAllocatorDescriptor new];
        ad.label = [NSString stringWithFormat:@"nvn-mtl allocator %d", i];
        NSError *ae = nil;
        g_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
        if (!g_alloc4[i]) MDIE("Failed to create MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
        g_up_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
        if (!g_up_alloc4[i]) MDIE("Failed to create upload MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
        MTL4CommandAllocatorDescriptor *pad = [MTL4CommandAllocatorDescriptor new];
        pad.label = [NSString stringWithFormat:@"nvn-mtl present allocator %d", i];
        g_present_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:pad error:&ae];
        if (!g_present_alloc4[i]) MDIE("Failed to create present MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
        g_present_cb[i] = [g_dev newCommandBuffer];
        if (!g_present_cb[i]) MDIE("Failed to create present MTL4CommandBuffer[%d]", i);
    }
    MTL4ArgumentTableDescriptor *atd = [MTL4ArgumentTableDescriptor new];
    atd.maxBufferBindCount = 31; atd.maxTextureBindCount = 1;
    NSError *ate = nil;
    g_vt = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_vt) MDIE("Failed to create vertex argument table: %s", ate.localizedDescription.UTF8String);
    g_ft = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_ft) MDIE("Failed to create fragment argument table: %s", ate.localizedDescription.UTF8String);
    g_ct = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_ct) MDIE("Failed to create compute argument table: %s", ate.localizedDescription.UTF8String);
    g_up_ct = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_up_ct) MDIE("Failed to create upload compute argument table: %s", ate.localizedDescription.UTF8String);
    MTL4ArgumentTableDescriptor *pad = [MTL4ArgumentTableDescriptor new];
    pad.maxTextureBindCount = 1; pad.maxSamplerStateBindCount = 1; pad.maxBufferBindCount = 1;
    g_bloomq_args = [g_dev newArgumentTableWithDescriptor:pad error:&ate];
    if (!g_bloomq_args) MDIE("Failed to create bloom 1/4 argument table: %s", ate.localizedDescription.UTF8String);
    for (int i = 0; i < 3; i++) {
        g_present_args[i] = [g_dev newArgumentTableWithDescriptor:pad error:&ate];
        if (!g_present_args[i]) MDIE("Failed to create present argument table[%d]: %s", i, ate.localizedDescription.UTF8String);
        g_present_uv[i] = [g_dev newBufferWithLength:sizeof(float) * 8 options:MTLResourceStorageModeShared];
        if (!g_present_uv[i]) MDIE("Failed to create present UV buffer[%d]", i);
        res_add(g_present_uv[i]);
        if (g_present_probe) {
            g_present_probe_src[i] = [g_dev newBufferWithLength:128 * 128 * 4 options:MTLResourceStorageModeShared];
            g_present_probe_dst[i] = [g_dev newBufferWithLength:128 * 128 * 4 options:MTLResourceStorageModeShared];
            if (!g_present_probe_src[i] || !g_present_probe_dst[i]) MDIE("Failed to create present probe buffers");
            res_add(g_present_probe_src[i]); res_add(g_present_probe_dst[i]);
        }
        g_bloomq_const[i] = [g_dev newBufferWithLength:sizeof(float) * 8 options:MTLResourceStorageModeShared];
        if (!g_bloomq_const[i]) MDIE("Failed to create bloom 1/4 constant buffer[%d]", i);
        res_add(g_bloomq_const[i]);
        g_fps_uv[i] = [g_dev newBufferWithLength:sizeof(float) * 8 options:MTLResourceStorageModeShared];
        if (!g_fps_uv[i]) MDIE("Failed to create FPS UV buffer[%d]", i);
        res_add(g_fps_uv[i]);
        g_shd_uv[i] = [g_dev newBufferWithLength:sizeof(float) * 8 options:MTLResourceStorageModeShared];
        if (!g_shd_uv[i]) MDIE("Failed to create shader counter box UV buffer[%d]", i);
        res_add(g_shd_uv[i]);
        g_load_uv[i] = [g_dev newBufferWithLength:sizeof(float) * 8 options:MTLResourceStorageModeShared];
        if (!g_load_uv[i]) MDIE("Failed to create load line UV buffer[%d]", i);
        res_add(g_load_uv[i]);
    }
    for (int i = 0; i < 4; i++) {
        MTLTextureDescriptor *fd = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:FPS_OVERLAY_TEX_W height:FPS_OVERLAY_TEX_H mipmapped:NO];
        fd.usage = MTLTextureUsageShaderRead; fd.storageMode = MTLStorageModeShared;
        g_fps_tex[i] = [g_dev newTextureWithDescriptor:fd];
        if (!g_fps_tex[i]) MDIE("Failed to create FPS texture[%d]", i);
        res_add(g_fps_tex[i]);
        MTLTextureDescriptor *sd = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:LOAD_OVERLAY_TEX_W height:FPS_OVERLAY_TEX_H mipmapped:NO];
        sd.usage = MTLTextureUsageShaderRead; sd.storageMode = MTLStorageModeShared;   // shaders and render pipelines in one line (picture corners)
        g_shd_tex[i] = [g_dev newTextureWithDescriptor:sd];
        if (!g_shd_tex[i]) MDIE("Failed to create shader counter box texture[%d]", i);
        res_add(g_shd_tex[i]);
        MTLTextureDescriptor *ld = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:LOAD_OVERLAY_TEX_W height:FPS_OVERLAY_TEX_H mipmapped:NO];
        ld.usage = MTLTextureUsageShaderRead; ld.storageMode = MTLStorageModeShared;
        g_load_tex[i] = [g_dev newTextureWithDescriptor:ld];
        if (!g_load_tex[i]) MDIE("Failed to create load line texture[%d]", i);
        res_add(g_load_tex[i]);
    }
    g_ev = [g_dev newSharedEvent];
    g_keep = [NSMutableArray array];
    g_nvn_deswz_gpu = nvn_deswz_gpu_init(g_dev) == 0;
    dm_res_report_register(mtl_res_counts);
    if (!g_nvn_deswz_gpu) MLOG("[red] GPU deswizzle init failed, pre-swizzled textures fall back to the CPU");
    MLOG("Metal device %s", g_dev.name.UTF8String);
    udc_selftest();
}

void dm_mtl_l3_tick(uint32_t tick) {
    static int leak = -1;
    if (leak < 0) leak = getenv("DM_TEST_LEAK_GPU") != NULL;
    if (leak && tick % 100 == 0) {
        if (!g_l3_gpu_leaks) g_l3_gpu_leaks = [NSMutableArray array];
        id<MTLBuffer> leak = [g_dev newBufferWithLength:1 << 20 options:MTLResourceStorageModeShared];
        if (leak) [g_l3_gpu_leaks addObject:leak];
    }
}

uint64_t dm_mtl_l3_sample(uint32_t tick) {
    (void)tick;
    return g_dev ? g_dev.currentAllocatedSize : 0;
}

static _Atomic uint64_t g_reg_gen = 1;   // Change generation of memory pool / texture / sampler registration: one of the invalidation conditions for argument buffer reuse
/* TOTK safety guard: twice a full-game run kernel-panicked macOS inside IOGPUFamily right after the driver returned
   kIOReturnNoMemory. A zero-copy buffer makes the whole range resident, so ranges with inaccessible pages (sparse
   virtual pools) or very large ranges are refused here, with details, instead of being handed to the driver. */
#include "mach_vm_compat.h"
/* 1 GiB; 4 GiB with TOTK_DRAM_8GB (the 8 GB pool for big texture packs, whose TextureHeap pool is ~3.8 GiB); or TOTK_POOL_BUFFER_MAX_MB (at most 2048): the launcher allows 2 GiB only for a 3D world above 1440p (settings:
   Maximum render resolution), whose texture heap passes 1 GiB. That heap holds textures, which are separate Metal textures
   here, so its zero-copy buffer is not made resident unless the GPU reads a buffer address in it (pool_res logs it). */
static uint64_t pool_buffer_max(void) {
    static uint64_t v;
    if (!v) {
        const char *e = getenv("TOTK_POOL_BUFFER_MAX_MB"); long mb = e ? atol(e) : 0;
        v = (mb >= 1024 && mb <= 2048 ? (uint64_t)mb : 1024) << 20;
        { const char *d = getenv("TOTK_DRAM_8GB"); if (d && *d && strcmp(d, "0") && v < (4ull << 30)) v = 4ull << 30; }
        if (v > (1ull << 30)) MLOG("memory pools: zero-copy GPU buffers up to %llu MiB (TOTK_POOL_BUFFER_MAX_MB)", (unsigned long long)(v >> 20));
    }
    return v;
}
#define POOL_BUFFER_MAX pool_buffer_max()
static void pool_range_check(uintptr_t a, uintptr_t b, const void *mem, uint64_t size) {
    if (b - a > POOL_BUFFER_MAX) MDIE("memory pool %p+%#llx: %llu MiB zero-copy GPU buffer refused (limit %llu MiB)", mem, (unsigned long long)size,
                                      (unsigned long long)((b - a) >> 20), POOL_BUFFER_MAX >> 20);
    for (mach_vm_address_t at = a; at < b;) {
        mach_vm_address_t ra = at; mach_vm_size_t rs = 0; vm_region_basic_info_data_64_t ri; mach_msg_type_number_t rc = VM_REGION_BASIC_INFO_COUNT_64; mach_port_t ro = MACH_PORT_NULL;
        if (mach_vm_region(mach_task_self(), &ra, &rs, VM_REGION_BASIC_INFO_64, (vm_region_info_t)&ri, &rc, &ro) != KERN_SUCCESS || ra > at)
            MDIE("memory pool %p+%#llx: unmapped hole at %#llx refused for a zero-copy GPU buffer", mem, (unsigned long long)size, (unsigned long long)at);
        if ((ri.protection & (VM_PROT_READ | VM_PROT_WRITE)) != (VM_PROT_READ | VM_PROT_WRITE)) {
            /* TOTK: pages our own dirty tracker write-protected (CPU-visible pool memory that is really read-write) are fine: they are
               mapped and resident, only the CPU page tables carry the temporary read-only bit. Anything else stays refused. */
            uintptr_t lo = ra < a ? a : (uintptr_t)ra, hi = ra + rs > b ? b : (uintptr_t)(ra + rs);
            if ((ri.protection & VM_PROT_READ) && hi > lo && nvn_dirty_tracked((const void *)lo, hi - lo)) {
                static int said; if (said++ < 4) MLOG("memory pool %p+%#llx: pages at %#llx+%#llx are write-protected by the dirty tracker; accepted for the zero-copy GPU buffer", mem, (unsigned long long)size, (unsigned long long)lo, (unsigned long long)(hi - lo));
            } else
            MDIE("memory pool %p+%#llx: pages at %#llx+%#llx have protection %d, refused for a zero-copy GPU buffer", mem, (unsigned long long)size,
                 (unsigned long long)ra, (unsigned long long)rs, ri.protection);
        }
        at = ra + rs;
    }
}
/* TOTK, from D2R Mobile e2a0c9a: a memory pool's zero-copy buffer enters the residency set only when the GPU first gets one
   of its addresses (mtl_addr / mtl_gpu_addr are the only ways it does), and the residency set is committed on the spot, so it
   is committed before any command buffer that can use the buffer. Residency pins every page of the buffer (on iOS they become
   wired and can never be paged out), also for pools the GPU never reads: textures in GPU pools are separate Metal textures
   here, so pools holding only texture data do not need it. TOTK_POOL_RES_ALL=1 makes pools resident when created (old). */
static uint64_t g_pool_bytes, g_pool_res_n, g_pool_res_bytes;   // registered pool bytes; live pools / bytes in the residency set (under g_mu)
static int pool_res_all(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("TOTK_POOL_RES_ALL"); v = e && atoi(e); if (v) MLOG("TOTK_POOL_RES_ALL=1: memory pools join the residency set as soon as they are created (for comparison)"); }
    return v;
}
static void pool_res(pidx_ent *p) {   // caller holds g_mu
    if (p->res) return;
    res_add((__bridge id<MTLBuffer>)p->buf); res_commit();
    p->res = 1; g_pool_res_n++; g_pool_res_bytes += p->hi - p->lo;
    if (p->hi - p->lo > (1ull << 30)) MLOG("memory pool of %llu MiB made resident (the GPU read a buffer address in it): above the old 1 GiB limit",
                                           (unsigned long long)((p->hi - p->lo) >> 20));
}
void mtl_pool_res_stats(uint64_t v[4]) {   // registered pools, their bytes, pools / bytes in the residency set
    pthread_mutex_lock(&g_mu); v[0] = (uint64_t)g_pools.n; v[1] = g_pool_bytes; v[2] = g_pool_res_n; v[3] = g_pool_res_bytes; pthread_mutex_unlock(&g_mu);
}
void mtl_pool_add(const void *mem, uint64_t size) {
    mtl_init(); g_reg_gen++;
    uintptr_t pg = (uintptr_t)getpagesize(), lo = (uintptr_t)mem, hi = lo + size;
    uintptr_t a = lo & ~(pg - 1), b = (hi + pg - 1) & ~(pg - 1);
    pool_range_check(a, b, mem, size);
    id<MTLBuffer> buf = [g_dev newBufferWithBytesNoCopy:(void *)a length:b - a options:MTLResourceStorageModeShared deallocator:nil];
    /* TOTK (2026-10-24, crash at boot 12:36): Metal refused the zero-copy buffer while pipelining had pages of the range
       write-protected (a guest thread was faulting on one at the same moment). Retry with the tracked pages writable for
       the call (nvn_dirty_gpu_write_begin / _end restore them), then a few more times before giving up. */
    for (int k = 0; !buf && k < 8; k++) {
        void *tok = nvn_dirty_tracked((void *)a, b - a) ? nvn_dirty_gpu_write_begin((void *)a, b - a) : NULL;
        buf = [g_dev newBufferWithBytesNoCopy:(void *)a length:b - a options:MTLResourceStorageModeShared deallocator:nil];
        nvn_dirty_gpu_write_end(tok);
        MLOG("[red] memory pool %p+%#llx: zero-copy buffer retry %d %s (protected pages %s)", mem, (unsigned long long)size, k + 1, buf ? "succeeded" : "failed", tok ? "opened for the call" : "none");
        if (!buf) usleep(2000 << k);
    }
    if (!buf) MDIE("Memory pool %p+%#llx: failed to create the zero-copy buffer", mem, (unsigned long long)size);
    pthread_mutex_lock(&g_mu);
    if (pidx_overlaps(&g_pools, lo, hi)) { static int said; if (said++ < 8) MLOG("memory pool %p+%#llx overlaps a registered pool (%d live)", mem, (unsigned long long)size, g_pools.n); }
    pidx_ent ent = {lo, hi, a, (__bridge void *)buf, buf.gpuAddress, mem, 0};
    if (pool_res_all()) { res_add(buf); ent.res = 1; g_pool_res_n++; g_pool_res_bytes += hi - lo; }
    if (!pidx_insert(&g_pools, &ent)) MDIE("Failed to grow the memory pool table (%d entries)", g_pools.n);
    pidx_query_invalidate(&g_pool_queries); atomic_fetch_add_explicit(&g_pool_gen, 1, memory_order_release);
    g_pool_adds++; g_pool_bytes += hi - lo;
    [g_keep addObject:buf];
    pthread_mutex_unlock(&g_mu);
}

static void stor_drop_range(uintptr_t lo, uintptr_t hi);
static void wb_drop_range(uintptr_t lo, uintptr_t hi);
static void stor_sweep(uint64_t fence);
void mtl_pool_del(const void *mem) {
    g_reg_gen++;
    uintptr_t lo = 0, hi = 0;
    pthread_mutex_lock(&g_mu);
    pidx_ent ent;
    if (pidx_remove(&g_pools, mem, &ent)) {
        pidx_query_invalidate(&g_pool_queries); atomic_fetch_add_explicit(&g_pool_gen, 1, memory_order_release);
        __unsafe_unretained id<MTLBuffer> buf = (__bridge id<MTLBuffer>)ent.buf;
        lo = ent.lo; hi = ent.hi; g_pool_bytes -= hi - lo;
        if (ent.res) { res_remove(buf); g_pool_res_n--; g_pool_res_bytes -= hi - lo; }
        [g_keep removeObjectIdenticalTo:buf];
    }
    pthread_mutex_unlock(&g_mu);
    if (hi > lo) { stor_drop_range(lo, hi); wb_drop_range(lo, hi); BOTW_LATE_DROP(lo, hi) }   // TOTK: storage-shared textures and pending write-backs of this pool
}

static pidx_ent *pool_query(uintptr_t addr, uint64_t len) { // caller holds g_mu
    if (!pool_query_on()) return pidx_find_mut(&g_pools, addr, len);
    pidx_ent *p = pidx_find_cached(&g_pools, &g_pool_queries, addr, len);
    if (atomic_load_explicit(&g_pool_query_check, memory_order_relaxed)) {
        if (p != pidx_find_mut(&g_pools, addr, len)) MDIE("pool query cache disagrees at %#llx+%#llx", (unsigned long long)addr, (unsigned long long)len);
        g_pool_query_checked++;
    }
    return p;
}
static const pool_tls_ent *pool_tls_find(uintptr_t a, uint64_t len) {
    uintptr_t end = a + (uintptr_t)len;
    if (end < a) return NULL;
    uint64_t gen = atomic_load_explicit(&g_pool_gen, memory_order_acquire);
    pool_tls_t *t = &g_ptls;
    int pg = pool_page_on();
    pool_tls_ent *ps = pg ? &t->pg[pool_tls_pg_slot(a)] : NULL;
    if (ps && ps->gen == gen && ps->lo <= a && a < ps->hi && end <= ps->hi) return ps;
    const pool_tls_ent *e = &t->e[t->last];
    if (e->gen == gen && e->lo <= a && a < e->hi && end <= e->hi) { if (ps) *ps = *e; return e; }   // a < hi: an address at the end may also start the next pool
    for (unsigned i = 0; i < POOL_TLS_N; i++) {
        e = &t->e[i];
        if (e->gen == gen && e->lo <= a && a < e->hi && end <= e->hi) { t->last = i; if (ps) *ps = *e; return e; }
    }
    return NULL;
}
static void pool_tls_keep(const pidx_ent *p, uintptr_t addr) {   // caller holds g_mu; p was just made resident and holds addr
    int i = (int)(p - g_pools.e);
    if (i < 0 || i >= g_pools.n) return;
    if (i > 0 && g_pools.maxhi[i - 1] > p->lo) return;          // an earlier pool reaches into this one
    if (i + 1 < g_pools.n && g_pools.e[i + 1].lo < p->hi) return; // a later pool starts inside this one
    pool_tls_t *t = &g_ptls;
    pool_tls_ent c = {p->lo, p->hi, p->base, p->buf, p->gpu, atomic_load_explicit(&g_pool_gen, memory_order_relaxed)};
    t->e[t->next++ % POOL_TLS_N] = c;
    if (pool_page_on() && addr >= p->lo && addr < p->hi) t->pg[pool_tls_pg_slot(addr)] = c;
}
/* TOTK frames in flight (TOTK_FRAMES_IN_FLIGHT=2, see fif_commit): while a submission is replayed, every memory pool it
   looks up is noted, so at commit the pools the GPU reads straight from guest memory get the submission's fence. */
static __thread int t_fif_rec;
static void fif_note_pool(uintptr_t lo, uintptr_t hi);
// The locked search; with keep, a pool it finds is remembered by this thread.
static int pool_lookup_locked(uint64_t addr, uint64_t len, void **buf, uint64_t *base, uint64_t *gpu, int keep) {
    pthread_mutex_lock(&g_mu);
    pidx_ent *p = pool_query((uintptr_t)addr, len);
    if (p) { pool_res(p); *buf = p->buf; *base = p->base; *gpu = p->gpu; if (keep) pool_tls_keep(p, (uintptr_t)addr); if (t_fif_rec) fif_note_pool(p->lo, p->hi); }
    pthread_mutex_unlock(&g_mu);
    return p != NULL;
}
static int pool_lookup(uint64_t addr, uint64_t len, void **buf, uint64_t *base, uint64_t *gpu) {
    if (!pool_tls_on()) return pool_lookup_locked(addr, len, buf, base, gpu, 0);
    const pool_tls_ent *e = pool_tls_find((uintptr_t)addr, len);
    if (!e) { g_pool_tls_misses++; return pool_lookup_locked(addr, len, buf, base, gpu, 1); }
    g_pool_tls_hits++;
    if (t_fif_rec) fif_note_pool(e->lo, e->hi);
    if (atomic_load_explicit(&g_pool_tls_check, memory_order_relaxed)) {
        void *b2; uint64_t base2, gpu2;
        if (!pool_lookup_locked(addr, len, &b2, &base2, &gpu2, 0) || b2 != e->buf || base2 != e->base || gpu2 != e->gpu)
            MDIE("pool lookup cache disagrees at %#llx+%#llx", (unsigned long long)addr, (unsigned long long)len);
        g_pool_tls_verified++;
    }
    *buf = e->buf; *base = e->base; *gpu = e->gpu;
    return 1;
}
/* pool_lookup that answers with the pool's guest range [*lo, *hi) (the uniform capture tests many nearby addresses:
   one inside the last pool found needs no lookup of its own). */
static int mtl_addr_range(uint64_t addr, uint64_t len, uintptr_t *lo, uintptr_t *hi) {
    if (pool_tls_on()) { const pool_tls_ent *e = pool_tls_find((uintptr_t)addr, len); if (e) { *lo = e->lo; *hi = e->hi; return 1; } }
    pthread_mutex_lock(&g_mu);
    pidx_ent *p = pool_query((uintptr_t)addr, len);
    if (p) { pool_res(p); *lo = p->lo; *hi = p->hi; if (pool_tls_on()) pool_tls_keep(p, (uintptr_t)addr); }
    pthread_mutex_unlock(&g_mu);
    return p != NULL;
}
int mtl_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off) {
    uint64_t base, gpu;
    if (!pool_lookup(addr, len, buf, &base, &gpu)) return 0;
    *off = addr - base;
    return 1;
}
int mtl_gpu_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off, uint64_t *gpu) {
    uint64_t base, pgpu;
    if (!pool_lookup(addr, len, buf, &base, &pgpu)) return 0;
    *off = addr - base; *gpu = pgpu + *off;
    return 1;
}

// ---------- Submission ----------
static void defer_reset(void); static void defer_fallback(void);
typedef struct { int kind; volatile uint32_t *val; uint32_t mode, v; uint64_t addr; uint32_t type; void *vis; int qlog; float sph[4]; int has_prev; uint64_t prev[2]; } post_op;   // has_prev / prev: TOTK frames in flight, the destination's bytes at replay (post_stale)   // vis: the visibility slot table for kind 3; qlog / sph: "querylog" diagnostic
static _Atomic int g_occl_vis; static _Atomic long g_ql_until = -1;   // TOTK occlusion diagnostics (see dm_gfx_querylog_next)
void dm_gfx_querylog_next(long n); void dm_gfx_passdump_next(long n); void dm_gfx_texdump_next(const char *path);
// ---------- Occlusion queries (NVN_COUNTER_TYPE_SAMPLES_PASSED) ----------
// NVN semantics: samples passed is a cumulative counter on the queue - ResetCounter zeroes it, every draw afterwards adds to it, and ReportCounter writes out the cumulative value at that moment (+ timestamp) when the GPU completes.
// Metal: every render pass attaches a visibility result buffer; draws during counting use counting mode, with a new slot per pass (no reliance on accumulation across passes); a reset empties the 'slot table since the reset',
// and a report hands the slot table together with its buffer (retained) to the completion callback to sum and write back; after a report a new slot is used, so later draws are not counted into the reported value.
// (Previously always wrote 0: occlusion query = 'fully occluded', campfires / light sources got culled - the character select screen calls ResetCounter 21 times per frame)
typedef struct { void *buf; uint32_t slot, n; } vis_slot;   // n (TOTK_ANOMALY): further consecutive slots of the same buffer counted with it (0 = just this one)
typedef struct { int n, skipped; vis_slot s[]; } vis_list;   // skipped: a counted draw since the reset was skipped (draw_skipped)
#define VIS_SLOTS 8192
typedef struct { __strong id<MTLBuffer> buf; uint64_t fence; } vis_buf;
static vis_buf g_vis_ring[4]; static int g_vis_ring_n, g_vis_ring_i = -1;
typedef struct { int k; uint64_t f; uint32_t i, slot; void *buf; } anom_vis_ent;   // per-draw visibility counters of the submission being encoded
static anom_vis_ent *g_anom_vis; static int g_anom_nvis, g_anom_capvis, g_anom_vis_slot = -1;
typedef struct { uint32_t idx, slot; void *buf; } skv_item;   // TOTK_EXP_SKIP_INVISIBLE (defined with draw_inner): this submission's per-draw counters
static skv_item *g_skv_list; static int g_skv_n, g_skv_cap; static uint64_t g_skv_skipped, g_skv_tested, g_skv_draws, g_skv_retests, g_skv_revived, g_skv_full, g_skv_effects;   // g_skv_effects: draws never skipped because a stage can write memory
static void skv_done(skv_item *l, int n, uint32_t frame);
static int skv_skip_storers(void);   // TOTK_SKIP_STORERS (defined with the skip table)
static int perdraw_vis_on(void);   // TOTK_ANOMALY per-draw counters or the TOTK_EXP_SKIP_INVISIBLE experiment
static int anom_vis_on(void); static void anom_vis_done(anom_vis_ent *e, int n);   // TOTK_ANOMALY (defined with anom_note)
static void anom_note_xfer(char kind, uint64_t src, uint64_t dst, uint64_t n, const void *data);   // TOTK_ANOMALY: inline update / copy in the frame's sequence
static id<MTLBuffer> g_vis; static uint32_t g_vis_n;   // This submission's visibility buffer and number of slots used
static int g_vis_on, g_vis_counting, g_vis_cur = -1; static uint64_t g_vis_cur_pass;
static int g_vis_skipped;                                // a draw counted since the last reset was skipped (its shader or pipeline not ready)
static _Atomic uint64_t g_occl_raised;                   // reports raised from 0 to 1 because of that (completion handler)
static vis_slot *g_vs; static int g_nvs, g_vscap;      // Slots since the last reset
static uint64_t g_cnt_report[32], g_cnt_reset[32];       // Report / reset counts per counter type (diagnostics)
static void vis_clear(void) { for (int i = 0; i < g_nvs; i++) CFRelease(g_vs[i].buf); g_nvs = 0; g_vis_cur = -1; g_vis_skipped = 0; }
static vis_list *vis_snapshot(void) {
    vis_list *l = malloc(sizeof *l + g_nvs * sizeof(vis_slot)); l->n = g_nvs; l->skipped = g_vis_skipped;
    for (int i = 0; i < g_nvs; i++) { l->s[i] = g_vs[i]; CFRetain(g_vs[i].buf); }
    return l;
}
// Target ranges of buffer writes (copies / inline uniform updates) already encoded in this submission but not yet executed on the GPU: reading these addresses on the CPU side at encode time yields old values (uv_proof avoids them when reading uniforms)
#define PEND_MAX 16384
static uint64_t g_pend_lo[PEND_MAX], g_pend_hi[PEND_MAX]; static int g_npend;
static const void *g_pend_src[PEND_MAX]; static uint8_t g_pend_kind[PEND_MAX];   // TOTK: 0 = inline update (host copy of the data), 1 = GPU copy (guest source address)
static uint64_t g_pend_fence[PEND_MAX], g_pend_over_fence;
static int g_usnap_pend_n;   // pend entries present when this submission's uniform snapshot was dispatched: all a snapshot copy may look at (the replay appends entries concurrently with the helper threads)
static _Atomic uint64_t g_usnap_faults;   // snapshot copies that hit an inaccessible address (guarded, the entry is dropped)   // TOTK: a write stays pending until the GPU completed its submission; over_fence: a submission whose writes did not fit the table
static uint64_t g_pend_reuse_done;
static _Atomic int g_pend_arena_pin = 1;
static uint64_t g_pend_arena_hazards;
static int pend_over(void) { return g_pend_over_fence > g_done; }
static int pend_hits(uint64_t a, uint64_t n) { if (pend_over()) return 1; for (int i = 0; i < g_npend; i++) if (a < g_pend_hi[i] && a + n > g_pend_lo[i]) return 1; return 0; }
/* TOTK: bumped whenever a uniform copy made earlier in this replay might no longer equal a fresh one plus the writes
   noted since (upd_shadow's incremental copy, TOTK_SHADOW_INCR): a new submission, the snapshot table rebuilt or a range
   dropped from it, a GPU copy noted (its bytes come from other memory), the table full. */
static uint64_t g_mat_gen;
static void pend_note(uint64_t dst, uint64_t n, const void *src, int kind) {
    if (kind || g_npend >= PEND_MAX) g_mat_gen++;
    if (g_npend < PEND_MAX) { g_pend_lo[g_npend] = dst; g_pend_hi[g_npend] = dst + n; g_pend_src[g_npend] = src; g_pend_kind[g_npend] = (uint8_t)kind; g_pend_fence[g_npend] = g_fence + 1; g_npend++; }
    else g_pend_over_fence = g_fence + 1;
}
/* Submission start: writes of earlier submissions the GPU has not completed yet stay in the table. The game updates
   ring-buffer uniform blocks inline one submission before the draws that read pointers out of them. */
static void pend_begin(void) {
    // Freeze the retirement boundary for the whole CPU replay. Entries retained below
    // still point into old arenas even if their GPU fence completes a moment later.
    g_pend_reuse_done = __atomic_load_n(&g_done, __ATOMIC_ACQUIRE);
    int n = 0;
    for (int i = 0; i < g_npend; i++) if (g_pend_fence[i] > g_pend_reuse_done) {
        if (n != i) { g_pend_lo[n] = g_pend_lo[i]; g_pend_hi[n] = g_pend_hi[i]; g_pend_src[n] = g_pend_src[i]; g_pend_kind[n] = g_pend_kind[i]; g_pend_fence[n] = g_pend_fence[i]; }
        n++;
    }
    g_npend = n; g_mat_gen++;
}
/* TOTK (2026-10-15): uniform contents as of the submit call. A submission is replayed inside nvnQueueSubmitCommands for
   several milliseconds; on the console the call returns at once and the GPU reads the constants soon after. Meanwhile the
   game, having handed the frame over, rebuilds per-object constant pools on other threads (main+0x87a604, called from
   main+0x874f50): draws replayed late in the frame then read another object's matrix -- distant meshes drawn in front of
   the camera while jumping ("rock walls"). So at the start of a submission every uniform range it binds is copied
   (nearby ranges merged) into its arena, and binding, renamed copies (pend_materialize) and pointer reads (pend_read) use
   the copy. A GPU write to a copied range within the submission (buffer copy, writable storage buffer, inline update
   outside the renaming) drops that copy from then on, so later readers see the GPU's result in memory again.
   TOTK_UBO_SNAPSHOT=0 / "flag ubo_snapshot 0" read live memory as before (A/B only). */
/* TOTK (2026-10-16): the copies are filled by helper threads while the replay already runs (usnap_take phase 2, the
   0.23 ms of copying was on the critical path before the first chunk); a binding that needs a copy not ready yet copies
   it itself. Lock-free: an entry's state is claimed with a CAS. PENDING = not copied yet, COPYING = some thread is on it,
   READY, DROPPED = a GPU write of this submission hit it (read memory). Lookups from inside the copy routine never wait
   (they read memory, as the single-threaded version did for entries not yet valid). TOTK_USNAP_HELPERS=0 copies inline. */
enum { US_PENDING, US_COPYING, US_READY, US_DROPPED };
typedef struct { uint64_t lo, hi, gpu; uint8_t *cpu; _Atomic int st; } usnap_t;
static usnap_t *g_usnap; static int g_nusnap, g_capusnap;
static uint64_t g_usnap_waits, g_usnap_self; static _Atomic uint64_t g_usnap_helped;   // bindings that waited for a helper / copied the entry themselves; entries the helpers copied
static _Atomic int g_usnap_on = -1;
static uint64_t g_usnap_bytes, g_usnap_n, g_usnap_drops, g_usnap_subs, g_usnap_ns;
static uint64_t g_usnap_t[3];   // TOTK (2026-10-16): where the snapshot's time goes -- collect+sort / merge / copy (the first-chunk latency work)
// TOTK (2026-10-16): what the GPU waits for at the start of a submission, per phase: [0] mtl_sub_begin, [1] replay up to the
// first chunk split, [2] rs_sync, [3] up_flush, [4] res_commit, [5] end + commit of the first chunk; logged with the snapshot stats
static uint64_t g_fc_t[6], g_fc_n, g_fc_begin0, g_fc_snap_end, g_exp_skip_fs_n;
static int usnap_on(void) {
    int v = atomic_load(&g_usnap_on);
    if (v < 0) { const char *e = getenv("TOTK_UBO_SNAPSHOT"); v = !(e && !strcmp(e, "0")); atomic_store(&g_usnap_on, v); fprintf(stderr, "[dm] [nvn-mtl] uniform contents snapshotted at submit time: %s\n", v ? "on" : "off (reads live memory, old behaviour)"); }
    return v;
}
static int usnap_first(uint64_t a) {   // first region whose end is above a
    int lo = 0, hi = g_nusnap;
    while (lo < hi) { int m = (lo + hi) / 2; if (g_usnap[m].hi <= a) lo = m + 1; else hi = m; }
    return lo;
}
static _Atomic int g_usnap_index_on = -1, g_usnap_index_check;
static uint32_t g_usnap_hint[256]; // indices into the CURRENT sorted snapshot list, never cached GPU addresses
static uint64_t g_usnap_index_hits, g_usnap_index_misses, g_usnap_index_verified;
static int g_usnap_index_negative;
static int usnap_index_on(void) {
    int v=atomic_load(&g_usnap_index_on);
    if(v<0){const char *e=getenv("TOTK_USNAP_INDEX");v=!(e && !atoi(e));atomic_store(&g_usnap_index_on,v);}
    return v;
}
static void usnap_copy_one(usnap_t *c);
static uint64_t usnap_copy_run(_Atomic int *next, int n);
static const usnap_t *usnap_find_slow(uint64_t a, uint64_t n, int wait) {   // wait: copy a pending entry now / wait for a helper (bindings); 0: not ready = not found (copy routine)
    if (!g_nusnap || !n) return NULL;
    int i = usnap_first(a);
    if (!(i < g_nusnap && g_usnap[i].lo <= a && a + n <= g_usnap[i].hi)) return NULL;
    usnap_t *c = &g_usnap[i];
    for (;;) {
        int st = atomic_load_explicit(&c->st, memory_order_acquire);
        if (st == US_READY) return c;
        if (st == US_DROPPED || !wait) return NULL;
        if (st == US_PENDING) { int exp = US_PENDING; if (atomic_compare_exchange_strong(&c->st, &exp, US_COPYING)) { usnap_copy_one(c); g_usnap_self++; } }
        else { g_usnap_waits++; while (atomic_load_explicit(&c->st, memory_order_acquire) == US_COPYING) sched_yield(); }
    }
}
static const usnap_t *usnap_find(uint64_t a, uint64_t n) {   // ready copy holding all of [a, a+n) (made ready here if a helper has not got to it yet)
    if(!usnap_index_on())return usnap_find_slow(a,n,1);
    if(!g_nusnap || !n)return NULL;
    unsigned slot=(unsigned)((a>>12)^(a>>22))&255;
    uint32_t i=g_usnap_hint[slot]-1;
    const usnap_t *c=i<(uint32_t)g_nusnap?&g_usnap[i]:NULL;
    // List rebuilds, reallocations, GPU writes, and hash collisions all recheck
    // the authoritative entry. Snapshot ranges are disjoint, so containment is unique.
    if(c && (atomic_load_explicit(&c->st, memory_order_acquire) == US_READY || g_usnap_index_negative) && c->lo<=a && a<c->hi && n<=c->hi-a) {
        g_usnap_index_hits++;
        if(atomic_load(&g_usnap_index_check)) {
            if(c!=usnap_find_slow(a,n,1))MDIE("uniform snapshot index mismatch");
            g_usnap_index_verified++;
        }
        return c;
    }
    g_usnap_index_misses++;
    c=usnap_find_slow(a,n,1);if(c)g_usnap_hint[slot]=(uint32_t)(c-g_usnap)+1;
    return c;
}
static void usnap_read_x(uint64_t a, void *out, size_t n, int wait) {
    const usnap_t *c = wait ? usnap_find(a, n) : usnap_find_slow(a, n, 0);
    memcpy(out, c ? (const void *)(c->cpu + (a - c->lo)) : (const void *)(uintptr_t)a, n);
}
static void usnap_read(uint64_t a, void *out, size_t n) { usnap_read_x(a, out, n, 1); }
/* Ranges the GPU writes (writable storage buffers, buffer copies, texture-to-buffer copies, inline updates written on the
   GPU timeline), with the fence of their submission: a copy taken at a later submit call while one of them is still
   executing would miss the GPU's result, so such ranges are not copied (they are read on the GPU timeline as before). */
typedef struct { uint64_t lo, hi, fence; } gw_t;
static gw_t *g_gw; static int g_ngw, g_capgw;
static uint64_t g_usnap_skip_gpu;
static int g_usnap_drop_off;   // probe-gpu-ubo-snapshot negative control only
static void usnap_drop(uint64_t a, uint64_t n) {   // the GPU writes [a, a+n) within this submission
    if (!n) return;
    g_mat_gen++;
    if (usnap_on()) {
        int dup = 0;   // the same buffer bound for many dispatches in a row: log it once
        for (int j = g_ngw - 1; j >= 0 && j >= g_ngw - 8; j--) if (g_gw[j].lo == a && g_gw[j].hi == a + n && g_gw[j].fence == g_fence + 1) { dup = 1; break; }
        if (!dup) {
            if (g_ngw == g_capgw) { g_capgw = g_capgw ? g_capgw * 2 : 4096; g_gw = realloc(g_gw, g_capgw * sizeof *g_gw); if (!g_gw) MDIE("GPU write ranges"); }
            g_gw[g_ngw++] = (gw_t){a, a + n, g_fence + 1};
        }
    }
    if (!g_nusnap || g_usnap_drop_off) return;
    for (int i = usnap_first(a); i < g_nusnap && g_usnap[i].lo < a + n; i++) if (atomic_exchange(&g_usnap[i].st, US_DROPPED) != US_DROPPED) g_usnap_drops++;   // a helper still copying it finds DROPPED when it is done and leaves it
}
/* TOTK: the value guest memory [a, a+n) will hold once this submission's pending writes (inline uniform updates,
   GPU copies) have executed: the replay needs it on the CPU for pointers the shader loads from a user uniform block.
   Returns 1 when a pending write supplied the bytes, 0 when memory is current (out is filled either way), -1 when a
   pending write overlaps only partly or the table overflowed (out = memory, which may be stale). */
static int pend_read(uint64_t a, void *out, size_t n, int depth) {
    for (int i = g_npend - 1; i >= 0; i--) {
        if (a >= g_pend_hi[i] || a + n <= g_pend_lo[i]) continue;
        if (a < g_pend_lo[i] || a + n > g_pend_hi[i]) { memcpy(out, (const void *)(uintptr_t)a, n); return -1; }
        if (g_pend_kind[i] == 0) { memcpy(out, (const uint8_t *)g_pend_src[i] + (a - g_pend_lo[i]), n); return 1; }
        uint64_t src = (uint64_t)(uintptr_t)g_pend_src[i] + (a - g_pend_lo[i]);
        if (depth < 4) { int r = pend_read(src, out, n, depth + 1); return r < 0 ? -1 : 1; }
        memcpy(out, (const void *)(uintptr_t)src, n); return 1;
    }
    usnap_read(a, out, n);
    return pend_over() ? -1 : 0;
