/* Reusing the open copy encoder needs a barrier between copies too: Metal 4 does not run the commands of one encoder in
   recording order, so a write then a read (or two writes) of the same range can swap (D2R Mobile 44a6770: without it a
   test read a stale value 1 time in 3). The barrier when the encoder opens only orders it against earlier encoders. On
   Metal 4 the copy encoder is a compute encoder, so both blit and dispatch stages are ordered. TOTK_BLIT_BAR=0: off. */
static int blit_bar_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_BLIT_BAR"); v = !e || atoi(e); } return v; }
static id<MTL4ComputeCommandEncoder> blit_kind(int buffer_alias) { blit_note(); if (g_enc) RP_WHY("copy"); if (!g_blit) { g_blit_opens++; g_blit_splits += g_enc != nil; } rp_end();
    if (buffer_alias && !g_copy_probe_no_alias) g_blit_alias = 1; // rp_end may itself open and close a copy encoder
    if (!g_blit) { rs_sync(); ser_gate(); pt_mark(g_cb, 'B', nil); g_blit = enc_b_begin(g_cb); [g_blit barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageAll visibilityOptions:blit_vis()]; g_bar_prior = 0; }
    else if (blit_bar_on()) [g_blit barrierAfterEncoderStages:MTLStageBlit | MTLStageDispatch beforeEncoderStages:MTLStageBlit | MTLStageDispatch visibilityOptions:blit_vis()];
    return g_blit; }
static id<MTL4ComputeCommandEncoder> blit(void) { return blit_kind(0); }
/* Buffer copies (mtl_sub_copy, the copy fallback of inline uniform updates). The same memory can be reached through two Metal
   buffers, each with its own GPU virtual address: a virtual pool's remapped view of a physical pool, or two pools over the same
   CPU memory. Device visibility alone does not make a write through one visible to a read through the other: a chain of copies
   through two no-copy buffers over one allocation read stale bytes on every run (probe-gpu-copy-alias). So every buffer-copy
   segment carries alias visibility in the barriers it keeps and at the encoder end (original port d309e62, Codex). The ranges
   are unused here; the original port's copy-batch experiment (off by default) takes the same call. */
static id<MTL4ComputeCommandEncoder> blit_buffer(id<MTLBuffer> src, NSUInteger so, id<MTLBuffer> dst, NSUInteger d, NSUInteger n) {
    (void)src; (void)so; (void)dst; (void)d; (void)n; return blit_kind(1); }

/* TOTK: collect and copy the uniform ranges a submission binds (see usnap_t). */
static size_t arena_alloc(size_t n, __strong id<MTLBuffer> *buf);
static size_t arena_alloc_u(size_t n, __unsafe_unretained id<MTLBuffer> *buf, uint8_t **cpu, uint64_t *gpu);
static void pend_materialize(uint64_t a, uint8_t *out, size_t n, int depth);
static void pend_overlay(uint64_t a, uint8_t *out, size_t n, int depth);
static void pend_materialize_x(uint64_t a, uint8_t *out, size_t n, int depth, int wait);
static void pend_overlay_x(uint64_t a, uint8_t *out, size_t n, int depth, int wait);
typedef struct { uint64_t lo, hi; } usnap_rng;
typedef struct { usnap_rng *r; int n, cap; } usnap_rngs;
static usnap_rngs g_usr;   // replay side (the capture on the game thread uses its own list)
static void usnap_collect(usnap_rngs *v, const uint8_t *p, int depth) {
    for (;;) {
        op_hdr h; memcpy(&h, p, sizeof h);
        if (h.size < 8 || (h.size & 7) || h.op >= OP_COUNT_) MDIE("corrupt recording at %p while copying uniforms (op %u size %u)", (const void *)p, h.op, h.size);
        if (h.op == OP_END) return;
        if (h.op == OP_JUMP) { memcpy(&p, p + 8, 8); continue; }
        if (h.op == OP_CALL) { uint64_t t; memcpy(&t, p + 8, 8); if (depth < 16) usnap_collect(v, (const uint8_t *)(uintptr_t)t, depth + 1); }
        else if (h.op == OP_BIND_UBO) {
            const p_bind_buf *b = (const p_bind_buf *)(p + 8);
            if (b->addr && b->size && b->size <= 65536) {
                if (v->n == v->cap) { v->cap = v->cap ? v->cap * 2 : 4096; v->r = realloc(v->r, v->cap * sizeof *v->r); if (!v->r) MDIE("uniform copy ranges"); }
                v->r[v->n++] = (usnap_rng){b->addr, b->addr + b->size};
            }
        }
        p += h.size;
    }
}
static int usnap_cmp(const void *x, const void *y) { const usnap_rng *a = x, *b = y; return a->lo < b->lo ? -1 : a->lo > b->lo; }
/* TOTK: sort ranges by start. A frame binds a few thousand uniform ranges; qsort with a compare callback took about 5% of
   the replay (0.4 ms a frame on the M4). LSD radix sort on the 64-bit start, 8 bits per pass, skipping bytes every key
   shares (guest addresses differ only in their low few bytes); stable, so equal starts keep their order. */
static void rng_sort(usnap_rng *a, int n) {
    if (n < 2) return;
    if (n <= 32) { qsort(a, (size_t)n, sizeof *a, usnap_cmp); return; }
    static usnap_rng *tmp; static int cap;
    if (n > cap) { cap = n + n / 2; tmp = realloc(tmp, (size_t)cap * sizeof *tmp); if (!tmp) MDIE("range sort"); }
    uint64_t lo_or = 0, lo_and = ~0ull;
    for (int i = 0; i < n; i++) { lo_or |= a[i].lo; lo_and &= a[i].lo; }
    uint64_t vary = lo_or ^ lo_and;
    usnap_rng *src = a, *dst = tmp;
    for (int sh = 0; sh < 64; sh += 8) {
        if (!((vary >> sh) & 0xff)) continue;
        int cnt[257] = {0};
        for (int i = 0; i < n; i++) cnt[((src[i].lo >> sh) & 0xff) + 1]++;
        for (int b = 0; b < 256; b++) cnt[b + 1] += cnt[b];
        for (int i = 0; i < n; i++) dst[cnt[(src[i].lo >> sh) & 0xff]++] = src[i];
        usnap_rng *t = src; src = dst; dst = t;
    }
    if (src != a) memcpy(a, src, (size_t)n * sizeof *a);
}
static int gw_cmp(const void *x, const void *y) { const gw_t *a = x, *b = y; return a->lo < b->lo ? -1 : a->lo > b->lo; }
/* With the translation thread (TOTK_ASYNC_REPLAY=1) nvnQueueSubmitCommands returns before the replay, as on the console,
   and the game rebuilds its constant pools right away: the uniform bytes are captured in the submit call (game thread)
   and the replay builds its copies from them. done: fence completion at the capture; a GPU write of an earlier submission
   whose fence is above it was not in memory then, so ranges it overlaps are read on the GPU timeline instead (with the
   replay inside the submit call the capture is the replay's own start, as before). */
typedef struct { uint64_t done; int n; usnap_rng *r; size_t *off; uint8_t *bytes; size_t cap; uint64_t ns; } usnap_cap;
/* Capture byte buffers are reused (a few MB each submission): a fresh malloc of that size is fresh pages, and their first
   touch made the copy three times slower than memcpy (0.18 ms of the submit call for 1.9 MB). */
