    if (g1 - g0 >= UPD_GRAN_MAX) return 0;
    for (uint64_t g = g0; g <= g1; g++) { unsigned b = upd_gran_bit(g); if (g_upd_bits[b >> 6] >> (b & 63) & 1) return 0; }
