static void pend_overlay(uint64_t a, uint8_t *out, size_t n, int depth) { pend_overlay_x(a, out, n, depth, 1); }
// Write the logged updates into memory on the GPU timeline (ends a render pass if one is open).
static void upd_flush(void) {
    if (!g_nupd) return;
    /* Own encoder: copies inside one encoder may run concurrently, so earlier copies to these bytes and later readers of
       them (a buffer copy right after this flush) must sit in other encoders, ordered by the encoder barriers. */
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    id<MTL4ComputeCommandEncoder> b = nil;
    for (int i = 0; i < g_nupd;) {
        uint64_t lo = g_upd[i].lo, hi = g_upd[i].hi; int j = i + 1;
        for (; j < g_nupd && g_upd[j].lo <= hi; j++) if (g_upd[j].hi > hi) hi = g_upd[j].hi;   // merge overlapping / touching ranges
        void *db; uint64_t dof;
        if (!mtl_addr(lo, hi - lo, &db, &dof)) MDIE("renamed uniform update %#llx+%#llx is no longer in one memory pool", (unsigned long long)lo, (unsigned long long)(hi - lo));
        usnap_drop(lo, hi - lo);   // TOTK: from here on the update is in memory (GPU timeline): later readers read it there
        __unsafe_unretained id<MTLBuffer> sb; uint8_t *scpu; size_t so = arena_alloc_u((size_t)(hi - lo), &sb, &scpu, NULL);
        pend_materialize(lo, scpu, (size_t)(hi - lo), 0);   // every byte here is covered by a logged update: the newest one wins
        if (!b) b = blit();
        enc_b_copy_buffer(b, sb, so, (__bridge id<MTLBuffer>)db, dof, hi - lo);
