        base_size = e ? atoi(e) : 40; base_first = f ? atoi(f) : 30;
        if (base_size <= 0 || base_first <= 0) base_size = base_first = 0;
    }
    int size = atomic_load(&g_chunk_size_request), first = atomic_load(&g_chunk_first_request);
    if (size < 0) size = base_size;
    if (first < 0) first = base_first;
    if (!size || !first) size = first = 0;
    if (size != g_chunk_size || first != g_chunk_first)
        MLOG("TOTK: mid-submission commits %s (first after %d draws, then every %d draws)", size ? "on" : "off", first, size);
    g_chunk_size = size; g_chunk_first = first;
}
uint64_t mtl_chunk_commits(void) { return g_chunk_commits; }
uint64_t mtl_chunk_time_commits(void) { return g_chunk_time_commits; }
void mtl_blit_stats(uint64_t v[6]) { v[0] = g_blit_opens; v[1] = g_blit_splits; v[2] = g_upd_n; v[3] = g_upd_split; v[4] = g_copy_n; v[5] = g_copy_split; }
/* Mid-submission commits are numbered (g_split_seq); g_split_done is the highest one the GPU completed, so a readback
   can wait for the commit that ends right after its producer dispatch (fif_readback_wait; after DavidZande 6a87c04). */
static uint64_t g_split_seq; static _Atomic uint64_t g_split_done;
static pthread_mutex_t g_split_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_split_cv = PTHREAD_COND_INITIALIZER;
/* TOTK_SPLIT_EARLY (default on; =0 off), 2026-10-23: the split waited for the encode stage (rs_sync: 125 samples in the
   Korok Forest profile) before doing the work that does not touch the chunk's command buffer: flushing the upload batch
   (its own command buffer, committed before this chunk as before), the residency commit, the commit options and the next
   chunk's command buffer object. That work now runs first and overlaps the encode stage's tail; the chunk is ended and
   committed after the wait as before, so the GPU sees the same commits in the same order. Nothing is replayed in
   between, so no upload can be recorded after the flush for this chunk. */
static int split_early_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_SPLIT_EARLY"); v = !(e && !atoi(e)); if (!v) MLOG("TOTK_SPLIT_EARLY=0: a chunk split waits for the encode stage first"); } return v; }
static void mtl_sub_split(void) {
    uint64_t fc0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); int fc_first = g_sub_chunks == 0, early = split_early_on();
    uint64_t fc1 = fc0, fc2, fc3, w0 = 0;
    if (!early) { rs_sync(); fc1 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }   // TOTK: the encode stage must have finished every pass of this command buffer
    up_flush();
    fc2 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    res_commit();
    fc3 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    uint64_t gpu_f = atomic_load(&g_cur_frame), fence_next = g_fence + 1; gpu_tag_begin(gpu_f);
    TotkCommitOptions *o = [TotkCommitOptions new]; uint64_t split_seq = ++g_split_seq;
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) {
        gpu_tag_done(gpu_f, f.GPUStartTime, f.GPUEndTime);
        pthread_mutex_lock(&g_split_mu); if (split_seq > atomic_load(&g_split_done)) atomic_store(&g_split_done, split_seq); pthread_cond_broadcast(&g_split_cv); pthread_mutex_unlock(&g_split_mu);
        if (f.error) { atomic_store(&g_last_commit_error, 1); static int n; if (n++ < 8) MLOG("[red] segment command buffer error fence=%llu: %s", (unsigned long long)fence_next, f.error.description.UTF8String); }
    }];
    if (totk_tl_on()) { uint64_t tlid = totk_tl_commit_id(); totk_tl(TL_COMMIT, tlid, 0);
        [o addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { totk_tl_at(TL_GPU, (uint64_t)(fb.GPUStartTime * 1e9), tlid, (uint64_t)(fb.GPUEndTime * 1e9)); }]; }
    id<MTL4CommandBuffer> next = [g_dev newCommandBuffer];
    if (early) { w0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); rs_sync(); fc1 = fc0 + (clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - w0); }   // fc1 - fc0: the wait, as before
    [g_cb endCommandBuffer];
    q4_commit(g_cb, o);
    g_cb = next;
    [g_cb beginCommandBufferWithAllocator:g_alloc4[g_alloc_cur]];
    g_sub_chunks++; g_chunk_commits++; g_chunk_mark = g_stat_draw; g_chunk_t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (fc_first) { uint64_t fc4 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW), wait = fc1 - fc0;   // [2] the wait, [3] up_flush, [4] res_commit, [5] the rest
        g_fc_t[1] += fc0 - g_fc_snap_end; g_fc_t[2] += wait; g_fc_t[3] += fc2 - (early ? fc0 : fc1); g_fc_t[4] += fc3 - fc2; g_fc_t[5] += fc4 - fc3 - (early ? wait : 0); g_fc_n++; }
}
/* TOTK_CHUNK_US (default 300, 0 = off): besides the draw count, a split point also commits once this many microseconds
   of replay have passed since the submission began or the last commit and at least 10 draws were replayed meanwhile
   (Ryujinx AutoFlushCounter, 1.5 ms there), so the GPU gets work early when draws are slow to replay. Commits still
   happen only where a new encoder is about to open: a render pass is never split. */
static int chunk_us(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_CHUNK_US"); v = e ? atoi(e) : 300; if (v < 0) v = 0; MLOG("TOTK_CHUNK_US=%d: mid-submission commits also after %d us of replay (0 = by draw count only)", v, v); } return v; }
// Called where a new encoder is about to be opened and none is open.
static void chunk_maybe_split(void) {
    if (!g_chunk_size || !g_cb || g_enc || g_frz_on || tbdr_any() || pt_active()) return;
    uint64_t nd = g_stat_draw - g_chunk_mark; int by_time = 0;
    if (nd < (uint64_t)(g_sub_chunks ? g_chunk_size : g_chunk_first)) {
        int us = chunk_us();
        if (!us || nd < 10 || clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - g_chunk_t0 < (uint64_t)us * 1000ull) return;
        by_time = 1;
    }
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    mtl_sub_split();
    if (by_time) g_chunk_time_commits++;
}
uint64_t mtl_sub_commit(void) {
    cg_flush();   // TOTK: cube-face-set groups still pending at the end of the submission (reason 4 in the stats line)
    lc_land();   // TOTK_LAZY_CLEAR: clears still waiting (normally landed at the end of each command list); rp_flush below lands a taken one
    defer_fallback();   // Deferred merged pass: at the end of the submission there are still P draws not replayed (the normal path never gets here)
    rp_flush();
    usnap_finish();   // TOTK: the helper threads must be done with the copies (they are, long before this)
    g_nusnap = 0; g_mat_gen++;   // TOTK: the replay is done; the uniform copies stay in this submission's arena until it completes
    upd_flush(); BOTW_WB_STAGE() BOTW_TINY_COMMIT()   // TOTK: renamed uniform updates reach memory here, after every draw that read them through private copies
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    rs_sub_end();   // TOTK: encode stage drained before the command buffer is ended
    up_flush();
    uint64_t fence = ++g_fence;
    { void fif_commit(uint64_t fence, int occl, int stat); int fif_guard_on(void);
      if (fif_guard_on()) { int no = 0, ns = 0; for (int i = 0; i < g_npost; i++) { no += g_post[i].kind == 3; ns += g_post[i].kind == 2; } fif_commit(fence, no, ns); } }
    if (g_vis_ring_i >= 0) g_vis_ring[g_vis_ring_i].fence = fence;
    // CPU-visible effects after completion: copy the op table into the callback
    int n = g_npost; post_op *ops = n ? malloc(n * sizeof *ops) : NULL;
    if (n) memcpy(ops, g_post, n * sizeof *ops);
    if (g_skv_n) {   // TOTK_EXP_SKIP_INVISIBLE: read this submission's per-draw counters on completion
        skv_item *l = g_skv_list; int n = g_skv_n; uint32_t fr = (uint32_t)atomic_load(&g_cur_frame); g_skv_list = NULL; g_skv_n = g_skv_cap = 0;
        [g_commit_blocks addObject:^{ skv_done(l, n, fr); }];
        static uint64_t subs; if (++subs % 300 == 0) MLOG("skip invisible draws through submit %llu: draws %llu, skipped %llu (%.1f%%), tested %llu, retested %llu (visible again after retest %llu), table full %llu, not skipped because the shader writes memory %llu%s%s", (unsigned long long)subs, (unsigned long long)g_skv_draws, (unsigned long long)g_skv_skipped, 100.0 * (double)g_skv_skipped / (double)(g_skv_draws ? g_skv_draws : 1), (unsigned long long)g_skv_tested, (unsigned long long)g_skv_retests, (unsigned long long)g_skv_revived, (unsigned long long)g_skv_full, (unsigned long long)g_skv_effects, skv_skip_storers() ? "" : " (strict: geometry that writes memory is not skipped either)", skv_retest() ? "" : " (no retest, measuring overhead only)");
    }
    if (g_anom_nvis) {   // TOTK_ANOMALY per-draw counters: read once this submission completes
        int cnt = g_anom_nvis; anom_vis_ent *copy = malloc((size_t)cnt * sizeof *copy); if (!copy) MDIE("anomaly counters");
        memcpy(copy, g_anom_vis, (size_t)cnt * sizeof *copy); g_anom_nvis = 0;
        [g_commit_blocks addObject:^{ anom_vis_done(copy, cnt); free(copy); }];
    }
    NSArray<dispatch_block_t> *commit_blocks = [g_commit_blocks copy];
    TotkCommitOptions *o = [TotkCommitOptions new];
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) { (void)f; for (dispatch_block_t block in commit_blocks) block(); }];
    uint64_t gpu_f = atomic_load(&g_cur_frame); gpu_tag_begin(gpu_f);
    NSString *cctx = @(cctx_snap());
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> cb) {
        nvn_dirty_guard_nowait();   // TOTK frames in flight: this thread writes counters into pool memory for its own submission
        gpu_tag_done(gpu_f, cb.GPUStartTime, cb.GPUEndTime);
        if (cb.error) { atomic_store(&g_last_commit_error, 1); static int n, nv; int victim = [cb.error.description containsString:@"InnocentVictim"]; if (victim ? nv++ < 1 : n++ < 8) MLOG("[red] command buffer error details fence=%llu: %s | GPU %.3f→%.3f", (unsigned long long)fence, cb.error.description.UTF8String, cb.GPUStartTime, cb.GPUEndTime); if (!victim) MLOG("[red] context of the failing submit fence=%llu: %s", (unsigned long long)fence, cctx.UTF8String); MLOG("[red] command buffer execution error: %s", cb.error.localizedDescription.UTF8String); }
        int nq = 0, nzero = 0;   // TOTK_OCCL_AUTODUMP: occlusion queries of this submission and how many reported 0
        for (int i = 0; i < n; i++) {
            if (post_stale(&ops[i])) { if (ops[i].kind == 3) { vis_list *l = ops[i].vis; for (int k = 0; k < l->n; k++) CFRelease(l->s[k].buf); free(l); } continue; }
            if (ops[i].kind == 1) { if (ops[i].mode == 1) *ops[i].val += ops[i].v; else *ops[i].val = ops[i].v; }
            else if (ops[i].kind == 3) {   // Samples passed: the sum of all slots since the reset
                vis_list *l = ops[i].vis; uint64_t sum = 0;
                for (int k = 0; k < l->n; k++) { const uint64_t *c = ((__bridge id<MTLBuffer>)l->s[k].buf).contents; for (uint32_t q = 0; q <= l->s[k].n; q++) sum += c[l->s[k].slot + q]; CFRelease(l->s[k].buf); }
                static int qlog = -1; if (qlog < 0) qlog = getenv("TOTK_QUERY_LOG") != NULL;
                if (qlog) MLOG("[query] frame=%llu fence=%llu addr=%#llx slots=%d samples=%llu", (unsigned long long)gpu_f, (unsigned long long)fence, (unsigned long long)ops[i].addr, l->n, (unsigned long long)sum);
                if (ops[i].qlog) MLOG("[query] F%llu dst=%#llx samples=%llu sphere=%g,%g,%g,%g%s", (unsigned long long)gpu_f, (unsigned long long)ops[i].addr, (unsigned long long)sum,
                                      ops[i].sph[0], ops[i].sph[1], ops[i].sph[2], ops[i].sph[3], atomic_load(&g_occl_vis) ? " (reported as visible: occl_visible)" : "");
                if (atomic_load(&g_occl_vis)) sum = 1u << 20;
