}

uint64_t mtl_last_fence(void) { return g_fence; }
int mtl_last_commit_error(void) { return atomic_load(&g_last_commit_error); }

int mtl_wait(uint64_t fence, uint64_t timeout_ns) {
    struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl);
    uint64_t ns = (uint64_t)dl.tv_nsec + (timeout_ns > 3600000000000ull ? 3600000000000ull : timeout_ns);
    dl.tv_sec += ns / 1000000000ull; dl.tv_nsec = ns % 1000000000ull;
    pthread_mutex_lock(&g_mu);
    int r = 0;
    while (g_done < fence) if ((r = pthread_cond_timedwait(&g_cv, &g_mu, &dl))) break;
    int ok = g_done >= fence;
    pthread_mutex_unlock(&g_mu);
    return ok;
}

/* ---------- TOTK frames in flight (TOTK_FRAMES_IN_FLIGHT=2; hle_nvn.c fif_target) ----------
   The game waits every frame on the fence of the frame it just submitted; with 2 that wait returns at the previous
   frame's fence, so the game may run one frame ahead of the GPU. yuzu / Ryujinx can do this because their GPU never
   reads guest memory directly; ours does (zero-copy pools), so the CPU side has to block instead:
   - CPU -> GPU: the GPU reads memory pools zero-copy (vertex / index / storage / indirect buffers, buffer textures,
     GPU texture decode). Every pool a submission looked up gets the submission's fence and its pages are made
     read-only at commit (nvn_dirty_guard); a CPU write to such a page waits in the fault handler until that fence is
     complete. Uniforms (usnap / upd_shadow) and CPU-mirrored textures are copies already and need nothing.
   - GPU -> CPU: a pool invalidate (the game's "about to read") over memory a GPU command of a submission still in flight
     writes waits for that command (fif_readback_wait; producers: storage writes, texture->buffer and buffer copies,
     uniform updates, counters). Producer compute shaders the game reads back are learned and end a command buffer right
     after their dispatch, so the wait is for that early commit only (port of DavidZande's TOTK_LAG_READBACK=2, 6a87c04
     / bdb8946). Submissions are flagged by class (fif_commit: occlusion reports, timestamp / statistics reports, pools
     the guard could not cover) and hle_nvn.c fif_target decides per class whether the lagged wait falls back.
   - Pool classes the guard sees (2026-10-23): ordinary pools (CPU cached / uncached / CPU_NO_ACCESS / compressible
     alike: our own host writes go through prep_write, which waits too) are guarded page-protected ranges; pools sharing
     a host page with a neighbour (NVN 4 KiB alignment vs 16 KiB host pages: the ~20 "untracked" pools a frame of the
     2026-10-23 audit) are now registered clipped and guarded across both ranges (nvn_dirty_add_range); virtual pools
     also guard the physical storage mapped into them, which the CPU writes through another address (totk_vpool_guard);
     GPU_NO_ACCESS pools are never registered for the GPU, so no submission reads them.
   - TOTK_FIF_AUDIT=1: nothing waits; the guard and the readback check only count what would have waited, with sample
     addresses (does TOTK multi-buffer its dynamic data?). Unsafe, for measurement. */
static uint64_t mtl_done_fence(void) { return __atomic_load_n(&g_done, __ATOMIC_ACQUIRE); }
static int fif_audit_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_FIF_AUDIT"); v = e && atoi(e) > 0; } return v; }
int fif_guard_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("TOTK_FRAMES_IN_FLIGHT"), *g = getenv("TOTK_FIF_GUARD"); v = e && atoi(e) > 1 && !(g && !strcmp(g, "0"));
        if (v) { nvn_dirty_guard_init(mtl_done_fence, fif_audit_on());
                 MLOG("[fif] frames in flight: pools the GPU reads are write-guarded per submission, readbacks wait for their producer%s (TOTK_FIF_GUARD=0: unguarded, unsafe)",
                      fif_audit_on() ? "; TOTK_FIF_AUDIT=1: nothing waits, would-be waits are only counted (unsafe)" : ""); } }
    return v;
}
#define FIF_SET 8192
static uint64_t g_fif_lo[FIF_SET], g_fif_hi[FIF_SET]; static uint32_t g_fif_tag[FIF_SET], g_fif_gen, g_fif_list[FIF_SET / 2]; static int g_fif_n, g_fif_over;
static _Atomic uint32_t g_fif_flags[4096]; static _Atomic uint64_t g_fif_flag_fence[4096];
static _Atomic uint64_t g_fif_subs, g_fif_pools, g_fif_unguarded, g_fif_counter_subs, g_fif_stat_subs, g_fif_pool_untracked, g_fif_virt_ok, g_fif_virt_bad, g_fif_over_subs;
int totk_vpool_guard(uintptr_t lo, uintptr_t hi, uint64_t fence);
void fif_begin(void) { t_fif_rec = 1; if (!++g_fif_gen) { memset(g_fif_tag, 0, sizeof g_fif_tag); g_fif_gen = 1; } g_fif_n = 0; g_fif_over = 0; }
static void fif_note_pool(uintptr_t lo, uintptr_t hi) {   // replay thread only (t_fif_rec)
    uint32_t h = (uint32_t)((lo >> 12) * 0x9E3779B1u) & (FIF_SET - 1);
    for (int k = 0; k < FIF_SET; k++, h = (h + 1) & (FIF_SET - 1)) {
        if (g_fif_tag[h] != g_fif_gen) { if (g_fif_n >= FIF_SET / 2) { g_fif_over = 1; return; } g_fif_tag[h] = g_fif_gen; g_fif_lo[h] = lo; g_fif_hi[h] = hi; g_fif_list[g_fif_n++] = h; return; }
        if (g_fif_lo[h] == lo) { if (hi > g_fif_hi[h]) g_fif_hi[h] = hi; return; }
    }
}
/* Submission flags (mtl_fence_flags; hle_nvn.c fif_target decides per class):
     FIF_FL_OCCL  samples-passed (occlusion) reports: real fence unless TOTK_FIF_COUNTERS=1
     FIF_FL_STAT  timestamp / statistics reports: lagged unless TOTK_FIF_COUNTERS=0 (see fif_target)
     FIF_FL_UNG   a pool read zero-copy with pages no tracking range covers (nvn_dirty_guard 0)
     FIF_FL_VIRT  a virtual pool whose physical backing could not be guarded (totk_vpool_guard 0)
     FIF_FL_OVER  more pools than the per-submission set holds
     FIF_FL_NOREC the submission's flags were not recorded (mtl_fence_flags only)   (values: nvn_mtl.h) */
void fif_commit(uint64_t fence, int occl, int stat) {
    t_fif_rec = 0;
    uint32_t fl = (occl ? FIF_FL_OCCL : 0u) | (stat ? FIF_FL_STAT : 0u) | (g_fif_over ? FIF_FL_OVER : 0u);
    uint64_t untracked = 0, vok = 0, vbad = 0;
    for (int i = 0; i < g_fif_n; i++) { uint32_t h = g_fif_list[i];
        if (!nvn_dirty_guard((const void *)(uintptr_t)g_fif_lo[h], g_fif_hi[h] - g_fif_lo[h], fence)) { fl |= FIF_FL_UNG; untracked++; }
        int v = totk_vpool_guard((uintptr_t)g_fif_lo[h], (uintptr_t)g_fif_hi[h], fence);   // a virtual pool: also its physical storage, which the CPU writes through another address
        if (v == 0) { fl |= FIF_FL_VIRT; vbad++; } else if (v > 0) vok++; }
    atomic_store(&g_fif_flags[fence & 4095], fl); atomic_store_explicit(&g_fif_flag_fence[fence & 4095], fence, memory_order_release);
    atomic_fetch_add(&g_fif_subs, 1); atomic_fetch_add(&g_fif_pools, (uint64_t)g_fif_n);
    if (fl & (FIF_FL_UNG | FIF_FL_VIRT | FIF_FL_OVER)) atomic_fetch_add(&g_fif_unguarded, 1);
    if (fl & FIF_FL_OVER) atomic_fetch_add(&g_fif_over_subs, 1);
    if (fl & FIF_FL_OCCL) atomic_fetch_add(&g_fif_counter_subs, 1);
    if (fl & FIF_FL_STAT) atomic_fetch_add(&g_fif_stat_subs, 1);
    atomic_fetch_add(&g_fif_pool_untracked, untracked); atomic_fetch_add(&g_fif_virt_ok, vok); atomic_fetch_add(&g_fif_virt_bad, vbad);
}
uint32_t mtl_fence_flags(uint64_t after, uint64_t upto) {   // OR of the flags of the submissions (after, upto]; FIF_FL_NOREC for one not recorded
    if (upto <= after) return 0;
    if (upto - after > 4000) return FIF_FL_NOREC;
    uint32_t fl = 0;
    for (uint64_t f = after + 1; f <= upto; f++) fl |= atomic_load_explicit(&g_fif_flag_fence[f & 4095], memory_order_acquire) == f ? atomic_load(&g_fif_flags[f & 4095]) : (uint32_t)FIF_FL_NOREC;
    return fl;
}
/* GPU -> CPU producers (after DavidZande 41de26e / 6a87c04 rb_prod): ranges a GPU command writes, with its submission's
   fence and the early commit after it (seq, 0 none). */
typedef struct { uint64_t lo, hi, fence, seq; char key[9]; } fif_prod;
#define FIF_PROD_N 4096
static fif_prod g_fprod[FIF_PROD_N]; static unsigned g_fprod_i; static pthread_mutex_t g_fprod_mu = PTHREAD_MUTEX_INITIALIZER;
static char g_fearly[16][9]; static int g_nfearly;
static uint64_t g_frb_waits, g_frb_ns, g_frb_full, g_frb_checked, g_frb_cnt_cov, g_frb_cnt_fly; static uint64_t g_frb_sample[4][2]; static unsigned g_frb_ns_i;
static int fif_early(const char *key) { for (int i = 0; i < g_nfearly; i++) if (!strncmp(g_fearly[i], key, 8)) return 1; return 0; }
static void fif_prod_note(uint64_t lo, uint64_t n, const char *key, uint64_t seq) {
    if (!n || !fif_guard_on()) return;
    pthread_mutex_lock(&g_fprod_mu);
    fif_prod *e = &g_fprod[g_fprod_i++ % FIF_PROD_N]; e->lo = lo; e->hi = lo + n; e->fence = g_fence + 1; e->seq = seq; snprintf(e->key, sizeof e->key, "%s", key ? key : "?");
    pthread_mutex_unlock(&g_fprod_mu);
}
static int fif_readback_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_FIF_READBACK"); v = fif_guard_on() && !(e && !strcmp(e, "0")); } return v; }
/* The game's thread, before it reads [lo, lo+n) (pool invalidate): wait for the newest GPU write of the range that is
   not complete -- its early commit when it has one, else its whole submission (and learn the shader). */
static void fif_readback_wait(uint64_t lo, uint64_t n) {
    if (!fif_readback_on() || !n) return;
    uint64_t done = mtl_done_fence(); fif_prod best = {0}; int have = 0;
    pthread_mutex_lock(&g_fprod_mu);
    g_frb_checked++;
    int cov_cnt = 0;
    for (unsigned k = 0; k < FIF_PROD_N; k++) { const fif_prod *e = &g_fprod[k];
        if (!(e->hi > lo && e->lo < lo + n)) continue;
        if (!cov_cnt && e->key[0] == 'c' && !strcmp(e->key, "counter")) { cov_cnt = 1; g_frb_cnt_cov++; }   // the game invalidates before reading counter results (then a lag is covered by this wait)
        if (e->fence <= done) continue;
        if (!have || e->fence > best.fence || (e->fence == best.fence && e->seq > best.seq)) { best = *e; have = 1; } }
    if (have && !strcmp(best.key, "counter")) g_frb_cnt_fly++;
    if (have) { g_frb_sample[g_frb_ns_i % 4][0] = lo; g_frb_sample[g_frb_ns_i % 4][1] = n; g_frb_ns_i++; }
    pthread_mutex_unlock(&g_fprod_mu);
    if (!have) return;
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); int full = 0;
    if (fif_audit_on()) {}
    else if (best.seq) {
        pthread_mutex_lock(&g_split_mu);
        while (atomic_load(&g_split_done) < best.seq && !mtl_wait(best.fence, 0)) { struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl); dl.tv_nsec += 2000000; if (dl.tv_nsec >= 1000000000) { dl.tv_sec++; dl.tv_nsec -= 1000000000; }
            pthread_cond_timedwait(&g_split_cv, &g_split_mu, &dl); }
        pthread_mutex_unlock(&g_split_mu);
    } else if (!mtl_wait(best.fence, 0)) {
        full = 1;
        if (strlen(best.key) == 8 && !fif_early(best.key)) {   // a compute shader: its dispatches end a command buffer from now on
            pthread_mutex_lock(&g_fprod_mu);
            if (!fif_early(best.key) && g_nfearly < 16) { snprintf(g_fearly[g_nfearly], 9, "%s", best.key); g_nfearly++; MLOG("[fif] compute shader %s writes what the game reads back; its dispatches end a command buffer from now on", best.key); }
            pthread_mutex_unlock(&g_fprod_mu);
        }
        mtl_wait(best.fence, UINT64_MAX);
    }
    uint64_t dt = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0;
    pthread_mutex_lock(&g_fprod_mu); g_frb_waits++; g_frb_ns += dt; g_frb_full += full; pthread_mutex_unlock(&g_fprod_mu);
}
/* For the periodic log line (hle_nvn.c): v = {submissions, pools guarded, submissions unguarded, with counters,
   readback checks, readbacks of in-flight GPU writes (waits; audit: would-be waits), their wait ns, of them for a whole
   submission, early-commit shaders, completion writes skipped as stale,
   10: submissions with timestamp / statistics reports, 11: pools a submission read that could not be guarded,
   12 / 13: virtual pools whose physical backing was / could not be guarded, 14: pool invalidates over a counter record
   (the game invalidates before reading counter results), 15: of them while the record was in flight, 16: submissions
   whose pool set overflowed}; sample: the last readback ranges that hit. */
void mtl_fif_stats(uint64_t v[MTL_FIF_NSTAT], uint64_t sample[4][2]) {
    v[0] = atomic_load(&g_fif_subs); v[1] = atomic_load(&g_fif_pools); v[2] = atomic_load(&g_fif_unguarded); v[3] = atomic_load(&g_fif_counter_subs);
    pthread_mutex_lock(&g_fprod_mu); v[4] = g_frb_checked; v[5] = g_frb_waits; v[6] = g_frb_ns; v[7] = g_frb_full; v[8] = (uint64_t)g_nfearly; memcpy(sample, g_frb_sample, sizeof g_frb_sample);
    v[14] = g_frb_cnt_cov; v[15] = g_frb_cnt_fly; pthread_mutex_unlock(&g_fprod_mu);
    v[9] = atomic_load(&g_post_stale);
    v[10] = atomic_load(&g_fif_stat_subs); v[11] = atomic_load(&g_fif_pool_untracked); v[12] = atomic_load(&g_fif_virt_ok); v[13] = atomic_load(&g_fif_virt_bad); v[16] = atomic_load(&g_fif_over_subs);
}

static void mtl_finish_gpu(void) {
    if (g_fence) mtl_wait(g_fence, UINT64_MAX);
    up_pending_wait(1000);
}
void mtl_present_flush(void);
void mtl_finish(void) { mtl_present_flush(); mtl_finish_gpu(); }
/* nvnQueueFinish (upstream #159 piece b, nxnative b0a9079): waits for the GPU work submitted so far, not for queued presents to
   reach the screen (the Switch does not wait for the display either). With a window the display link takes one present per
   tick, so the wait made every QueueFinish cost one or two ticks; loaders that call it per resource paid that each time.
   A queued present keeps only a by-value tex_t copy, so before the game frees the memory or texture it presents from
   (nvnMemoryPoolFinalize / nvnTextureFinalize) mtl_present_flush_mem drains the queued presents that read it; AcquireTexture
   still waits for the texture's previous present ticket; mtl_drain (suspend / teardown) still flushes every present.
   TOTK_FINISH_PRESENTS=1: QueueFinish waits for presents again (old behaviour). Internal callers keep mtl_finish. */
void mtl_queue_finish(void) {
    static int old = -1; if (old < 0) { const char *e = getenv("TOTK_FINISH_PRESENTS"); old = e && atoi(e); if (old) MLOG("TOTK_FINISH_PRESENTS=1: QueueFinish also waits for queued presents (old behaviour)"); }
    if (old) mtl_present_flush();
    mtl_finish_gpu();
}   // Queue semantics: already-enqueued presents also count as queue work
static void present_drop_for_suspend(void);
void mtl_drain(void) { present_drop_for_suspend(); mtl_present_flush(); mtl_init(); id<MTLCommandBuffer> cb = q_cb(); cb_commit(cb); cb_wait(cb); mtl_finish_gpu(); }

// ================= Render replay =================
#include "../../host/front.h"
static int g_red_once[128];
#define RED_ONCE(k, ...) do { if (!g_red_once[k]++) MLOG("[red] " __VA_ARGS__); } while (0)

// ---------- Texture → MTLTexture ----------
static int fmt_compressed(int f) { return (f >= 0x41 && f <= 0x50) || (f >= 0x79 && f <= 0x94); }
static int fmt_depth(int f) { return f >= 0x31 && f <= 0x36; }
typedef struct { MTLPixelFormat a, b; } pfv_pair;
static const pfv_pair g_pfv_srgb[] = {
    {MTLPixelFormatRGBA8Unorm, MTLPixelFormatRGBA8Unorm_sRGB},
    {MTLPixelFormatBGRA8Unorm, MTLPixelFormatBGRA8Unorm_sRGB},
    {MTLPixelFormatBC1_RGBA, MTLPixelFormatBC1_RGBA_sRGB},
    {MTLPixelFormatBC2_RGBA, MTLPixelFormatBC2_RGBA_sRGB},
    {MTLPixelFormatBC3_RGBA, MTLPixelFormatBC3_RGBA_sRGB},
    {MTLPixelFormatBC7_RGBAUnorm, MTLPixelFormatBC7_RGBAUnorm_sRGB},
};
static int tex_need_pfv(MTLPixelFormat base, MTLPixelFormat view) {
    if (base == view) return 0;
    for (size_t i = 0; i < sizeof g_pfv_srgb / sizeof *g_pfv_srgb; i++)
        if ((base == g_pfv_srgb[i].a && view == g_pfv_srgb[i].b) || (base == g_pfv_srgb[i].b && view == g_pfv_srgb[i].a)) return 0;
    return 1;
}
// Cache tables on the replay hot path always use nvn_hmap (C hash, keys not boxed); the table stores CFBridgingRetain'ed objects, CFRelease'd on replace / delete
static void hm_rel(void *v) { CFRelease(v); }
static __unsafe_unretained id hm_get_id(const nvn_hmap *m, const void *k) { return (__bridge id)nvn_hm_get(m, k); }
static void hm_put_id(nvn_hmap *m, const void *k, id o) { void *old = nvn_hm_put(m, k, (void *)CFBridgingRetain(o)); if (old) CFRelease(old); }
static void hm_del_id(nvn_hmap *m, const void *k) { void *old = nvn_hm_del(m, k); if (old) CFRelease(old); }
static nvn_hmap g_by_serial = {.klen = 8};     // Serial → MTLTexture / NvPkg / NvProg
static pthread_mutex_t g_smu = PTHREAD_MUTEX_INITIALIZER;
// Serial table generation: +1 when entries are added / removed or a packaged texture is replaced. Downstream caches (texture views, programs) record the generation at fetch time; if it is unchanged they can be used directly without another table lookup
static _Atomic uint64_t g_ser_gen = 1;
static uint64_t g_treg_same, g_treg_changed;   // TOTK: identical / changed texture registrations (memory readout line)
/* TOTK: which serial each generation step was for (g_ser_chg[gen % SER_CHG_N]; 0 = not one serial, every cache must
   look again). A texture-ID view cache whose own serial is not among the steps since it was validated stays valid: the
   ~34 per-frame re-uploads of small CPU-written textures used to send every bound texture of every following draw down
   the slow path (about 13% of the replay). Written under g_smu before the generation is published. */
#define SER_CHG_N 1024
static _Atomic uint64_t g_ser_chg[SER_CHG_N];
/* TOTK: the newest generation step per hashed serial (and for "everything"), written with the step under g_smu before the
   generation is published. last <= from for a serial's slot and for "everything" means no step in (from, now] was for that
   serial (a shared slot only answers "maybe": the caller then looks again). O(1), and not limited to the last SER_CHG_N
   steps; tex_fast uses it so a texture view survives steps for other serials without leaving the inline path. */
#define SER_LAST_N 4096
static _Atomic uint64_t g_ser_last[SER_LAST_N], g_ser_last_all;
static inline unsigned ser_last_slot(uint64_t serial) { return (unsigned)((serial * UINT64_C(0x9E3779B97F4A7C15)) >> 52) & (SER_LAST_N - 1); }
static void ser_bump_locked(uint64_t serial) {
    uint64_t g = atomic_load_explicit(&g_ser_gen, memory_order_relaxed) + 1;
    atomic_store_explicit(&g_ser_chg[g % SER_CHG_N], serial, memory_order_relaxed);
    atomic_store_explicit(serial ? &g_ser_last[ser_last_slot(serial)] : &g_ser_last_all, g, memory_order_relaxed);
    atomic_store_explicit(&g_ser_gen, g, memory_order_release);
}
/* 1: no generation step after `from` up to the last g_ser_gen this thread acquired was for this serial or for everything. */
static inline int ser_unaffected_since(uint64_t from, uint64_t serial) {
    return serial && atomic_load_explicit(&g_ser_last_all, memory_order_relaxed) <= from &&
           atomic_load_explicit(&g_ser_last[ser_last_slot(serial)], memory_order_relaxed) <= from;
}
static void ser_bump(uint64_t serial);
/* 1 when none of the generation steps (from, to] was for this serial (or for "everything"). */
static int ser_unaffected(uint64_t from, uint64_t to, uint64_t serial) {
    if (!serial || to - from >= SER_CHG_N) return 0;
    for (uint64_t g = from + 1; g <= to; g++) { uint64_t s = atomic_load_explicit(&g_ser_chg[g % SER_CHG_N], memory_order_relaxed); if (!s || s == serial) return 0; }
    return atomic_load_explicit(&g_ser_gen, memory_order_acquire) - from < SER_CHG_N;   // no slot was overwritten while scanning
}
// ---------- TOTK: storage-shared GPU textures ----------
/* Several live NVNtexture objects can describe the same pool memory with the same layout: the game registers a
   persistent sampling object in the texture pool (e.g. serial 75485, the normals G-buffer) and re-initialises the
   render-target object at the same storage every frame (serial 75569). On hardware both descriptors read the same
   bytes; here every serial used to get its own private MTLTexture, so what was rendered through one serial was
   invisible through the other (the deferred lighting read all-zero normals: black geometry). GPU-owned textures are
   now keyed by (storage, layout): the same pixel format shares the MTLTexture, a different uncompressed format of the
   same texel size gets a texture view on it, and a usage the base lacks recreates the base with the union (content
   copied on the GPU timeline). An entry keeps its content while any serial holds it and for STOR_IDLE_SUBMITS
   submissions after the last holder left (previous-frame buffers are re-initialised every frame), and is dropped
   when its memory pool is finalised. TOTK_TEX_SHARE=0 restores one texture per serial. */
int nvn_fmt_bpb(int format, int *bw, int *bh);
typedef struct { uint64_t mem, size; uint32_t w, h, d, levels, target, samples, bpb, depth_fmt; } stor_key;   // 48 bytes, no padding
typedef struct { stor_key k; void *tex; uint64_t idle_fence; uint64_t *ser; int nser, cser; uint64_t rt_frame, rt_frames; } stor_ent;      // tex: CFBridgingRetain'ed base texture; ser: serials holding it or a view on it; rt_*: last frame / frames it was a render target (stor_note_attach)
static nvn_hmap g_by_storage = {.klen = sizeof(stor_key)};   // stor_key -> stor_ent *
static nvn_hmap g_stor_of_obj = {.klen = 8};                  // base texture / view pointer -> stor_ent *
static uint64_t g_stor_entries, g_stor_shared, g_stor_viewed, g_stor_recreated, g_stor_swept, g_stor_dropped;
/* Texture preparation runs before a draw captures its encoder. An upgrade discovered under the
   registry lock requests a pass split; the caller ends the pass outside that lock and retries. */
static int g_tex_preparing, g_tex_prepare_split;
#define STOR_IDLE_SUBMITS 600
static int stor_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_TEX_SHARE"); on = !e || atoi(e); } return on; }
static int stor_key_of(const tex_t *t, stor_key *k) {
    if (!t->mem || !t->L.size) return 0;
    int bw = 1, bh = 1, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
    if (!bpb || bw != 1 || bh != 1) return 0;   // block-compressed formats keep one texture per serial (no cross-format views)
    memset(k, 0, sizeof *k);
    k->mem = (uint64_t)(uintptr_t)t->mem; k->size = t->L.size; k->w = t->d.width ? t->d.width : 1; k->h = t->d.height ? t->d.height : 1; k->d = t->d.depth ? t->d.depth : 1; k->levels = t->d.levels ? t->d.levels : 1;
    k->target = (uint32_t)t->d.target; k->samples = t->d.samples > 1 ? (uint32_t)t->d.samples : 1; k->bpb = (uint32_t)bpb; k->depth_fmt = (uint32_t)fmt_depth(t->d.format);
    return 1;
}
static inline uint64_t obj_key(id o) { return (uint64_t)(uintptr_t)(__bridge void *)o; }
/* g_smu held: a serial starts / stops holding a storage-owned object. stor_unref_locked returns 1 for a storage-owned
   object, which the caller must only unref (the entry keeps it resident); a dropped view leaves the object table. */
static void stor_ref_locked(id o, uint64_t serial) {
    uint64_t ok = obj_key(o); stor_ent *e = nvn_hm_get(&g_stor_of_obj, &ok); if (!e) return;
    for (int i = 0; i < e->nser; i++) if (e->ser[i] == serial) return;
    if (e->nser == e->cser) { e->cser = e->cser ? e->cser * 2 : 4; e->ser = realloc(e->ser, (size_t)e->cser * sizeof *e->ser); if (!e->ser) MDIE("storage serial list"); }
    e->ser[e->nser++] = serial;
}
static int stor_unref_locked(id o, uint64_t serial) {
    uint64_t ok = obj_key(o); stor_ent *e = nvn_hm_get(&g_stor_of_obj, &ok); if (!e) return 0;
    for (int i = 0; i < e->nser; i++) if (e->ser[i] == serial) { e->ser[i] = e->ser[--e->nser]; break; }
    if (!e->nser) e->idle_fence = g_fence;
    if ((__bridge void *)o != e->tex) nvn_hm_del(&g_stor_of_obj, &ok);
    return 1;
}
static int stor_key_lookup(id o, stor_key *k);
static id<MTLTexture> stor_recreate(const stor_key *k, MTLTextureUsage usage);
/* TOTK: plain pointer (the macro bridges it), as prog_get_p / tex_by_id_p: every texture returned is held by the serial
   table (directly or through its NvPkg), whose entries are dropped only through the deferred-release queue (also
   pkg_evict_sweep, reup_retire). As an id return each call was a retain + autorelease in here and a claim in the caller. */
static void *tex_mtl_p(const tex_t *ct);
#define tex_mtl(t) ((__bridge id<MTLTexture>)tex_mtl_p(t))
static int rp_active(void);
/* TOTK: plain pointers for the replay hot paths. The functions above return id, and the __unsafe_unretained on their
   return types is ignored by ARC, so every lookup was a retain / autorelease pair. Table entries are only freed through
   the deferred-release queue, which the replay thread drains, so the replay may hold these unretained. */
static inline void *hm_get_ptr(const nvn_hmap *m, const void *k) { return nvn_hm_get(m, k); }
static void *serial_ptr(uint64_t k) { pthread_mutex_lock(&g_smu); void *o = nvn_hm_get(&g_by_serial, &k); pthread_mutex_unlock(&g_smu); return o; }
static __unsafe_unretained id serial_get(uint64_t k) { pthread_mutex_lock(&g_smu); __unsafe_unretained id o = hm_get_id(&g_by_serial, &k); pthread_mutex_unlock(&g_smu); return o; }
static void serial_put(uint64_t k, id o) { pthread_mutex_lock(&g_smu); id old = hm_get_id(&g_by_serial, &k); if (old) { if (stor_unref_locked(old, k)) defer_obj_unref(old); else defer_obj_release(old); } hm_put_id(&g_by_serial, &k, o); stor_ref_locked(o, k); ser_bump_locked(k); pthread_mutex_unlock(&g_smu); }
static void serial_del(uint64_t k) { pthread_mutex_lock(&g_smu); id old = hm_get_id(&g_by_serial, &k); if (old) { if (stor_unref_locked(old, k)) defer_obj_unref(old); else defer_obj_release(old); } hm_del_id(&g_by_serial, &k); ser_bump_locked(k); pthread_mutex_unlock(&g_smu); BOTW_SERIAL_NOTE(k, "serial_del") }
static void ser_bump(uint64_t serial) { pthread_mutex_lock(&g_smu); ser_bump_locked(serial); pthread_mutex_unlock(&g_smu); }
/* Dead serials (TOTK): the game finalizes temporary NVNtexture objects after recording and before the submission runs,
   so a replay may meet a serial that was already finalized. Previously the replay created a Metal texture for it and
   stored it under the serial, where nothing ever deleted it: about 4.6 textures (~18 MB) leaked per frame, the
   residency set grew without bound and the GPU driver ran out of wired memory (kernel panics). A texture created
   for a dead serial is now deleted again when the submission that used it completes. */
static totk_serial_set g_dead_serial;   // serial -> (void *)1 once finalized
/* TOTK: serials the GPU has rendered into. A mirrored (CPU-pool) texture that the game then uses as a render target is owned by
   the GPU from that point: dirty-page re-uploads from the (stale) pool memory would wipe the rendered content. */
static totk_serial_set g_gpu_owned;
static _Atomic uint64_t g_owned_gen = 1;   // TOTK: bumped whenever a serial joins g_gpu_owned (entries are never removed)
static void pkg_owned_locked(uint64_t k);
static void gpu_owned_mark(uint64_t k) { pthread_mutex_lock(&g_smu); int had = totk_serial_has(&g_gpu_owned, k); if (!had) { totk_serial_add(&g_gpu_owned, k); atomic_fetch_add(&g_owned_gen, 1); pkg_owned_locked(k); } pthread_mutex_unlock(&g_smu);
}
static int gpu_owned(uint64_t k) { pthread_mutex_lock(&g_smu); int d = totk_serial_has(&g_gpu_owned, k); pthread_mutex_unlock(&g_smu); return d; }

static uint64_t *g_dead_put; static int g_dead_put_n, g_dead_put_cap; static uint64_t g_dead_put_total;
static int serial_is_dead(uint64_t k) { pthread_mutex_lock(&g_smu); int d = totk_serial_has(&g_dead_serial, k); pthread_mutex_unlock(&g_smu); return d; }
/* 2026-10-20: a finalised serial is forgotten (dropped from g_dead_serial and g_gpu_owned) once nothing can bring it back:
   no recording copy names it (dm_nvn_pin_has_serial: only a recording's texture copy brings a serial to the replay) and
   no texture-pool slot is registered with it (g_treg_refs, kept by mtl_reg_tex and tex_by_id's redirect: such a slot still
   follows the serial to the live texture at its memory). Before, both sets only grew: Breath of the Wild finalises about
   80 textures a frame and had 17.4 million entries after 30 minutes on a static screen, TOTK about 130 MB in 27 minutes. */
static nvn_hmap g_treg_refs = {.klen = 8};   /* serial -> pool slots registered with it (g_rmu) */
static uint64_t g_serial_forgotten;
static void treg_ref_locked(uint64_t serial, int delta) {   /* g_rmu held */
    if (!serial) return;
    uintptr_t n = (uintptr_t)nvn_hm_get(&g_treg_refs, &serial);
    n = delta > 0 ? n + 1 : n ? n - 1 : 0;
    if (n) nvn_hm_put(&g_treg_refs, &serial, (void *)n); else nvn_hm_del(&g_treg_refs, &serial);
}
static void serial_forget_locked_rmu(uint64_t k) {   /* g_rmu held (g_rmu -> g_pin_mu and g_rmu -> g_smu are the allowed orders) */
    extern int dm_nvn_pin_has_serial(uint64_t serial);
    if (!k || nvn_hm_get(&g_treg_refs, &k) || dm_nvn_pin_has_serial(k)) return;
    pthread_mutex_lock(&g_smu);
    if (totk_serial_del(&g_dead_serial, k)) g_serial_forgotten++;
    totk_serial_del(&g_gpu_owned, k);
    pthread_mutex_unlock(&g_smu);
}
static inline int registry_lock(void); static inline void registry_unlock(void);
static void serial_forget_if_unreferenced(uint64_t k) { registry_lock(); serial_forget_locked_rmu(k); registry_unlock(); }
static void dead_put_note(uint64_t k) {
    pthread_mutex_lock(&g_smu);
    if (g_dead_put_n == g_dead_put_cap) { g_dead_put_cap = g_dead_put_cap ? g_dead_put_cap * 2 : 256; g_dead_put = realloc(g_dead_put, g_dead_put_cap * sizeof *g_dead_put); if (!g_dead_put) MDIE("dead-serial list"); }
    g_dead_put[g_dead_put_n++] = k; g_dead_put_total++;
    pthread_mutex_unlock(&g_smu);
}
/* Called at the end of every submission: textures created for already-finalized serials are released after it completes. */
static void dead_put_flush(void) {
    pthread_mutex_lock(&g_smu); int n = g_dead_put_n; uint64_t *l = n ? malloc(n * sizeof *l) : NULL; if (n) memcpy(l, g_dead_put, n * sizeof *l); g_dead_put_n = 0; pthread_mutex_unlock(&g_smu);
    for (int i = 0; i < n; i++) { BOTW_DEAD_KEEP(l[i]) BOTW_SERIAL_NOTE(l[i], "dead_put_flush") serial_del(l[i]); treg_drop_serial(l[i]); }
    free(l);
}
uint64_t mtl_dead_serial_textures(void) { return g_dead_put_total; }
// Host record of a packaged texture: the current MTLTexture, the upload stamp, and the global write generation at the last check
