static int vertex_streams_on(void) {
    int v=atomic_load(&g_vertex_streams_on);
    if(v<0){const char *e=getenv("TOTK_VERTEX_STREAMS");v=!(e && !atoi(e));atomic_store(&g_vertex_streams_on,v);}
