            }
            TILELOG(t, "writers since the render (%d records):%s", nr, line);
        }
        if (!fresh[i] && tilelog_match(t) && e->snap && e->snap_n == t->L.size) {   // which of its own bytes the CPU changed
            const uint8_t *a = e->snap, *b = t->mem; size_t nd = 0, lo = 0, hi = 0, nz = 0;
            for (size_t q = 0; q < e->snap_n; q++) if (a[q] != b[q]) { if (!nd++) lo = q; hi = q; nz += b[q] != 0; }
            TILELOG(t, "own bytes changed since the render: %zu (offsets %#zx..%#zx, %zu now non-zero)", nd, lo, hi, nz);
        }
        if (!fresh[i]) {   // the CPU wrote it since: its bytes are newer
            if (++g_wb_skip_cpu <= 24) MLOG("[writeback] skipped (CPU wrote since the render) ser=%llu %ux%u nvnfmt=%#x lv%u", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, t->d.levels);
            wb_ent_free(e); continue;
        }
        if (!mt || bc_unpack(t->d.format, &upf, &ubpp) || t->d.target == 2 || t->d.samples > 1) { if (++g_wb_skip_fmt <= 8) MLOG("[red] GPU writeback to memory: unsupported texture ser=%llu format %#x target %d", (unsigned long long)t->serial, t->d.format, t->d.target); wb_ent_free(e); continue; }
#ifdef GAME_BOTW
        if (e->stage) {   // staged at the end of the submission that rendered it (botw_wb_stage_encode): no blit round trip
            void *tok = nvn_dirty_tracked(t->mem, t->L.size) ? nvn_dirty_gpu_write_begin(t->mem, t->L.size) : NULL;
            if (!tok) dm_guest_write_prepare(t->mem, t->L.size);
            int s = botw_wb_from_stage(e);
            nvn_dirty_gpu_write_end(tok);
            if (s == WB_POOL_GONE) { wb_ent_free(e); continue; }   // counted and logged by wb_target_lock
            if (s >= 0) {
                if (s) { BOTW_WB_LANDED(t) ++g_wb_done; } else MLOG("[red] GPU write-back to memory failed ser=%llu format %#x", (unsigned long long)t->serial, t->d.format);
                wb_ent_free(e); continue;
            }
        }
#endif
        size_t bytes = wb_tex_bytes(t);
        if (nb && (!wb_batch_on() || nb == WB_BATCH_MAX || batch_bytes + bytes > WB_BATCH_BYTES)) { wb_back_batch(batch, batch_mt, nb, batch_bytes); nb = 0; batch_bytes = 0; }
        batch[nb] = e; batch_mt[nb++] = mt; batch_bytes += bytes;
    }
    if (nb) wb_back_batch(batch, batch_mt, nb, batch_bytes);
}
static uint64_t g_pkg_uploads, g_pkg_reuploads, g_pkg_miss, g_pkg_restored;
static uint64_t g_pfv_upgrades;
// DM_NVN_DIRTYCHECK=1 (diagnostic, compared against ground truth): fully hash the pool content on every use; changed but not detected by dirty-page tracking = a missed detection
static int dirtycheck(void) { static int v = -1; if (v < 0) v = getenv("DM_NVN_DIRTYCHECK") != NULL; return v; }
static uint64_t full_hash(const uint8_t *m, uint64_t n) { uint64_t h = 1469598103934665603ull; for (uint64_t i = 0; i < n; i++) h = (h ^ m[i]) * 1099511628211ull; return h; }
// The GPU does not support BC compressed formats (A15 / A16 etc.): BC textures are created in the decompressed format and decompressed on the CPU at upload / buffer→texture copy time (nvn_bcdec.c).
// BC3 among the game textures was converted to ASTC offline by the Legacy Device Pack (dm/tools/astc_pack.py); what reaches here is the small remainder of BC. The test switch DM_TEST_NO_BC=1 forces this path on any machine
static int no_bc(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_TEST_NO_BC"); v = (e && *e && strcmp(e, "0")) || ![g_dev supportsBCTextureCompression];
        if (v) MLOG("GPU does not support BC compressed formats%s: BC textures are created in a decompressed format (BC1-5 decompressed on the GPU, BC6H / BC7 / 3D on the CPU)", e && *e && strcmp(e, "0") ? " (test switch DM_TEST_NO_BC)" : ""); }
    return v;
}
static int bc_unpack(uint32_t nvn_fmt, uint32_t *pf, int *bpp) { return no_bc() && nvn_bc_unpacked(nvn_fmt, pf, bpp); }
/* TOTK, no BC (A15/A16): BC1 textures (most of TOTK's colour textures) become ASTC 4x4 instead of RGBA8: a quarter of the
   memory. Uploads transcode on the GPU (bc1astc kernel, tex/nvn_bc1astc_msl.h) after the deswizzle; CPU paths use the C
   transcoder (tex/nvn_bc1astc.c). 3D, 1D and multisample BC1 textures keep the decompressed path. TOTK_BC1_ASTC=0 turns
   it off. probe-bc1astc checks the transcoding through Metal's ASTC decoder. */
static int bc1_fmt(uint32_t f) { return f == 0x41 || f == 0x42 || f == 0x45 || f == 0x46; }
static int bc1_rgba(uint32_t f) { return f == 0x42 || f == 0x46; }
static MTLPixelFormat bc1_astc_pf(uint32_t f) { return (f == 0x45 || f == 0x46) ? MTLPixelFormatASTC_4x4_sRGB : MTLPixelFormatASTC_4x4_LDR; }
static int pf_astc4(NSUInteger pf) { return pf == MTLPixelFormatASTC_4x4_LDR || pf == MTLPixelFormatASTC_4x4_sRGB; }
static int astc_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("TOTK_BC1_ASTC"); v = no_bc() && (!e || atoi(e)); if (v) MLOG("No BC: BC1 textures are converted to ASTC 4x4 (TOTK_BC1_ASTC=0 decompresses to RGBA8 instead)"); }
    return v;
}
static int tex_astc(const tex_t *t) { uint32_t g = t->d.target; return astc_on() && bc1_fmt(t->d.format) && (g == 1 || g == 4 || g == 7 || g == 8 || g == 9); }
/* TOTK, no BC: CPU-pool (mirrored) BC2/BC3/BC7 textures become ASTC 4x4 and unsigned BC4/BC5 EAC R11/RG11 instead of
   RGBA8 / R8 / RG8 (a quarter / half of the memory), transcoded on the GPU after the deswizzle (tex/nvn_bctc.metal,
   probe-gpu-bctc). Only uploads that take the GPU deswizzle path (pool-backed block-linear storage); others, GPU-owned
   textures and a copy the GPU starts rendering into keep the decompressed format. TOTK_BC_TRANSCODE=0 turns it off. */
static MTLPixelFormat tc_pf(uint32_t f) {
    switch (f) {
    case 0x43: case 0x44: case 0x4d: return MTLPixelFormatASTC_4x4_LDR;
    case 0x47: case 0x48: case 0x4e: return MTLPixelFormatASTC_4x4_sRGB;
    case 0x49: return MTLPixelFormatEAC_R11Unorm;
    case 0x4b: return MTLPixelFormatEAC_RG11Unorm;
    default: return MTLPixelFormatInvalid;
    }
}
static int tex_mirrored(const tex_t *t);
static id<MTLComputePipelineState> bctc_pso(void);
int mtl_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off);
static int g_mip_nodrop;   // set while re-uploading a copy at full size and in the decompressed format (the GPU renders into it)
static int tex_tc(const tex_t *t) {
    static int on = -1; if (on < 0) { const char *e = getenv("TOTK_BC_TRANSCODE"); on = no_bc() && (!e || atoi(e)); if (on) MLOG("No BC: BC2/BC3/BC7 assets are converted to ASTC 4x4, BC4/BC5 to EAC (TOTK_BC_TRANSCODE=0 decompresses instead)"); }
    uint32_t g = t->d.target; void *mb; uint64_t mo;
    return on && !g_mip_nodrop && tc_pf(t->d.format) != MTLPixelFormatInvalid && (g == 1 || g == 4 || g == 7 || g == 8 || g == 9) && tex_mirrored(t)
        && g_nvn_deswz_gpu && !nvn_tex_is_linear(&t->d) && mtl_addr((uint64_t)t->mem, t->L.size, &mb, &mo) && bctc_pso();
}
// TOTK: NVN texture swizzle selectors (0/1 = constants, 2..5 = R..A) composed with the format remap of nvn_fmt_to_mtl.
// Returns 1 when the result is not the identity.
// A view with its own swizzle (view selectors non-NULL) replaces the texture's selectors.
static int tex_swizzle_sel(const tex_t *t, const uint8_t *view_sel, int format, MTLTextureSwizzleChannels *out) {
    uint32_t pf = 0; uint8_t swz[4] = {MTLTextureSwizzleRed, MTLTextureSwizzleGreen, MTLTextureSwizzleBlue, MTLTextureSwizzleAlpha};
    if (!nvn_fmt_to_mtl(format, &pf, swz)) return 0;
    unsigned sel[4] = {t->d.swizzle_r, t->d.swizzle_g, t->d.swizzle_b, t->d.swizzle_a};
    if (view_sel) for (unsigned i = 0; i < 4; i++) sel[i] = view_sel[i];
    MTLTextureSwizzle c[4];
    for (unsigned i = 0; i < 4; i++) c[i] = (MTLTextureSwizzle)(sel[i] < 2 ? sel[i] : swz[sel[i] - 2]);
    *out = MTLTextureSwizzleChannelsMake(c[0], c[1], c[2], c[3]);
    return c[0] != MTLTextureSwizzleRed || c[1] != MTLTextureSwizzleGreen || c[2] != MTLTextureSwizzleBlue || c[3] != MTLTextureSwizzleAlpha;
}
static int tex_swizzle(const tex_t *t, int format, MTLTextureSwizzleChannels *out) { return tex_swizzle_sel(t, NULL, format, out); }
static int swizzle_eq(MTLTextureSwizzleChannels a, MTLTextureSwizzleChannels b) { return a.red == b.red && a.green == b.green && a.blue == b.blue && a.alpha == b.alpha; }
// TOTK: a texture that comes from a mod can carry descriptor fields the guest never validates and Metal refuses to
// build - it aborts the process from -[MTLTextureDescriptorInternal validateWithDevice:] (seen with The Second Quest:
// "requests 9 mipmap levels, but the dimensions (1, 1, 1) can only support 1"). Cap every guest-controlled field at
// what the hardware allows; the game's own data is always inside these bounds, so nothing changes for it.
static void tex_desc_fixup(const tex_t *t, MTLTextureDescriptor *d) {
    static uint64_t capped;
    char why[160] = "";
    NSUInteger w = d.width, h = d.height, z = d.depth;
    NSUInteger arr0 = d.arrayLength, smp0 = d.sampleCount, lv0 = d.mipmapLevelCount, w0 = d.width, h0 = d.height, z0 = d.depth;
    int is_msaa = d.textureType == MTLTextureType2DMultisample || d.textureType == MTLTextureType2DMultisampleArray;
    if (w < 1 || w > 16384) { d.width = w = w < 1 ? 1 : 16384; strlcat(why, "width, ", sizeof why); }
    if (h < 1 || h > 16384) { d.height = h = h < 1 ? 1 : 16384; strlcat(why, "height, ", sizeof why); }
    if (z < 1 || z > 2048) { d.depth = z = z < 1 ? 1 : 2048; strlcat(why, "depth, ", sizeof why); }
    NSUInteger biggest = w > h ? w : h;
    if (d.textureType == MTLTextureType3D && z > biggest) biggest = z;
    unsigned allowed = 1;
    for (NSUInteger v = biggest; v > 1; v >>= 1) allowed++;
    if (d.mipmapLevelCount > allowed) { d.mipmapLevelCount = allowed; strlcat(why, "mip levels, ", sizeof why); }
    if (d.mipmapLevelCount < 1) { d.mipmapLevelCount = 1; strlcat(why, "mip levels, ", sizeof why); }
    if (d.arrayLength < 1 || d.arrayLength > 2048) { d.arrayLength = d.arrayLength < 1 ? 1 : 2048; strlcat(why, "array length, ", sizeof why); }
    if (!(d.sampleCount == 1 || d.sampleCount == 2 || d.sampleCount == 4 || d.sampleCount == 8)) {
        d.sampleCount = 1; strlcat(why, "sample count, ", sizeof why);
    }
    if (d.sampleCount > 1 && !is_msaa) { d.sampleCount = 1; strlcat(why, "sample count, ", sizeof why); }   // only the multisample types may sample more than once
    if (d.sampleCount > 1) d.mipmapLevelCount = 1;
    if (!why[0]) return;
    if (capped++ < 6 || capped % 500 == 0) {
        size_t n = strlen(why); if (n > 2) why[n - 2] = 0;      // drop the trailing ", "
        MLOG("[tex] ser=%llu %ux%ux%u target %d declared %lux%lux%lu arr=%lu smp=%lu levels=%lu: %s exceeds hardware limits, creating as %lux%lux%lu arr=%lu smp=%lu levels=%lu (%llu so far; Metal would otherwise kill the process)",
             (unsigned long long)t->serial, (uint32_t)t->d.width, (uint32_t)t->d.height, (uint32_t)t->d.depth, (int)t->d.target,
             (unsigned long)w0, (unsigned long)h0, (unsigned long)z0, (unsigned long)arr0, (unsigned long)smp0, (unsigned long)lv0,
             why, (unsigned long)d.width, (unsigned long)d.height, (unsigned long)d.depth, (unsigned long)d.arrayLength,
             (unsigned long)d.sampleCount, (unsigned long)d.mipmapLevelCount, (unsigned long long)capped);
    }
}

static MTLTextureDescriptor *tex_desc(const tex_t *t, int packaged) {
    uint32_t pf = 0; uint8_t swz[4];
    if (!nvn_fmt_to_mtl(t->d.format, &pf, swz) || !pf) { RED_ONCE(0, "texture format %#x has no Metal equivalent (first case)", t->d.format); return nil; }
    int unp = 0; { uint32_t upf; int ubpp; if (tex_astc(t)) pf = (uint32_t)bc1_astc_pf(t->d.format); else if (tex_tc(t)) pf = (uint32_t)tc_pf(t->d.format); else if (bc_unpack(t->d.format, &upf, &ubpp)) { pf = upf; unp = 1; } }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.pixelFormat = (MTLPixelFormat)pf;
    d.width = t->d.width ? t->d.width : 1; d.height = t->d.height ? t->d.height : 1; d.depth = 1; d.arrayLength = 1;
    d.mipmapLevelCount = t->d.levels ? t->d.levels : 1;
    switch (t->d.target) {
        case 0: d.textureType = MTLTextureType1D; d.height = 1; break;
        case 2: d.textureType = MTLTextureType3D; d.depth = t->d.depth; break;
        case 3: d.textureType = MTLTextureType1DArray; d.arrayLength = t->d.height; d.height = 1; break;
        case 4: d.textureType = MTLTextureType2DArray; d.arrayLength = t->d.depth; break;
        case 5: d.textureType = MTLTextureType2DMultisample; d.sampleCount = t->d.samples; d.mipmapLevelCount = 1; break;
        case 6: d.textureType = MTLTextureType2DMultisampleArray; d.sampleCount = t->d.samples; d.arrayLength = t->d.depth; d.mipmapLevelCount = 1; break;
        case 8: d.textureType = MTLTextureTypeCube; break;
        case 9: d.textureType = MTLTextureTypeCubeArray; d.arrayLength = MAX(t->d.depth / 6, 1u); break;   // NVN depth counts layer-faces, Metal arrayLength counts cubes
        case 10: RED_ONCE(1, "buffer textures (TARGET_BUFFER) are not implemented"); return nil;
        default: d.textureType = MTLTextureType2D; break;
    }
    tex_desc_fixup(t, d);
    d.storageMode = MTLStorageModePrivate;   // Render targets and assets both go in GPU private storage (lossless compression available)
    d.usage = MTLTextureUsageShaderRead | (fmt_compressed(t->d.format) || packaged ? 0 : MTLTextureUsageRenderTarget)
            | (t->d.flags & NVN_TEXTURE_FLAGS_IMAGE ? MTLTextureUsageShaderWrite : 0)   // Image usage: shader-writable (compute kernels generating the 3D color lookup table, etc.)
            | (t->d.target == 8 && t->d.width <= 64 && !fmt_compressed(t->d.format) && !packaged ? MTLTextureUsageShaderWrite : 0)   // TOTK: small cube render targets: the cube-merge copy-out kernel writes them (nvn_cube_group.h)
            | (unp ? MTLTextureUsageShaderWrite | MTLTextureUsagePixelFormatView : 0);
    // TOTK: Metal rejects descriptor swizzle on render targets and on shader-writable textures (image use, and BC textures
    // decoded by the bcd kernel on GPUs without BC support); those get the swizzle on their sampling view (tex_by_id).
    MTLTextureSwizzleChannels sw;
    if (tex_swizzle(t, t->d.format, &sw) && !(d.usage & (MTLTextureUsageRenderTarget | MTLTextureUsageShaderWrite))) d.swizzle = sw;
    return d;
}
// In-place upgrade: when the original texture was not created with PixelFormatView (off by default, to keep Apple GPU lossless compression) but a different-format view is needed, create a new one with the original spec + PixelFormatView, copy over every slice × level, and replace the registration.
// Count: across the 4 screens character select / camp / wilderness / combat, 17473 textures needed a different-format view 0 times, so this is a fallback and does not rely on predicting which textures need it
static id<MTLTexture> tex_upgrade_pfv(const tex_t *t, id<MTLTexture> base, MTLPixelFormat view_pf) {
    if (g_tex_preparing && rp_active()) { g_tex_prepare_split = 1; return base; }
    { stor_key k;   // TOTK: a storage-shared base is recreated for every serial holding it, then this serial re-resolves
      if (stor_key_lookup(base, &k)) { if (!stor_recreate(&k, base.usage | MTLTextureUsagePixelFormatView)) return base; id<MTLTexture> nb = tex_mtl(t); return nb ? nb : base; } }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = base.textureType; d.pixelFormat = base.pixelFormat; d.width = base.width; d.height = base.height; d.depth = base.depth;   // Keep the original format, only add the format-view usage
    d.swizzle=base.swizzle;
    d.arrayLength = base.arrayLength; d.mipmapLevelCount = base.mipmapLevelCount; d.sampleCount = base.sampleCount;
    d.storageMode = base.storageMode; d.cpuCacheMode = base.cpuCacheMode; d.hazardTrackingMode = base.hazardTrackingMode;
    d.resourceOptions = base.resourceOptions; d.usage = base.usage | MTLTextureUsagePixelFormatView;
    id<MTLTexture> upgraded = [g_dev newTextureWithDescriptor:d];
    if (!upgraded) { RED_ONCE(45, "texture upgrade failed ser=%llu format %lu -> %lu", t->serial, (unsigned long)base.pixelFormat, (unsigned long)view_pf); return base; }
    res_add(upgraded);
    id<MTL4ComputeCommandEncoder> b = blit();
    NSUInteger slices = base.textureType == MTLTextureType3D ? 1 : base.arrayLength * (base.textureType == MTLTextureTypeCube || base.textureType == MTLTextureTypeCubeArray ? 6 : 1);
    for (NSUInteger l = 0; l < base.mipmapLevelCount; l++) {
        NSUInteger w = MAX(base.width >> l, 1u), h = MAX(base.height >> l, 1u), z = base.textureType == MTLTextureType3D ? MAX(base.depth >> l, 1u) : 1;
        if (base.textureType == MTLTextureType3D)
            enc_b_copy_texture(b, base, 0, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, z), upgraded, 0, l, MTLOriginMake(0, 0, 0));
        else for (NSUInteger s = 0; s < slices; s++)
            enc_b_copy_texture(b, base, s, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), upgraded, s, l, MTLOriginMake(0, 0, 0));
    }
    id holder = serial_get(t->serial);
    if ([holder isKindOfClass:[NvPkg class]]) { id<MTLTexture> old = ((NvPkg *)holder)->tex; ((NvPkg *)holder)->tex = upgraded; memset(&((NvPkg *)holder)->key, 0, sizeof(reup_key)); defer_obj_release(old); ser_bump(t->serial); }   // key 0: the upgraded texture is not recycled
    else serial_put(t->serial, upgraded);
    MLOG("texture upgraded to allow format views ser=%llu base format %lu -> view format %lu (upgrades=%llu)", t->serial, (unsigned long)base.pixelFormat, (unsigned long)view_pf, ++g_pfv_upgrades);
    return upgraded;
}
static int stor_key_lookup(id o, stor_key *k) {
    if (!o) return 0; uint64_t ok = obj_key(o);
    pthread_mutex_lock(&g_smu); stor_ent *e = nvn_hm_get(&g_stor_of_obj, &ok); if (e) *k = e->k; pthread_mutex_unlock(&g_smu);
    return e != NULL;
}
/* g_smu held. Serials still holding the entry lose their table entries (they re-resolve on next use); the base is
   retired once the submissions using it complete. */
static void stor_release_holders_locked(stor_ent *e) {
    for (int i = 0; i < e->nser; i++) {
        uint64_t s = e->ser[i]; id o = hm_get_id(&g_by_serial, &s); if (!o) continue;
        uint64_t ok = obj_key(o); if (ok != (uint64_t)(uintptr_t)e->tex) nvn_hm_del(&g_stor_of_obj, &ok);
        defer_obj_unref(o); hm_del_id(&g_by_serial, &s); BOTW_SERIAL_NOTE(s, "storage entry dropped")
    }
    e->nser = 0; ser_bump_locked(0);
}
static void stor_drop_locked(stor_ent *e) {
    stor_release_holders_locked(e);
    uint64_t bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_del(&g_stor_of_obj, &bk); nvn_hm_del(&g_by_storage, &e->k);
    defer_obj_release((__bridge id)e->tex); CFRelease(e->tex);
    free(e->ser); free(e);
}
/* Replaces the entry's base by one with the requested usage, content copied on the GPU timeline (submit thread only). */
static id<MTLTexture> stor_recreate(const stor_key *k, MTLTextureUsage usage) {
    if (g_tex_preparing && rp_active()) { g_tex_prepare_split = 1; return nil; }
    if (!on_sub_thread() || rp_active()) {   // the copy is a blit, which would end the open render pass under its draw; the serial then keeps a texture of its own
        static uint64_t n; if (++n <= 4) MLOG("storage-shared texture recreate refused (%s): the serial keeps a texture of its own", on_sub_thread() ? "inside a render pass" : "not on the submit thread");
        return nil; }
    pthread_mutex_lock(&g_smu); stor_ent *e = nvn_hm_get(&g_by_storage, k); id<MTLTexture> base = e ? (__bridge id<MTLTexture>)e->tex : nil; pthread_mutex_unlock(&g_smu);
    if (!base) return nil;
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = base.textureType; d.pixelFormat = base.pixelFormat; d.width = base.width; d.height = base.height; d.depth = base.depth;
    d.swizzle = base.swizzle; d.arrayLength = base.arrayLength; d.mipmapLevelCount = base.mipmapLevelCount; d.sampleCount = base.sampleCount;
    d.storageMode = base.storageMode; d.cpuCacheMode = base.cpuCacheMode; d.hazardTrackingMode = base.hazardTrackingMode;
    d.resourceOptions = base.resourceOptions; d.usage = usage;
    id<MTLTexture> nt = [g_dev newTextureWithDescriptor:d];
    if (!nt) { RED_ONCE(120, "storage-shared texture recreate failed %lux%lu format %lu usage %#lx", (unsigned long)base.width, (unsigned long)base.height, (unsigned long)base.pixelFormat, (unsigned long)usage); return nil; }
    res_add(nt);
    if (base.sampleCount <= 1) {
        id<MTL4ComputeCommandEncoder> b = blit();
        NSUInteger slices = base.textureType == MTLTextureType3D ? 1 : base.arrayLength * (base.textureType == MTLTextureTypeCube || base.textureType == MTLTextureTypeCubeArray ? 6 : 1);
        for (NSUInteger l = 0; l < base.mipmapLevelCount; l++) {
            NSUInteger w = MAX(base.width >> l, 1u), h = MAX(base.height >> l, 1u), z = base.textureType == MTLTextureType3D ? MAX(base.depth >> l, 1u) : 1;
            if (base.textureType == MTLTextureType3D) enc_b_copy_texture(b, base, 0, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, z), nt, 0, l, MTLOriginMake(0, 0, 0));
            else for (NSUInteger s = 0; s < slices; s++) enc_b_copy_texture(b, base, s, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), nt, s, l, MTLOriginMake(0, 0, 0));
        }
    }
    pthread_mutex_lock(&g_smu);
    e = nvn_hm_get(&g_by_storage, k);
    if (!e || (__bridge void *)base != e->tex) { pthread_mutex_unlock(&g_smu); defer_obj_release(nt); return nil; }   // the entry went away meanwhile (pool finalised)
    stor_release_holders_locked(e);
    uint64_t bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_del(&g_stor_of_obj, &bk);
    defer_obj_release(base); CFRelease(e->tex);
    e->tex = (void *)CFBridgingRetain(nt); bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_put(&g_stor_of_obj, &bk, e);
    uint64_t n = ++g_stor_recreated;
    pthread_mutex_unlock(&g_smu);
    if (n <= 8) MLOG("storage-shared texture recreated with usage %#lx (%lux%lu format %lu, %llu so far)", (unsigned long)usage, (unsigned long)base.width, (unsigned long)base.height, (unsigned long)base.pixelFormat, (unsigned long long)n);
    return nt;
}
/* NVN compression: a compressible texture in a compressible pool keeps its contents in compressed form, and a clear only
   sets the compression state - the bytes under it stay as they were. A descriptor that reads the same storage in another
   format therefore does not see such writes on hardware. 2026-10-15, the frame-wide flashes: when the game moved the
   linear depth to new memory, the deferred lighting kept reading the old depth descriptor for two frames, while the old
   memory already belonged to an RGBA8 target cleared to white; with one shared Metal texture every depth texel read
   0xFFFFFFFF = NaN, the lighting turned NaN and bloom / exposure spread it over the frame.
   So compressible textures share storage only with the same format or its sRGB / linear twin. When one of another format
   arrives, the storage changes hands: the current entry is detached (kept, with its content, for the serials and stale
   descriptors still holding it) and the newcomer's format owns the storage; a detached entry of the newcomer's format is
   taken back instead of creating a new texture, so a buffer re-initialised every frame keeps last frame's content.
   Detached entries go when nobody has held them for STOR_IDLE_SUBMITS submissions or their pool is finalised.
   TOTK_COMPRESSED_ALIAS=1 shares across formats as before (A/B). */
static uint64_t g_stor_handover, g_stor_taken_back;
static stor_ent **g_stor_det; static int g_stor_ndet, g_stor_cdet;   // detached entries (g_smu)
static int stor_compressed(const tex_t *t) { return (t->d.flags & NVN_TEXTURE_FLAGS_COMPRESSIBLE) && t->pool && (t->pool->flags & NVN_MEMORY_POOL_FLAGS_COMPRESSIBLE); }
static int compressed_alias_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_COMPRESSED_ALIAS"); on = e && atoi(e); } return on; }
static void stor_det_push_locked(stor_ent *e) {
    if (g_stor_ndet == g_stor_cdet) { g_stor_cdet = g_stor_cdet ? g_stor_cdet * 2 : 16; g_stor_det = realloc(g_stor_det, (size_t)g_stor_cdet * sizeof *g_stor_det); if (!g_stor_det) MDIE("detached storage list"); }
    g_stor_det[g_stor_ndet++] = e;
}
/* A detached entry for this storage whose base reads in pixel format pf (itself or its sRGB / linear twin), removed from the list. */
static stor_ent *stor_det_take_locked(const stor_key *k, MTLPixelFormat pf) {
    for (int i = 0; i < g_stor_ndet; i++) {
        stor_ent *d = g_stor_det[i]; MTLPixelFormat bf = ((__bridge id<MTLTexture>)d->tex).pixelFormat;
        if (!memcmp(&d->k, k, sizeof *k) && (bf == pf || !tex_need_pfv(bf, pf))) { g_stor_det[i] = g_stor_det[--g_stor_ndet]; return d; }
    }
    return NULL;
}
/* g_smu held: like stor_drop_locked, for an entry that is no longer in g_by_storage (its key may belong to another entry). */
static void stor_det_drop_locked(stor_ent *e) {
    stor_release_holders_locked(e);
    uint64_t bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_del(&g_stor_of_obj, &bk);
    defer_obj_release((__bridge id)e->tex); CFRelease(e->tex);
    free(e->ser); free(e);
}
static void stor_det_sweep(int (^pick)(const stor_ent *), uint64_t *counter) {
    pthread_mutex_lock(&g_smu);
    for (int i = 0; i < g_stor_ndet; ) {
        stor_ent *d = g_stor_det[i];
        if (pick(d)) { g_stor_det[i] = g_stor_det[--g_stor_ndet]; stor_det_drop_locked(d); (*counter)++; } else i++;
    }
    pthread_mutex_unlock(&g_smu);
}
/* The object a serial should hold for texture t when another serial already has the same storage and layout:
   the shared base, or a format view on it. nil: the caller creates a texture of its own and publishes it. */
static id<MTLTexture> stor_acquire(const tex_t *t, MTLTextureDescriptor *d) {
    stor_key k; if (!stor_on() || !stor_key_of(t, &k)) return nil;
    MTLPixelFormat pf = d.pixelFormat;
    pthread_mutex_lock(&g_smu);
    stor_ent *e = nvn_hm_get(&g_by_storage, &k); id<MTLTexture> base = e ? (__bridge id<MTLTexture>)e->tex : nil;
    if (!base) { pthread_mutex_unlock(&g_smu); return nil; }
    int pfv = pf != base.pixelFormat && tex_need_pfv(base.pixelFormat, pf);
    if (pfv && stor_compressed(t) && !compressed_alias_on()) {   /* another format of compressed storage: it changes hands (see stor_compressed) */
        MTLPixelFormat bf = base.pixelFormat;
        stor_ent *back = stor_det_take_locked(&k, pf);
        nvn_hm_del(&g_by_storage, &e->k); stor_det_push_locked(e);
        uint64_t n = ++g_stor_handover;
        if (back) { nvn_hm_put(&g_by_storage, &back->k, back); e = back; base = (__bridge id<MTLTexture>)back->tex; pfv = pf != base.pixelFormat && tex_need_pfv(base.pixelFormat, pf); g_stor_taken_back++; }
        if (n <= 8) MLOG("compressible texture serial %llu (NVN format %#x, Metal %lu, %ux%u) takes over storage %p from Metal format %lu%s (%llu so far)",
                         (unsigned long long)t->serial, t->d.format, (unsigned long)pf, t->d.width, t->d.height, (void *)t->mem, (unsigned long)bf,
                         back ? ", back on its earlier texture" : ", with a new texture", (unsigned long long)n);
        if (!back) { pthread_mutex_unlock(&g_smu); return nil; }   /* the caller creates the texture and publishes it as the storage's owner */
    }
    MTLTextureUsage want = base.usage | d.usage | (pfv ? MTLTextureUsagePixelFormatView : 0);
    if (want == base.usage && pf == base.pixelFormat) { g_stor_shared++; pthread_mutex_unlock(&g_smu); goto logged; }
    pthread_mutex_unlock(&g_smu);
    if (want != base.usage) { base = stor_recreate(&k, want); if (!base) return nil; }
    if (pf != base.pixelFormat) {
        id<MTLTexture> v = [base newTextureViewWithPixelFormat:pf];
        if (!v) { RED_ONCE(121, "storage-shared format view %lu on %lu failed", (unsigned long)pf, (unsigned long)base.pixelFormat); return nil; }
        pthread_mutex_lock(&g_smu);
        e = nvn_hm_get(&g_by_storage, &k);
        if (!e || (__bridge void *)base != e->tex) { pthread_mutex_unlock(&g_smu); return nil; }
        uint64_t ok = obj_key(v); nvn_hm_put(&g_stor_of_obj, &ok, e); g_stor_viewed++;
        pthread_mutex_unlock(&g_smu);
        base = v;
    } else { pthread_mutex_lock(&g_smu); g_stor_shared++; pthread_mutex_unlock(&g_smu); }
logged:
    { static uint64_t logged; if (logged++ < 6) MLOG("texture serial %llu shares storage %p (%ux%ux%u lv%u target %d format %lu%s) with an earlier serial", (unsigned long long)t->serial, (void *)t->mem, t->d.width, t->d.height, t->d.depth, t->d.levels, t->d.target, (unsigned long)pf, pf == ((id<MTLTexture>)base).parentTexture.pixelFormat || !((id<MTLTexture>)base).parentTexture ? "" : " via a format view"); }
    return base;
}
/* Registers a texture just created for t as the owner of its storage (unless one appeared meanwhile). */
static void stor_publish(const tex_t *t, id<MTLTexture> mt) {
    stor_key k; if (!stor_on() || !stor_key_of(t, &k)) return;
    pthread_mutex_lock(&g_smu);
    if (!nvn_hm_get(&g_by_storage, &k)) {
        static uint64_t near;   // diagnostic: another layout already lives at this storage (first 12): on hardware the two descriptors read the same bytes
        if (near < 12) for (uint32_t i = 0; i < g_by_storage.cap; i++) { stor_ent *o = g_by_storage.vals[i];
            if (o && o->k.mem == k.mem && o->k.size == k.size) { near++;
                MLOG("storage %p (%llu bytes): serial %llu creates %ux%ux%u lv%u target %u samples %u bpb %u depth %u beside an existing %ux%ux%u lv%u target %u samples %u bpb %u depth %u (format %#x)", (void *)t->mem, (unsigned long long)k.size, (unsigned long long)t->serial,
                     k.w, k.h, k.d, k.levels, k.target, k.samples, k.bpb, k.depth_fmt, o->k.w, o->k.h, o->k.d, o->k.levels, o->k.target, o->k.samples, o->k.bpb, o->k.depth_fmt, t->d.format); break; } }
        stor_ent *e = calloc(1, sizeof *e); if (!e) MDIE("storage entry");
        e->k = k; e->tex = (void *)CFBridgingRetain(mt); e->idle_fence = g_fence;
        nvn_hm_put(&g_by_storage, &e->k, e); uint64_t ok = obj_key(mt); nvn_hm_put(&g_stor_of_obj, &ok, e); g_stor_entries++;
    }
    pthread_mutex_unlock(&g_smu);
}
/* Submission end: entries nobody has held for STOR_IDLE_SUBMITS submissions are dropped. */
static void stor_collect_drop(int (^pick)(const stor_ent *), uint64_t *counter) {
    pthread_mutex_lock(&g_smu);
    stor_ent **gone = NULL; int n = 0, cap = 0;
    for (uint32_t i = 0; i < g_by_storage.cap; i++) {
        stor_ent *e = g_by_storage.vals[i];
        if (e && pick(e)) { if (n == cap) { cap = cap ? cap * 2 : 16; gone = realloc(gone, (size_t)cap * sizeof *gone); if (!gone) MDIE("storage sweep"); } gone[n++] = e; }
    }
    for (int i = 0; i < n; i++) stor_drop_locked(gone[i]);
    *counter += (uint64_t)n;
    pthread_mutex_unlock(&g_smu);
    free(gone);
}
/* TOTK (2026-10-20): render targets the game stopped drawing into. The game keeps its canvas and scene targets per output
   size (DynamicTextureAllocator): switching 1080p -> 1440p -> native -> 1080p left every size's targets initialised, so
   their storage entries stayed held and each size's set stayed in GPU memory (+640 MB GPU allocated, +850 MB footprint on
   the M3 Pro after four switches; on hardware they are bytes of the game's fixed heap, here they are Metal textures of
   their own). An entry that was a render target in at least STOR_RT_MIN_FRAMES frames and has not been one for
   STOR_RT_IDLE_FRAMES frames is dropped like a finalised pool's entry: holders re-resolve, the texture goes once the
   submissions using it complete. A per-frame target is written again before it is read, so one that comes back (the
   game returns to that size) gets a new texture and is redrawn; textures drawn once and only sampled afterwards
   (cube maps, baked tables) never reach STOR_RT_MIN_FRAMES and are kept. Only targets last drawn before the latest size
   change (settings display.*, the window crop, mtl_rt_size_changed) go: without one nothing is released, so a picture
   the game keeps showing without redrawing it (the pause menu's frozen scene) is never touched. TOTK_RT_EVICT=0 keeps
   them all (A/B). */
#define STOR_RT_MIN_FRAMES 120
#define STOR_RT_IDLE_FRAMES 1200
/* GPU memory tight (above STOR_RT_TIGHT_PCT percent of the budget, or the budget guard asked for relief): targets of an
   earlier size go after STOR_RT_IDLE_TIGHT frames without a draw. They were last drawn before the size change, so the
   game draws at another size now; a target the game comes back to is made again and redrawn. */
#define STOR_RT_TIGHT_PCT 70
#define STOR_RT_IDLE_TIGHT 60
static uint64_t stor_rt_idle_frames(void) {
    uint64_t budget = gpu_budget_bytes();
    if (atomic_load(&g_budget_relief) || (budget && (uint64_t)g_dev.currentAllocatedSize > budget / 100 * STOR_RT_TIGHT_PCT)) return STOR_RT_IDLE_TIGHT;
    return STOR_RT_IDLE_FRAMES;
}
static uint64_t g_stor_rt_evicted, g_stor_rt_evicted_bytes;
static _Atomic uint64_t g_rt_size_frame;   /* frame of the latest output / scene size change (0: none yet) */
/* +120: a size is applied up to 0.4 s after the request (output_latch); targets still drawn afterwards stay newer than the change */
void mtl_rt_size_changed(void) { atomic_store(&g_rt_size_frame, atomic_load(&g_cur_frame) + 120); }
uint64_t mtl_rt_size_frame(void) { return atomic_load(&g_rt_size_frame); }   /* hle_nvn.c: the auto frame cap leaves the change out */
/* The game's own scene size changes (dynamic resolution, scene_size_note) count as size changes too (2026-10-28): without
   them a session that never touched the settings never released a target, and one drop to 2048x1280 and back added a
   second set of targets (2.3 -> 5.1 GB at nvn_mtl.m's texture creation) until the budget guard stopped the game twice.
   Stamped at the frame the new size was seen, not +120 like a requested change: it is already in effect, so every target
   drawn since (the pause menu's frozen scene among them) is newer than it and kept. Kept apart from g_rt_size_frame so
   the auto frame cap (hle_nvn.c) does not treat the game's frequent resolution steps as requested changes. */
static _Atomic uint64_t g_rt_scene_frame;
static uint64_t rt_changed_frame(void) { uint64_t a = atomic_load(&g_rt_size_frame), b = atomic_load(&g_rt_scene_frame); return a > b ? a : b; }
static int stor_rt_evict_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_RT_EVICT"); on = !e || atoi(e); } return on; }
/* A pass renders into mt (a base texture or a view on one): stamp its storage entry. */
static void stor_note_attach(id<MTLTexture> mt) {
    if (!mt || !stor_rt_evict_on()) return;
    uint64_t frame = atomic_load_explicit(&g_cur_frame, memory_order_relaxed), ok = obj_key(mt), pk = mt.parentTexture ? obj_key(mt.parentTexture) : 0;
    pthread_mutex_lock(&g_smu);
    stor_ent *e = nvn_hm_get(&g_stor_of_obj, &ok); if (!e && pk) e = nvn_hm_get(&g_stor_of_obj, &pk);
    if (e && e->rt_frame != frame) { e->rt_frame = frame; e->rt_frames++; }
    pthread_mutex_unlock(&g_smu);
}
static void stor_sweep(uint64_t fence) {
    stor_collect_drop(^int(const stor_ent *e) { return !e->nser && fence > e->idle_fence + STOR_IDLE_SUBMITS; }, &g_stor_swept);
    if (stor_rt_evict_on()) {
        static uint64_t last_check; uint64_t frame = atomic_load_explicit(&g_cur_frame, memory_order_relaxed);
        uint64_t changed = rt_changed_frame();
        /* Each target's own idle time counts, not the time since the latest change: before (2026-10-23), every new size
           change pushed the release of all older sizes' targets out by another STOR_RT_IDLE_FRAMES, so switching render
           resolutions every few seconds kept every size's set (1.1-1.8 GB with six sizes at 2560x1440 output) until the
           budget guard stopped the game. Short idle times when memory is tight (stor_rt_idle_frames). */
        uint64_t idle = stor_rt_idle_frames(); int tight = idle < STOR_RT_IDLE_FRAMES;
        if (changed && frame > changed && frame >= last_check + (tight ? 8 : 60)) { last_check = frame;   /* about once a second, or every 8 frames when tight */
            uint64_t before = g_stor_rt_evicted; __block uint64_t bytes = 0; __block uint64_t *held = NULL; __block int nheld = 0, cheld = 0;
            stor_collect_drop(^int(const stor_ent *e) { int go = e->rt_frames >= STOR_RT_MIN_FRAMES && e->rt_frame < changed && frame > e->rt_frame + idle;
                                                         if (go) { bytes += ((__bridge id<MTLTexture>)e->tex).allocatedSize;
                                                                   for (int i = 0; i < e->nser; i++) { if (nheld == cheld) { cheld = cheld ? cheld * 2 : 64; held = realloc(held, (size_t)cheld * sizeof *held); if (!held) MDIE("evicted holders"); } held[nheld++] = e->ser[i]; } }
                                                         return go; }, &g_stor_rt_evicted);
            /* Texture-pool slots registered with the holders keep a view, and a view keeps its base alive (out of the
               residency set but allocated): the slots let go too and rebuild their view if they are sampled again. */
            for (int i = 0; i < nheld; i++) treg_drop_serial(held[i]);
            free(held);
            if (g_stor_rt_evicted > before) { g_stor_rt_evicted_bytes += bytes;
                MLOG("render targets of an earlier size not drawn into for %llu frames released%s: %llu (%.1f MB) at frame %llu, %llu (%.0f MB) so far (TOTK_RT_EVICT=0 keeps them)", (unsigned long long)idle,
                     tight ? " (GPU memory tight)" : "", (unsigned long long)(g_stor_rt_evicted - before), bytes / 1048576.0, (unsigned long long)frame, (unsigned long long)g_stor_rt_evicted, g_stor_rt_evicted_bytes / 1048576.0); } }
    }
    stor_det_sweep(^int(const stor_ent *e) { return !e->nser && fence > e->idle_fence + STOR_IDLE_SUBMITS; }, &g_stor_swept);
}
/* TOTK_STOR_DUMP=1 (diagnostic): the storage-shared entries grouped by size, with their holders (live = the newest
   texture initialised at that memory; dead = finalised serial). */
static void stor_dump_(int force) {
    static int on = -1; if (on < 0) on = getenv("TOTK_STOR_DUMP") != NULL; if (!on && !force) return;
    extern int nvn_tex_live_at(const void *mem, tex_t *out);
    enum { G = 48 }; struct { uint32_t w, h; int n, held, live, dead, other; uint64_t bytes, idle; } g[G]; int ng = 0;
    pthread_mutex_lock(&g_smu);
    for (uint32_t i = 0; i < g_by_storage.cap; i++) { stor_ent *e = g_by_storage.vals[i]; if (!e) continue;
        int j = 0; while (j < ng && (g[j].w != e->k.w || g[j].h != e->k.h)) j++;
        if (j == ng) { if (ng == G) continue; memset(&g[ng], 0, sizeof g[ng]); g[ng].w = e->k.w; g[ng].h = e->k.h; ng++; }
        g[j].n++; g[j].bytes += ((__bridge id<MTLTexture>)e->tex).allocatedSize; if (e->nser) g[j].held++; else g[j].idle++;
        tex_t live; int have = nvn_tex_live_at((const void *)(uintptr_t)e->k.mem, &live);
        for (int k = 0; k < e->nser; k++) { uint64_t s = e->ser[k];
            if (totk_serial_has(&g_dead_serial, s)) g[j].dead++; else if (have && live.serial == s) g[j].live++; else g[j].other++; }
    }
    pthread_mutex_unlock(&g_smu);
    for (int j = 0; j < ng; j++) if (g[j].bytes >= (4u << 20))
        MLOG("[stor-dump] %ux%u: %d entries %llu MB, held %d (holders: live %d, dead %d, other %d), idle %llu", g[j].w, g[j].h, g[j].n, (unsigned long long)(g[j].bytes >> 20), g[j].held, g[j].live, g[j].dead, g[j].other, (unsigned long long)g[j].idle);
}
/* A memory pool is finalised: its storage entries go with it. */
static void stor_drop_range(uintptr_t lo, uintptr_t hi) {
    stor_collect_drop(^int(const stor_ent *e) { return e->k.mem >= lo && e->k.mem < hi; }, &g_stor_dropped);
    stor_det_sweep(^int(const stor_ent *e) { return e->k.mem >= lo && e->k.mem < hi; }, &g_stor_dropped);
}
// Packaged texture upload: first set read-only, then take the stamp, then read the pool memory and deswizzle into a staging buffer, and blit into a new private texture.
// Batching: uploads within one replay submission share one upload command buffer (compute encoder deswizzle + a unified blit), flushed before the replay command buffer is committed;
// the same queue executes in commit order ⇒ uploads are always finished before the first sample. Uploads outside a submission are flushed on the spot. The staging area is cut from 32 MB private blocks, held by the command buffer until completion.
static _Atomic uint64_t g_upload_ns;   // Cumulative time of deswizzle + upload encoding on the submit thread (timing instrumentation)
static _Atomic uint64_t g_upload_gpu_ns;
static id<MTL4CommandBuffer> g_up_cb;
static id<MTL4ComputeCommandEncoder> g_up_ce;
static _Atomic int g_up_alloc_busy[3];
// TOTK: the submit thread sleeps on this until an upload allocator slot's GPU feedback arrives (was a 1 ms usleep poll).
static pthread_mutex_t g_up_slot_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_up_slot_cv = PTHREAD_COND_INITIALIZER;
/* TOTK_UP_WAIT_CV (upstream #159, default on): waits for all committed uploads (q_cb on the submit thread, mtl_finish) sleep on
   g_up_slot_cv until the completion handler drops g_up_pending to 0, instead of polling it every 200 us / 1 ms -- the poll
   added up to one period of latency to every QueueFinish and helper command buffer. =0: the old polling. */
static void up_pending_wait(useconds_t poll_us) {
    static int cv = -1; if (cv < 0) { const char *e = getenv("TOTK_UP_WAIT_CV"); cv = !(e && !strcmp(e, "0")); if (!cv) MLOG("TOTK_UP_WAIT_CV=0: waiting for uploads polls again (old behaviour)"); }
    if (!cv) { while (atomic_load(&g_up_pending)) usleep(poll_us); return; }
    if (!atomic_load(&g_up_pending)) return;
    pthread_mutex_lock(&g_up_slot_mu); while (atomic_load(&g_up_pending)) pthread_cond_wait(&g_up_slot_cv, &g_up_slot_mu); pthread_mutex_unlock(&g_up_slot_mu);
}
static _Atomic uint64_t g_up_slot_waits, g_up_slot_wait_ns;
static unsigned g_up_seq;
#define UP_BLOCK_SIZE (32u * 1024u * 1024u)
typedef struct {
    __unsafe_unretained id<MTLBuffer> src;
    size_t off, row, image;
    MTLSize size;
    __unsafe_unretained id<MTLTexture> dst;   // Strongly referenced by g_up_texs until the flush is encoded
    NSUInteger slice, level;
} up_blit;
static up_blit *g_up_blits; static int g_nup_blits, g_up_blitcap;
// Without BC, BC1–5 are decompressed on the GPU (A16 logs: CPU deswizzle + CPU decompression took over 300 ms in a single frame): the GPU deswizzle writes the compressed blocks into the staging area, and at flush time, after the barrier,
// the compute kernel bcd decodes them into the texture one thread per block (the target is a 2D view in the decompressed format; an sRGB base texture is written with raw values through an RGBA8Unorm view). BC6H / BC7 / 3D textures are very few and still go through the CPU (nvn_bcdec.c)
typedef struct { __unsafe_unretained id<MTLBuffer> src, params; size_t off, poff; uint32_t bw, bh; __unsafe_unretained id<MTLTexture> view; } up_dec;   // view: held by g_up_texs within the batch, and afterwards by defer_obj_unref until the GPU finishes
static up_dec *g_up_decs; static int g_nup_decs, g_up_deccap;
static const char k_bcd_msl[] =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct P { uint off, pitch, w, h, fmt, z; };\n"   // fmt: 1 BC1, 2 BC2, 3 BC3, 4 BC4, 5 BC4 signed, 6 BC5, 7 BC5 signed
"static float3 c565(uint c) { return float3((c >> 11) & 31, (c >> 5) & 63, c & 31) / float3(31, 63, 31); }\n"
"static void col(device const uchar *b, thread float4 *o, bool four) {\n"
"  uint c0 = b[0] | (b[1] << 8), c1 = b[2] | (b[3] << 8), ix = b[4] | (b[5] << 8) | (b[6] << 16) | (b[7] << 24); float3 e0 = c565(c0), e1 = c565(c1); float4 p[4];\n"
"  p[0] = float4(e0, 1); p[1] = float4(e1, 1);\n"
"  if (four || c0 > c1) { p[2] = float4((2 * e0 + e1) / 3, 1); p[3] = float4((e0 + 2 * e1) / 3, 1); } else { p[2] = float4((e0 + e1) / 2, 1); p[3] = float4(0); }\n"
"  for (int i = 0; i < 16; i++) o[i] = p[(ix >> (2 * i)) & 3]; }\n"
"static void a8(device const uchar *b, thread float *o, bool sn) {\n"   // Single-channel block of BC4 / BC3 alpha / BC5
"  float a0 = sn ? max(float(as_type<char>(b[0])), -127.0) / 127 : b[0] / 255.0, a1 = sn ? max(float(as_type<char>(b[1])), -127.0) / 127 : b[1] / 255.0;\n"
"  bool eight = sn ? as_type<char>(b[0]) > as_type<char>(b[1]) : b[0] > b[1]; float lo = sn ? -1 : 0; float p[8]; p[0] = a0; p[1] = a1;\n"
"  for (int k = 2; k < 8; k++) p[k] = eight ? ((8 - k) * a0 + (k - 1) * a1) / 7 : (k < 6 ? ((6 - k) * a0 + (k - 1) * a1) / 5 : (k == 6 ? lo : 1));\n"
"  uint lo24 = b[2] | (b[3] << 8) | (b[4] << 16), hi24 = b[5] | (b[6] << 8) | (b[7] << 16);\n"
"  for (int i = 0; i < 16; i++) o[i] = p[i < 8 ? (lo24 >> (3 * i)) & 7 : (hi24 >> (3 * (i - 8))) & 7]; }\n"
"static void dec(device const uchar *src, device const P &p, uint2 g, thread float4 *o) {\n"
"  uint bb = (p.fmt == 1 || p.fmt == 4 || p.fmt == 5) ? 8 : 16; device const uchar *b = src + p.off + g.y * p.pitch + g.x * bb; float a[16], c[16];\n"
"  if (p.fmt == 1) col(b, o, false);\n"
"  else if (p.fmt == 2) { col(b + 8, o, true); for (int i = 0; i < 16; i++) o[i].a = ((b[i / 2] >> (4 * (i & 1))) & 15) / 15.0; }\n"
"  else if (p.fmt == 3) { col(b + 8, o, true); a8(b, a, false); for (int i = 0; i < 16; i++) o[i].a = a[i]; }\n"
"  else if (p.fmt == 4 || p.fmt == 5) { a8(b, a, p.fmt == 5); for (int i = 0; i < 16; i++) o[i] = float4(a[i], 0, 0, 1); }\n"
"  else { a8(b, a, p.fmt == 7); a8(b + 8, c, p.fmt == 7); for (int i = 0; i < 16; i++) o[i] = float4(a[i], c[i], 0, 1); } }\n"
"kernel void bcd(device const uchar *src [[buffer(0)]], device const P &p [[buffer(1)]], texture2d<float, access::write> dst [[texture(0)]], uint2 g [[thread_position_in_grid]]) {\n"
"  if (g.x >= (p.w + 3) / 4 || g.y >= (p.h + 3) / 4) return; float4 o[16]; dec(src, p, g, o);\n"
"  for (int i = 0; i < 16; i++) { uint2 q = g * 4 + uint2(i & 3, i >> 2); if (q.x < p.w && q.y < p.h) dst.write(o[i], q); } }\n"
"kernel void bcd3(device const uchar *src [[buffer(0)]], device const P &p [[buffer(1)]], texture3d<float, access::write> dst [[texture(0)]], uint2 g [[thread_position_in_grid]]) {\n"   // TOTK: one depth plane (p.z) of a 3D texture rendered as BC blocks
"  if (g.x >= (p.w + 3) / 4 || g.y >= (p.h + 3) / 4) return; float4 o[16]; dec(src, p, g, o);\n"
"  for (int i = 0; i < 16; i++) { uint2 q = g * 4 + uint2(i & 3, i >> 2); if (q.x < p.w && q.y < p.h) dst.write(o[i], uint3(q, p.z)); } }\n";
static int bcd_fmt(uint32_t f) {   // NVN format → bcd fmt; 0 = not decoded on the GPU (BC6H / BC7 / non-BC)
    switch (f) { case 0x41: case 0x42: case 0x45: case 0x46: return 1; case 0x43: case 0x47: return 2; case 0x44: case 0x48: return 3;
                 case 0x49: return 4; case 0x4a: return 5; case 0x4b: return 6; case 0x4c: return 7; default: return 0; }
}
static id<MTLComputePipelineState> bcd3_pso(void) {   // TOTK: 3D BC render targets (blk_decode)
