typedef struct { __unsafe_unretained id<MTLBuffer> src, dst, params; size_t poff; uint32_t bw, bh; } up_tca;
static up_tca *g_up_tcas; static int g_nup_tcas, g_up_tcacap;
static up_tca *g_up_tcxs; static int g_nup_tcxs, g_up_tcxcap;   // TOTK: BC2/3/4/5/7 transcode jobs (tex_tc), same shape
#include "../tex/nvn_bctc_msl.h"
