}
static NSMutableArray *g_up_texs;   // Target textures in the batch: before the flush, textures may be replaced / released within the same submission
static id<MTLBuffer> g_up_block;
/* TOTK: upload staging is pooled and stays resident. A fresh 32 MiB private block per upload batch (and a shared buffer per
   CPU-staged texture), each added to and later removed from the residency set, made every batch flush commit the residency
   set in the kernel: about 1.5 ms of the submit thread per frame once each frame is committed in chunks. Up to UP_POOL
   private blocks and UP_SPOOL shared blocks are kept resident; a block is free again when the batch that used it completed
   on the GPU. Requests larger than a block, or a pool with every block in flight, use one-off buffers retired as before. */
#define UP_POOL 6
#define UP_SPOOL 4
#if TARGET_OS_IPHONE   // iOS: about 4 GB per app in total; fewer pooled blocks (overflow uses one-off buffers as before)
#define UP_POOL_USE 2
#define UP_SPOOL_USE 2
#else
#define UP_POOL_USE UP_POOL
#define UP_SPOOL_USE UP_SPOOL
#endif
#define UP_SBLOCK_SIZE (8u * 1024u * 1024u)
static id<MTLBuffer> g_up_pool[UP_POOL], g_up_spool[UP_SPOOL]; static _Atomic int g_up_pool_busy[UP_POOL], g_up_spool_busy[UP_SPOOL];
static int g_up_pool_n, g_up_spool_n, g_up_block_pooled;
static uint32_t g_up_batch_pool, g_up_batch_spool;   // pool blocks taken by the open batch
static id<MTLBuffer> g_up_sblock; static size_t g_up_sblock_off, g_up_sblock_size; static int g_up_sblock_pooled;
