// A free pooled block (created and made resident once), or -1 when every block is in flight.
static int up_pool_take(__strong id<MTLBuffer> *pool, _Atomic int *busy, int *npool, int cap, uint32_t *mask, size_t size, MTLResourceOptions opt) {
    for (int i = 0; i < *npool; i++) if (!(*mask >> i & 1) && !atomic_load(&busy[i])) { atomic_store(&busy[i], 1); *mask |= 1u << i; g_up_pool_hits++; return i; }
