}
uint64_t mtl_upload_ns_take(void) { return atomic_exchange(&g_upload_ns, 0); }
uint64_t mtl_upload_gpu_ns_take(void) { return atomic_exchange(&g_upload_gpu_ns, 0); }
void mtl_create_stats(uint64_t *lib, uint64_t *pso) { *lib = g_bp_lib_n; *pso = g_bp_pso_n; }
void mtl_create_ns(uint64_t *lib_ns, uint64_t *pso_ns) { *lib_ns = atomic_load_explicit(&g_bp_lib_ns, memory_order_relaxed); *pso_ns = atomic_load_explicit(&g_bp_pso_ns, memory_order_relaxed); }   // Cumulative time spent synchronously creating shader libraries / pipelines on the spot (the long-frame log takes the per-frame difference)
uint64_t mtl_upload_bytes(void) { return g_bp_up_bytes; }   // Cumulative texture upload bytes
/* TOTK: textures replaced by a re-upload are kept (still resident) once the submissions that read them completed, and the
   next upload with the same description writes into one instead of creating a texture: about 30 small textures the game
   rewrites on the CPU every frame (4x4 RGBA8, 3x3x8 R8 ...) were each a new MTLTexture plus residency-set churn per frame.
   An upload writes every level and layer, so nothing of the earlier content survives. Unused entries are retired after
   REUP_IDLE submissions; TOTK_REUP_RECYCLE=0 turns it off. */
#define REUP_MAX 256
#define REUP_MAX_BYTES (1u << 20)
#define REUP_IDLE 600
typedef struct { void *tex; uint64_t fence; reup_key k; } reup_ent;   // tex: CFBridgingRetain'd MTLTexture
static reup_ent g_reup[REUP_MAX]; static int g_nreup; static os_unfair_lock g_reup_lk = OS_UNFAIR_LOCK_INIT;
static uint64_t g_reup_reused, g_reup_kept;
static int reup_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_REUP_RECYCLE"); on = !e || atoi(e); } return on; }
static reup_key reup_key_of(MTLTextureDescriptor *d) {
    reup_key k; memset(&k, 0, sizeof k); MTLTextureSwizzleChannels z = d.swizzle;
    k.pf = d.pixelFormat; k.type = d.textureType; k.w = d.width; k.h = d.height; k.z = d.depth; k.levels = d.mipmapLevelCount; k.layers = d.arrayLength;
    k.samples = d.sampleCount; k.usage = d.usage; k.storage = d.storageMode; k.swz[0] = (uint8_t)z.red; k.swz[1] = (uint8_t)z.green; k.swz[2] = (uint8_t)z.blue; k.swz[3] = (uint8_t)z.alpha;
    return k;
}
/* The texture a re-upload replaced (k: the description it was created from): keep it for reuse, or retire it as before. */
static int reup_offer(id<MTLTexture> old, const reup_key *k) {
    if (old && k && k->pf && reup_on() && old.allocatedSize <= REUP_MAX_BYTES) {
        os_unfair_lock_lock(&g_reup_lk);
        if (g_nreup < REUP_MAX) { g_reup[g_nreup++] = (reup_ent){(void *)CFBridgingRetain(old), g_fence + 1, *k}; g_reup_kept++; os_unfair_lock_unlock(&g_reup_lk); return 1; }
        os_unfair_lock_unlock(&g_reup_lk);
    }
    return 0;
}
static void reup_retire(id<MTLTexture> old, const reup_key *k) {
    if (old && !reup_offer(old, k)) defer_obj_release(old);
}
static int reup_holds(id t) {   // probe-gpu-texture-retire: t sits in the recycle pool
    int hit = 0; os_unfair_lock_lock(&g_reup_lk); for (int i = 0; i < g_nreup && !hit; i++) hit = g_reup[i].tex == (__bridge void *)t; os_unfair_lock_unlock(&g_reup_lk); return hit;
}
/* A kept texture with this description that no submission still reads; nil if none. Also retires long-unused entries. */
static id<MTLTexture> reup_take(const reup_key *k) {
    if (!g_nreup) return nil;
    id<MTLTexture> hit = nil; uint64_t done = g_done;
    os_unfair_lock_lock(&g_reup_lk);
    for (int i = 0; i < g_nreup; i++) {
        if (g_reup[i].fence > done) continue;
        if (!hit && !memcmp(&g_reup[i].k, k, sizeof *k)) { hit = CFBridgingRelease(g_reup[i].tex); g_reup[i--] = g_reup[--g_nreup]; continue; }
        if (g_reup[i].fence + REUP_IDLE < done) { defer_obj_release(CFBridgingRelease(g_reup[i].tex)); g_reup[i--] = g_reup[--g_nreup]; }
    }
    os_unfair_lock_unlock(&g_reup_lk);
    if (hit) g_reup_reused++;
    return hit;
}
/* TOTK (iPhone): Metal copies of large mipmapped CPU-pool textures leave out the top level: a quarter of the memory. The
   game samples them with normalised coordinates, so a texture one level smaller is drawn from what was its level 1 (on
   the 720p handheld screen most of them are minified anyway). Texture-ID views shift their level range (tex_by_id);
   a copy the GPU starts rendering into is uploaded again at full size (tex_mtl). 2D / 2D-array / cube textures with
   at least two levels and both sides >= TOTK_MIP_DROP_MIN (512). Not lower: at 256 the grass disappeared and the ground
   took wrong colours on an iPhone 14 (2026-10-23): data textures of that size (terrain material / grass maps) are read
   by integer texel coordinates, which a copy one level smaller does not match. TOTK_MIP_DROP=0 off, =1 on (default on
   iOS only). */
