                    size_t qoff; id<MTLBuffer> q = up_param_alloc(&qoff); if (!q) { enc_ok = 0; break; }
                    uint32_t bw4 = (w + 3) / 4, bh4 = (h + 3) / 4;
                    uint32_t *pp = (uint32_t *)((uint8_t *)q.contents + qoff); pp[0] = (uint32_t)(stg_off + off); pp[1] = (uint32_t)pitch; pp[2] = w; pp[3] = h; pp[4] = t->d.format; pp[5] = (uint32_t)(ast_off + aoff);
                    if (g_nup_tcxs == g_up_tcxcap) { g_up_tcxcap = g_up_tcxcap ? g_up_tcxcap * 2 : 256; g_up_tcxs = realloc(g_up_tcxs, g_up_tcxcap * sizeof *g_up_tcxs); }
                    g_up_tcxs[g_nup_tcxs++] = (up_tca){stg, ast, q, qoff, bw4, bh4};
                    up_blit_add(ast, ast_off + aoff, (size_t)bw4 * tco, (size_t)bw4 * tco * bh4, MTLSizeMake(w, h, 1), mt, y, l - drop);
