void pg_sub_begin_ext(uint64_t fence) { pg_sub_begin(fence); }
void pg_commit_ext(id<MTLCommandBuffer> cb) { pg_commit(cb); }
/* Format views share storage, but sRGB writes still require a distinct Metal view. The absence of a
   PixelFormatView usage requirement for linear/sRGB pairs does not mean their formats are interchangeable. */
static MTLPixelFormat attachment_format(const tex_t *t, const view_t *v, int has_v, MTLPixelFormat base) {
    if (!has_v || !v->set_format || fmt_compressed(t->d.format)) return base; /* block targets use blk_aux */
    uint32_t pf = 0; uint8_t swz[4];
    if (!nvn_fmt_to_mtl(v->format, &pf, swz) || !pf) MDIE("attachment view format %#x unsupported", v->format);
    return (MTLPixelFormat)pf;
}
static id<MTLTexture> attachment_texture(const tex_t *t, const view_t *v, int has_v) {
    __unsafe_unretained id<MTLTexture> b0 = BOTW_ATTACH_TEX_U(t); if (!b0) return nil;   // TOTK: held by the serial table (tex_mtl); the common answer takes no retain
    MTLPixelFormat bpf = b0.pixelFormat, pf = attachment_format(t, v, has_v, bpf);
    if (pf == bpf) return b0;
    id<MTLTexture> base = b0;
    if (tex_need_pfv(base.pixelFormat, pf) && !(base.usage & MTLTextureUsagePixelFormatView)) base = tex_upgrade_pfv(t, base, pf);
    /* Bounded cache: views retain their base. Evictions remain resident until their last submit finishes. */
    static id<MTLTexture> views[32]; static unsigned next;
    for (unsigned i = 0; i < 32; i++) if (views[i].parentTexture == base && views[i].pixelFormat == pf) return views[i];
    id<MTLTexture> view = [base newTextureViewWithPixelFormat:pf];
    if (!view) MDIE("attachment view creation failed: %lu -> %lu", (unsigned long)base.pixelFormat, (unsigned long)pf);
    res_add(view); unsigned slot = next++ % 32; if (views[slot]) defer_obj_release(views[slot]); views[slot] = view;
    return view;
}
static void attach(MTLRenderPassAttachmentDescriptor *a, const tex_t *t, const view_t *v, int has_v) {
    a.texture = attachment_texture(t, v, has_v);
    if (has_v && v->set_levels) a.level = v->base_level;
    if (has_v && v->set_layers) { if (t->d.target == 2) a.depthPlane = v->min_layer; else a.slice = v->min_layer; }
}
// mode 1 (clear_only): a pass opened only to land pending clears, attaching only the attachments that have clears; mode 2: the lookahead proves this pass does not use depth-stencil, so depth is not attached.
// clear_only: a pass opened only to land pending clears, attaching only the attachments that have clears - the other attachments are not touched by this pass, and attaching them costs a pointless load and store on TBDR
// (Mac character select screen: the color-clear pass drags along a 400x225 depth load and store)

/* TOTK_MFX: called with the finished pass descriptor, before the encoder is created. Learns the canvas (the last float
   target with the presented texture's aspect ratio before a pass into a presented texture: 1920x1080 docked, 1280x720 in
   handheld mode, where the final pass scales it to the 1920x1080 swapchain), notes the G-buffer depth (three or more
   colour targets and a D32F depth of their size) and, once the scene is copied, adds the UI attachment to canvas passes. */
static uint32_t g_canvas_w, g_canvas_h;   // size of the last canvas candidate (g_mfx.last_c0), for the logs
static void canvas_learn(MTL4RenderPassDescriptor *pd) {
    const tex_t *t0 = R.rt.n > 0 ? R.rt.color[0] : NULL;
    id<MTLTexture> c0 = t0 ? pd.colorAttachments[0].texture : nil;
    if (t0 && c0 && g_mfx.swap_w) {
        int to_swap = 0; for (int i = 0; i < g_mfx.nswap; i++) to_swap |= g_mfx.swap[i] == t0->serial;
        if (to_swap) {
            /* The first size is the canvas's own; this used to print the presented texture's (3840x2160 for a 2560x1440 canvas).
               Not when the copy to the window named the canvas (mfx_copy_draw), this frame or the last: in cutscenes the last
               such target is a different texture every frame, not the canvas. */
            if (!g_mfx.copy_learned && !g_mfx.copy_prev && g_mfx.last_c0 && g_mfx.canvas != g_mfx.last_c0) { g_mfx.canvas = g_mfx.last_c0; MLOG("[mfx] canvas: texture %llu (%ux%u), copied to presented texture %llu (%ux%u)", (unsigned long long)g_mfx.canvas, g_canvas_w, g_canvas_h, (unsigned long long)t0->serial, g_mfx.swap_w, g_mfx.swap_h); }
        } else if (c0.width >= 640 && fabs((double)c0.width * g_mfx.swap_h / ((double)c0.height * g_mfx.swap_w) - 1) < 0.01 && pd.colorAttachments[0].level == 0 &&
                   MFX_CANVAS_FMT_OK(c0.pixelFormat) && !pd.depthAttachment.texture)
            { g_mfx.last_c0 = t0->serial; g_canvas_w = (uint32_t)c0.width; g_canvas_h = (uint32_t)c0.height; }
    }
}
/* Our residency set (mfx_residency: scene / UI / motion / per-object textures) on the game's queue, once it exists: the
   G-buffer pass writes the per-object motion target, the canvas passes the UI layer. */
static void mfx_queue_residency(void) {
    static int added; if (added) return;
    id<MTLResidencySet> rs = mfx_residency(); if (!rs) return;
    [g_q4 addResidencySet:rs]; added = 1;
}
/* ui 0: the debug view with interpolation off (mfx_debug_only): only the G-buffer depth, the camera and the per-object
   motion are taken; no canvas search, no UI layer. */
static void mfx_pass_setup(MTL4RenderPassDescriptor *pd, int ui) {   // ui 2: the UI layer only (totk_ui_layer.h, interpolation off)
    if (ui) canvas_learn(pd);
    const tex_t *t0 = R.rt.n > 0 ? R.rt.color[0] : NULL;
    id<MTLTexture> c0 = t0 ? pd.colorAttachments[0].texture : nil;
    id<MTLTexture> dt = pd.depthAttachment.texture;
    if (ui != 2) {
    if (!g_mfx.depth_done && dt && c0 && dt.pixelFormat == MTLPixelFormatDepth32Float && dt.width == c0.width && dt.height == c0.height && dt.width >= 320) {
        int nc = 0; for (int i = 0; i < R.rt.n && i < 8; i++) nc += pd.colorAttachments[i].texture != nil;
        if (nc >= 3) { mfx_note_depth(dt); om_note_depth(dt); g_mfx.depth_done = 1; g_mfx.want_cam = 1; g_mfx.gbuf_pass = g_pass.serial; g_mfx.cam_tries = 0; }
    }
    om_pass_setup(pd);   // TOTK_OBJ_MOTION: the motion attachment of passes into the G-buffer depth
    if (g_pass.objmv) mfx_queue_residency();
    }
    if (ui && t0 && c0 && g_mfx.scene_done && g_mfx.canvas == t0->serial && R.rt.n <= 7 && pd.colorAttachments[0].level == 0 && !pd.colorAttachments[7].texture) {
        MTLRenderPassColorAttachmentDescriptor *a7 = pd.colorAttachments[7];
        a7.texture = uil_ui_target(c0.width, c0.height);
        if (uil_on()) g_uil.canvas = c0;
        a7.loadAction = g_mfx.ui_cleared ? MTLLoadActionLoad : MTLLoadActionClear; a7.clearColor = MTLClearColorMake(0, 0, 0, 0); a7.storeAction = MTLStoreActionStore;
        g_mfx.ui_cleared = 1;
        g_pass.cfmt[7] = (uint32_t)MTLPixelFormatRGBA16Float; g_pass.mfx = 1;
    }
}
/* TOTK_MFX: vertex shaders of the game's UI (layout panes, text, icons, the minimap); the first draw into the canvas with
   one of them ends the scene. */
static int mfx_ui_vs(const char *key) {
    static const char *const ui[] = {"7f2113e2", "e9fd7b43", "a662e313", "16684efc", "3e11cee5", "48c18ae6", "35cbc686", "4872bec9", "9f47ed90"};
    for (size_t i = 0; i < sizeof ui / sizeof *ui; i++) if (!strncmp(key, ui[i], 8)) return 1;
    return 0;
}
/* Key 4 / TOTK_ASPECT (runtime/aspect_patch.h): the camera sees a view of another shape squeezed into the 16:9 canvas and
   the present stretches the canvas over the window, so the UI drawn into the canvas would come out stretched as well.
   Its draws are squeezed back about the canvas centre instead, so the HUD keeps its shape in the middle 16:9 of the
   window: narrowed on a wider window (21:9), flattened on a taller one (16:10, bars above and below the HUD).
   A UI draw: into the canvas, from the first draw with a UI vertex shader on (as TOTK_MFX takes it), a quad of 6
   indices with one of the UI vertex shaders (uw_ui_vs). Everything else stays: the inventory composes its 3D scene
   (full-screen triangles, shader 0ac9a549 and its post passes) after UI draws, and its opaque quad 7d591779 belongs to
   that scene (squeezed, Link turns into a black silhouette). The canvas is learned as for TOTK_MFX (canvas_learn,
   uw_note_present); g_uw_ui: this frame's UI has begun. */
extern float runtime_aspect_now(void) __attribute__((weak_import));
#include "totk_ui_squeeze.h"
static int g_uw_ui;
_Atomic long g_uw_log;   // diagnostic "flag uw_log <frames>": log the canvas draws of that many frames
_Atomic long g_draw_log;   // diagnostic "flag draw_log <frames>": log every draw and dispatch of that many frames (same [uw] lines)
static double uw_ratio(void) { float a = runtime_aspect_now ? runtime_aspect_now() : 0; return a > 0 ? a : 0; }
static void uw_note_present(const tex_t *t) {
    int known = 0; for (int i = 0; i < g_mfx.nswap; i++) known |= g_mfx.swap[i] == t->serial;
    if (!known) g_mfx.swap[g_mfx.nswap < 4 ? g_mfx.nswap++ : (int)(t->serial % 4)] = t->serial;
    g_mfx.swap_w = t->d.width; g_mfx.swap_h = t->d.height;
}
static int uw_on_canvas(void) { return g_mfx.canvas && R.rt.n > 0 && R.rt.color[0] && R.rt.color[0]->serial == g_mfx.canvas; }
/* The TOTK_MFX UI vertex shaders and more that draw UI quads (inventory tab labels, map icons; e9c27008: the boss health
   bar's fill, drawn right after its track 1469983f; unsqueezed it sat 56 canvas pixels above the track on a 16:10 window,
   a line through the boss name, 2026-10-24). */
static int uw_ui_vs(const char *vs) {
    static const char *const more[] = {"1a40e5f5", "2117f58b", "8d4e36d0", "1469983f", "e9c27008"};
    if (mfx_ui_vs(vs)) return 1;
    for (size_t i = 0; i < sizeof more / sizeof *more; i++) if (!strncmp(vs, more[i], 8)) return 1;
    return 0;
}
/* The squeeze for this draw (totk_ui_squeeze.h): *ux narrows it, *uy flattens it, both 1 when not UI or at 16:9. */
static void uw_ui_squeeze(const char *vs, const p_draw *dw, const p_draw_idx *di, NSUInteger tw, NSUInteger th, double *ux, double *uy) {
    *ux = *uy = 1;
    /* TOTK_UI_SQUEEZE=0: the UI layouts themselves are laid out for the wide canvas (scripts/ultrawide_layout.py, the
       launcher's ultrawide resolution), so nothing is squeezed here. No ratio (the game's 16:9): no squeeze either. The
       canvas is also learned for the picture settings and Hide the HUD; without the ratio check a 16:9 window squeezed
       every UI quad to nothing once it was known (the HUD and menus vanished). */
    static int off = -1; if (off < 0) { const char *e = getenv("TOTK_UI_SQUEEZE"); off = e && !strcmp(e, "0"); }
    /* Menu flash (docs/settings.md, Known issues): a UI quad drawn before this frame's first TOTK_MFX UI shader (g_uw_ui
       still 0) is left unsqueezed, so it comes out stretched for that frame. Suspected while a menu opens or closes,
       when the game may draw the menu's own quads (uw_ui_vs's extra shaders: tab labels, map icons) first. Logged (the
       first 40, frame and shader) to confirm; TOTK_UI_SQUEEZE_EARLY=1 squeezes them as well (unverified, off). */
    static int early = -1; if (early < 0) { const char *e = getenv("TOTK_UI_SQUEEZE_EARLY"); early = e && !strcmp(e, "1"); }
    /* TOTK_REPLAY_FAST: both cases below need a 6-index draw with a vertex shader and the squeeze on; most draws fail that,
       so they leave before the 13 shader-name compares (~115 samples / 15 s on the replay thread, 2026-10-22). */
    if (replay_fast() && (off || !vs || (dw ? dw->count : di ? di->count : 0) != 6)) return;
    if (uil_on()) return;   // the UI is composed as one layer instead (totk_ui_layer.h)
    if (!off && !g_uw_ui && vs && uw_ui_vs(vs) && (dw ? dw->count : di ? di->count : 0) == 6 && uw_on_canvas() && tw && th && uw_ratio() > 0) {
        static int n; if (n < 40) { n++; MLOG("[uw] F%llu: UI quad (vs %.8s) before the UI began: %s", (unsigned long long)atomic_load(&g_cur_frame), vs, early ? "squeezed (TOTK_UI_SQUEEZE_EARLY=1)" : "not squeezed"); }
        if (early) { totk_ui_squeeze(uw_ratio(), ux, uy); return; }
    }
    if (off || !g_uw_ui || !vs || UW_NOT_UI_DRAW(vs, dw, di) || !uw_on_canvas() || !tw || !th) return;
    /* The game lays its UI out for 16:9 and maps it onto the canvas; the picture is shown at the ratio of key 4 (on a
       16:9 canvas: the present stretches it there) or at the canvas's own shape (a canvas as wide as the screen,
       TOTK_OUTPUT_RES=3440x1440, nothing stretched at the present). Either way the UI comes out wider (or, below
       16:9, taller) by the shown ratio over 16:9; a ratio * th / tw only held for a 16:9 canvas. With key 4 off the
       picture is 16:9 again (stretched over a wide canvas, UI and all): nothing to squeeze. */
    totk_ui_squeeze(uw_ratio(), ux, uy);
}
/* TOTK_MFX: the scene is complete: end the pass (the draw that follows opens it again, loading the canvas, with the UI
   attachment) and copy the canvas into this frame's scene texture. */
static void mfx_snapshot_scene(void) {
    if (g_enc) rp_end();
    id<MTLTexture> c = tex_mtl(R.rt.color[0]);
    if (!c || c.textureType != MTLTextureType2D || c.mipmapLevelCount < 1) { g_mfx.scene_done = 1; return; }
    id<MTLTexture> sc = uil_scene_target(c.width, c.height, c.pixelFormat);
    if (mfx_enabled()) mfx_queue_residency();
    g_uil.scene_cur = sc;
    id<MTL4ComputeCommandEncoder> b = blit();
    enc_b_copy_texture(b, c, 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(c.width, c.height, 1), sc, 0, 0, MTLOriginMake(0, 0, 0));
    enc_b_end(g_blit); g_blit = nil;
    g_mfx.scene_done = 1; mfx_note_scene();
}
