      if (nl) { for (int i = 0; i < 8; i++) if (cas[i].texture && cas[i].loadAction == MTLLoadActionLoad) cas[i].loadAction = MTLLoadActionDontCare;
                if (da.texture && da.loadAction == MTLLoadActionLoad) da.loadAction = MTLLoadActionDontCare;
