        g_pass.layered = lay_n != 0; g_pass.noatt = noatt;
        if (rt_range_on()) { g_pass.reg_gen = reg0; g_pass.ser_gen = ser0; }
        if (rt_range_on()) { g_pass.range_dirty=dirty0; g_pass.range_color=cas[0].texture; g_pass.range_depth=da.texture; }
