    pg_render(pd, (NSUInteger)R.rt.n);
    { void td_note(id pd, NSUInteger nc); td_note(pd, (NSUInteger)R.rt.n);
      void ts_note(id pd, NSUInteger nc); ts_note(pd, (NSUInteger)R.rt.n); }
    ser_gate();
    if (taa_pass(pd) == 2) g_mfx.want_cam = 1;   // TOTK_TAA: the G-buffer pass found; its first draw gives the camera
    camfeed_pass(pd);   // noclip: the same camera, whatever else is on
    if (mfx_enabled()) mfx_pass_setup(pd, 1);   // TOTK: MetalFX scene / UI attachments, G-buffer depth
    else {
        if (mfx_debug_only()) mfx_pass_setup(pd, 0);   // the motion / depth debug view without interpolation: G-buffer depth, camera, per-object motion
        if (uil_on()) mfx_pass_setup(pd, 2);   // the UI-layer composite: canvas, UI attachment (totk_ui_layer.h)
        else if (uw_ratio() || g_pp_sharpen || g_pp_aa >= 2 || g_fx_hud) canvas_learn(pd);
    }   // key 4: the canvas the UI is squeezed in; picture settings: the canvas they process; hide the HUD: the canvas its draws go to
    g_enc = enc_r_begin(pd);
    args_dirty_all();
    g_stat_pass++;
    g_pass_draw0 = g_stat_draw;
    par_pass_begin();
    if (totk_tl_on()) totk_tl(TL_PASS_BEGIN, g_stat_pass, 0);   // TOTK_TIMELINE: draws per pass
    if (lay_n) { g_lay.active = 1; g_lay.base = g_lay.cur = lay_first; g_lay.count = lay_n; if (g_cg_force_layers) g_lay.cur = g_cg_cur;
        if (!g_lay.passes++) MLOG("[totk] layered pass: first one covers layers %d-%d of a %lux%lu level", lay_first, lay_first + lay_n - 1, (unsigned long)g_pass.tw, (unsigned long)g_pass.th);
        PD("L %llu layered pass layers %d-%d", g_stat_pass, lay_first, lay_first + lay_n - 1); }
    if (enc_label_on()) { id<MTLTexture> lt = pd.colorAttachments[0].texture ?: pd.depthAttachment.texture ?: pd.stencilAttachment.texture; g_el_w = (int)lt.width; g_el_h = (int)lt.height; g_el_draws = 0; g_el_key[0] = 0; }
