    uint64_t mru_gen[4]; uint32_t mru_pass[4][13]; NvShader *mru_vs[4], *mru_fs[4]; NSString *mru_vb[4], *mru_fb[4]; id<MTLRenderPipelineState> mru_ps[4]; uint8_t mru_next; } @end   // TOTK (iOS, Mac async shaders): missing = stages whose variant is not translated yet; miss_sig: signature whose variant is missing (prog_fit); exp_skip: TOTK_EXP_SKIP_FS decision (0 unknown, 1 keep, 2 skip); keeps: a stage stores to memory or streams out (sph_keeps_memory), its draws are never skipped; miss_gen: totk_rt_ready_gen() when a stage was last found missing
@implementation NvProg @end
/* TOTK_EXP_SKIP_FS=<fragment key prefix>[,<prefix>...] (measurement only, 2026-10-16): drop every draw whose fragment shader key
   starts with one of the prefixes. A render pass whose draws are all dropped is never opened, so the GPU time saved is the
   whole cost of those passes (fixed per-pass overhead included): the upper bound of merging them away. Not for normal play. */
static int exp_skip_fs(NvProg *pr) {
    static int on = -1; static char list[8][17]; static int nl;
    if (on < 0) {
        const char *e = getenv("TOTK_EXP_SKIP_FS"); on = e && *e;
        if (on) { for (const char *p = e; *p && nl < 8; ) { int k = 0; while (p[k] && p[k] != ',' && p[k] != '+' && k < 16) { list[nl][k] = p[k]; k++; } list[nl][k] = 0; if (k) nl++; p += k; while (*p == ',' || *p == '+') p++; }   // '+' separates too (bench_sessions.sh splits its VAR list on ',')
                  MLOG("[experiment] TOTK_EXP_SKIP_FS=%s: skipping draws with these fragment shaders (measurement only, the picture will be missing parts)", e); }
    }
    if (!on || !pr || !pr->sh[1]) return 0;
    if (!pr->exp_skip) { int k = 1; for (int i = 0; i < nl; i++) if (!strncmp(pr->sh[1]->key, list[i], strlen(list[i]))) { k = 2; break; } pr->exp_skip = k; }
    if (pr->exp_skip == 2) { g_exp_skip_fs_n++; return 1; }
    return 0;
}
// Warm-up entry: built in the background, waiting to be taken by the submit thread. vs / fs are strong references (in pso they are only raw pointers, and the background dictionary is released when the task ends)
// A border pipeline (B row) also brings its variant functions and their cache keys (vpatch / bpatch): warm_claim files them
// with the shaders the game uses, whose own lookups then return these functions and so find the pipeline.
@interface WarmItem : NSObject { @public int kind; NSString *key, *vs_key, *fs_key; NvShader *shader, *vs, *fs; pso_key pso; id<MTLFunction> fsfn; id object;
    id<MTLFunction> vfn, bfn; NSString *vpatch_key, *bpatch_key; } @end
@implementation WarmItem @end
static NSMutableDictionary<NSString *, NvShader *> *g_shcache;

/* TOTK (2026-10-17): every c1 read of the shader stays inside its own data, so it can share a bank (c1_store). D2R decides
   this offline (c1_full.tsv from tools/c1_guard.py); TOTK never had that list, so every shader got its own 64 KiB of zeros
   (5,257 of them, 328 MB of GPU memory and as many residency-set objects after a long session), and an offline list would
   also miss the variants translated while playing. Decided from the MSL at load instead: shareable only if every
   "<stage>_c1)._m0[<index>]" index is a plain integer naming a float4 inside the data rounded up to 256 bytes plus the 256
   zero bytes that follow it in the bank (reads there give zero, as the exclusive buffer would). The translated MSL reads c1
   no other way (the cache, 7,546 variants: 5,248 have c1 data, 65 of them with a computed index). No source -> own 64 KiB. */
static int c1_reads_bounded(NSString *src, size_t len) {
    if (!src) return 0;
    const size_t limit = (((len + 255u) & ~(size_t)255u) + 256u) / 16u;   /* float4s readable as own data or zeros */
    for (const char *p = src.UTF8String; (p = strstr(p, "_c1)._m0[")); ) {
        p += 9;
        char *end; unsigned long idx = strtoul(p, &end, 10);
        if (end == p || *p < '0' || *p > '9') return 0;   /* a computed index */
        if (*end == 'u') end++;
        if (*end != ']' || idx >= limit) return 0;
        p = end;
    }
    return 1;
}
static void c1_store(NvShader *o, NSString *src) {
    size_t len = o->rf.c1_len;
    NSString *guardKey = [NSString stringWithUTF8String:o->key];
    if ([guardKey hasSuffix:@"_b"]) guardKey = [guardKey substringToIndex:guardKey.length - 2];
    static int share = -1;   /* TOTK_C1_SHARE=0: every c1 its own 64 KiB again (the behaviour before 2026-10-17, for A/B) */
    if (share < 0) { const char *e = getenv("TOTK_C1_SHARE"); share = !(e && !strcmp(e, "0")); if (!share) MLOG("TOTK_C1_SHARE=0: constant bank c1 always gets its own 64 KiB (no sharing based on the MSL scan)"); }
    const int bounded = share && c1_reads_bounded(src, len);
    os_unfair_lock_lock(&g_c1_lock);   // Both the warm-up thread and the submit thread load shaders
    if ((g_c1_full_valid && [g_c1_full containsObject:guardKey]) || !bounded) {   // Runtime index not proven bounded: exclusive 64 KiB of all zeros (same as the original implementation)
        o->c1buf = [g_dev newBufferWithLength:C1_DECL_SIZE options:MTLResourceStorageModeShared]; o->c1_gpu = o->c1buf.gpuAddress;
        if (!o->c1buf) { os_unfair_lock_unlock(&g_c1_lock); MDIE("c1 private buffer allocation failed"); }
        res_add(o->c1buf);
        memset(o->c1buf.contents, 0, C1_DECL_SIZE); memcpy(o->c1buf.contents, o->rf.c1, len);
        g_c1_alloc_bytes += C1_DECL_SIZE; g_c1_data_bytes += len; g_c1_count++; g_c1_exclusive++;
        os_unfair_lock_unlock(&g_c1_lock);
        return;
    }
    size_t need = (len + 255u) & ~((size_t)255u);
    if (!g_c1_banks) g_c1_banks = [NSMutableArray array];
    if (!g_c1_banks.count || g_c1_bank_off + need + 256u + C1_DECL_SIZE > C1_BANK_SIZE) {
        id<MTLBuffer> b = [g_dev newBufferWithLength:C1_BANK_SIZE options:MTLResourceStorageModeShared];
        if (!b) { os_unfair_lock_unlock(&g_c1_lock); MDIE("c1 buffer block allocation failed"); }
        res_add(b);
        memset(b.contents, 0, C1_BANK_SIZE);
        [g_c1_banks addObject:b];
        g_c1_bank_off = 0;
        g_c1_alloc_bytes += C1_BANK_SIZE;
    }
    id<MTLBuffer> b = g_c1_banks.lastObject;
    size_t off = g_c1_bank_off;
    memcpy((uint8_t *)b.contents + off, o->rf.c1, len);
    g_c1_bank_off += need + 256u;
    g_c1_data_bytes += len;
    g_c1_count++;
    o->c1buf = b;
    o->c1_gpu = b.gpuAddress;
    o->c1off = off;
    os_unfair_lock_unlock(&g_c1_lock);
}

