// User manifest: shaders / pipelines created synchronously on the submit thread while running on this machine, warmed up at the next launch together with the seed manifest.
// Path = DM_PSO_USER, the parent of DM_SAVE, or TOTK_PROFILE_DIR/pso_user.tsv; each local profile records its own additions.
static NSString *pso_user_path(void) {
    const char *u = getenv("DM_PSO_USER"), *save = getenv("DM_SAVE"), *profile = getenv("TOTK_PROFILE_DIR");
    if (u && *u) return @(u);
    if (save && *save) return [[@(save) stringByDeletingLastPathComponent] stringByAppendingPathComponent:@"pso_user.tsv"];
    return [(profile && *profile ? @(profile) : @"user-data") stringByAppendingPathComponent:@"pso_user.tsv"];
}
static FILE *g_pso_user; static int g_pso_user_checked;
/* Lines already in the warm lists, as 64-bit hashes of the line (seen_key): the lines themselves were ~190,000 strings,
   53 MB on the Mac (a render pipeline's key is 1,088 hex digits; the iPhone also carries the shared list's 12,000 in
   pso_list.tsv, 2026-10-23). A collision only leaves one line unrecorded. */
static NSNumber *seen_key(const char *line, size_t n) { return @(pkg_hash(line, n)); }
static NSNumber *seen_key_str(NSString *line) { const char *u = line.UTF8String; return seen_key(u, strlen(u)); }
static NSMutableSet<NSNumber *> *g_pso_user_seen;
static NSMutableSet<NSNumber *> *g_pso_shipped_seen;   // !warm_shared(): the shared list's lines, recorded but not shown as new
/* The shared list's pipelines (pso_list.tsv: every player's, 13,875 rows after #229-#272) are kept in memory only on the
   Mac. On an iPhone / iPad they are compiled into the pipeline archive before the title and dropped (warm_start,
   warm_fill_archive): kept, 6,813 render pipelines put an iPhone 14 in the world at 3.82-3.89 GB with p99 117-200 ms
   (2026-10-23). One drawn comes from the archive. TOTK_WARM_SHARED=1 / 0 forces either. */
static int warm_shared(void) {
    static int v = -1; if (v < 0) { const char *e = getenv("TOTK_WARM_SHARED"); v = e && *e ? atoi(e) != 0 : !TARGET_OS_IPHONE; }
    return v;
}
static FILE *pso_user_file(void) {
    if (g_pso_user_checked) return g_pso_user;
    g_pso_user_checked = 1;
    NSString *path = pso_user_path();
    if (path) g_pso_user = fopen(path.fileSystemRepresentation, "a");
    return g_pso_user;
}
/* TOTK automatic shader collection (user, 2026-10-16 night: "warm up, use and cache newly discovered shaders automatically"): a new shader variant
   is translated, used and written to the translation cache at once (totk_rt_variant), every cached variant is compiled
   by the next start's warm-up, and every shader / pipeline built on the submit thread goes into the warm lists. Besides
   the per-profile list, those lines also go into one shared list next to the translation cache, so what any session
   finds (the user's game, an agent's test session on a save copy) is warmed by every later start of either checkout
   (the cache directory is shared). g_collect_new: lines added this run (S shaders, R render, C compute pipelines);
   the bottom-left box shows them (shader_overlay_prepare). */
static NSString *pso_shared_path(void) { return [totk_rt_dir() stringByAppendingPathComponent:@"pso_collected.tsv"]; }
static FILE *g_pso_shared; static int g_pso_shared_checked;
static _Atomic uint64_t g_collect_new[3], g_collect_last_ns;
static void pso_user_record(const char *fmt, ...) {
    FILE *f = pso_user_file();
    if (!g_pso_shared_checked) { g_pso_shared_checked = 1; g_pso_shared = fopen(pso_shared_path().fileSystemRepresentation, "a"); }
    if (!f && !g_pso_shared) return;
    char line[8192]; va_list ap; va_start(ap, fmt); vsnprintf(line, sizeof line, fmt, ap); va_end(ap);
    if (!g_pso_user_seen) {
        g_pso_user_seen = [NSMutableSet set];
        // the app's lists count as seen too: iOS carries the shared list's pipelines in pso_list.tsv (build_ipa.py), and
        // one the warm-up had not reached yet was written again and shown as new (835 of an iPhone's first 1,795, 2026-10-22)
        NSString *dir = g_shmap_path.stringByDeletingLastPathComponent;
        NSMutableArray<NSString *> *paths = [NSMutableArray array];
        // without warm_shared() the shared list is not kept warm, so one of its pipelines drawn here is written to
        // pso_user.tsv like any other and kept warm from the next start
        for (NSString *name in warm_shared() ? @[@"pso_manifest.tsv", @"pso_list.tsv"] : @[@"pso_manifest.tsv"]) if (dir) [paths addObject:[dir stringByAppendingPathComponent:name]];
        if (!warm_shared() && dir) @autoreleasepool {   // drawn here, one is new to this device's list but not to the game (the box's count)
            g_pso_shipped_seen = [NSMutableSet set];
            NSString *txt = [NSString stringWithContentsOfFile:[dir stringByAppendingPathComponent:@"pso_list.tsv"] encoding:NSUTF8StringEncoding error:nil];
            for (NSString *old in [txt componentsSeparatedByString:@"\n"]) if (old.length && ![old hasPrefix:@"#"]) [g_pso_shipped_seen addObject:seen_key_str(old)];
        }
        NSString *user = pso_user_path(); if (user) [paths addObject:user];
        [paths addObject:pso_shared_path()];
        for (NSString *path in paths) @autoreleasepool { NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
            for (NSString *old in [txt componentsSeparatedByString:@"\n"]) if (old.length && ![old hasPrefix:@"#"]) [g_pso_user_seen addObject:seen_key_str(old)]; }
    }
    size_t ll = strlen(line);
    NSNumber *k = seen_key(line, ll && line[ll - 1] == '\n' ? ll - 1 : ll);   // Compared with the manifest file line by line (without the newline)
    if ([g_pso_user_seen containsObject:k]) return;
    [g_pso_user_seen addObject:k];
    if (f) { fputs(line, f); fflush(f); }
    if (g_pso_shared) { fputs(line, g_pso_shared); fflush(g_pso_shared); }
    int kind = line[0] == 'S' ? 0 : line[0] == 'R' ? 1 : line[0] == 'C' ? 2 : -1;
    if (kind >= 0 && [g_pso_shipped_seen containsObject:k]) kind = -1;   // from the shared list (and its archive): not new
    if (kind >= 0) { atomic_fetch_add(&g_collect_new[kind], 1); atomic_store(&g_collect_last_ns, clock_gettime_nsec_np(CLOCK_UPTIME_RAW)); }
}
static id<MTLLibrary> totk_msl_library(NSString *src, NSError **err);
// Build the library from a .metallib file without permanently occupying a file descriptor: newLibraryWithURL keeps that file open for as long as the library object lives (one per game shader - of the 258 descriptors the iOS app permanently holds in a run, 213 are these,
// while the default soft limit of an iOS process is 256; new shaders created in other acts raise it further). Here the file is mapped into memory and closed immediately, and the library is built from the in-memory data; the mapping is released when the library's data object is freed
static id<MTLLibrary> lib_from_file(NSString *path, NSError **err) {
    int fd = open(path.fileSystemRepresentation, O_RDONLY); struct stat st;
    if (fd < 0 || fstat(fd, &st) || st.st_size <= 0) { if (fd >= 0) close(fd); if (err) *err = [NSError errorWithDomain:NSPOSIXErrorDomain code:errno userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"cannot open %@", path]}]; return nil; }
    size_t len = (size_t)st.st_size; void *m = mmap(NULL, len, PROT_READ, MAP_PRIVATE, fd, 0); close(fd);
    if (m == MAP_FAILED) { if (err) *err = [NSError errorWithDomain:NSPOSIXErrorDomain code:errno userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"mmap failed %@", path]}]; return nil; }
#ifdef DM_SHELL
    // Shell: when the user's computer has no Apple shader compiler (the no-compiler mode of tools/d2rm_pack.py, gfx/tools/nometal_run.py), the "library files" contain
    // shader source rather than compiled libraries (a compiled library starts with MTLB). They are compiled here on the spot; the system caches the compiled result, and from the second launch on the same shader no longer costs this time.
    // Measured on a real device (cold): about 80 ms each on average, about 450 ms for the longest single one; one session uses several hundred.
    if (len < 4 || memcmp(m, "MTLB", 4)) { NSString *src = [[NSString alloc] initWithBytes:m length:len encoding:NSUTF8StringEncoding]; munmap(m, len);
        if (!src) { if (err) *err = [NSError errorWithDomain:NSPOSIXErrorDomain code:EILSEQ userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"neither a compiled library nor source %@", path]}]; return nil; }
        static _Atomic int n; static _Atomic long long us; CFAbsoluteTime t0 = CFAbsoluteTimeGetCurrent();
        id<MTLLibrary> l = totk_msl_library(src, err); long long dt = (long long)((CFAbsoluteTimeGetCurrent() - t0) * 1e6);
        int k = atomic_fetch_add(&n, 1) + 1; long long tot = atomic_fetch_add(&us, dt) + dt;
        if (k == 1 || k % 100 == 0 || dt >= 300000) MLOG("Shader compiled at runtime: #%d took %.0f ms, %.1f s total", k, dt / 1e3, tot / 1e6);
        return l; }
#endif
#if TARGET_OS_IPHONE
    // iOS: a mapping also holds a vnode, and the whole device has 11,400 (iPad A16, 2026-10-18); with the full warm-up keeping about
    // 8,800 libraries the table filled and the system killed the game (jetsam reason vnode-limit). Copy and unmap at once (about 110 MB for all).
    void *copy = malloc(len);
    if (copy) { memcpy(copy, m, len); munmap(m, len);
                return [g_dev newLibraryWithData:dispatch_data_create(copy, len, NULL, DISPATCH_DATA_DESTRUCTOR_FREE) error:err]; }
#endif
    dispatch_data_t d = dispatch_data_create(m, len, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ munmap(m, len); });
    return [g_dev newLibraryWithData:d error:err];
}
/* TOTK: the translated Switch shaders rely on exactly rounded IEEE float arithmetic (integer-division idioms built from
   float bit patterns, invariant positions, depth compares); Metal's default fast math breaks them. */
/* TOTK_MATH_MODE=safe|relaxed|fast picks the math mode every translated shader is compiled with (default safe).
   relaxed lets the compiler reassociate and contract but keeps infinities and NaNs; fast also assumes there are none.
   TOTK_FAST_MATH=1 is the older spelling of fast (TOTK_MATH_MODE wins when both are set). Anything but safe is for
   measurement: fast is known to break the tile-light vertex shader's integer-division idiom, so pictures from such runs
   are not evidence of correctness. Libraries and pipelines built ahead of time are safe-math builds, so another mode skips
   the precompiled shader libraries and keeps its pipeline archive in a folder of its own (par_dir). 0 safe, 1 relaxed, 2 fast. */
static int totk_math_mode(void) {
    static _Atomic int v = -1; int m = atomic_load(&v);
    if (m >= 0) return m;
    const char *e = getenv("TOTK_MATH_MODE"), *f = getenv("TOTK_FAST_MATH");
    m = 0;
    if (e && *e) {
        if (!strcmp(e, "safe")) m = 0; else if (!strcmp(e, "relaxed")) m = 1; else if (!strcmp(e, "fast")) m = 2;
        else MDIE("TOTK_MATH_MODE=%s: expected safe, relaxed or fast", e);
    } else if (f && atoi(f)) m = 2;
    int expect = -1;
    if (atomic_compare_exchange_strong(&v, &expect, m) && m)
        MLOG("[experiment] TOTK_MATH_MODE=%s: translated shaders use %s math (precompiled shader libraries skipped, pipeline archive in its own folder)", m == 1 ? "relaxed" : "fast", m == 1 ? "relaxed" : "fast");
    return atomic_load(&v);
}
/* TOTK_MSL_FAST=1 (default 0; measurement): the text pass of totk_msl_fast.h over every translated shader before it is
   compiled, with mathMode still safe. Parts: TOTK_MSL_FAST_DIV=0 / TOTK_MSL_FAST_FUNCS=0 turn off fast::divide / the
   fast:: log2 exp2 sqrt rsqrt calls (both on by default). The NaN guards on sample coordinates are not touched (see
   docs/performance-followups.md). Like another math mode, a mask other than 0 skips the precompiled safe-math shader
   libraries (they are keyed by the unmodified source) and keeps its pipeline archive in a folder of its own (par_dir);
   Metal's own cache is keyed by the source text, which the pass changes. Returns the mask (MSLF_DIV | MSLF_FUNCS). */
static int totk_msl_fast_mask(void) {
    static _Atomic int v = -1; int m = atomic_load(&v);
    if (m >= 0) return m;
    const char *e = getenv("TOTK_MSL_FAST"), *d = getenv("TOTK_MSL_FAST_DIV"), *f = getenv("TOTK_MSL_FAST_FUNCS");
    m = 0;
    if (e && atoi(e)) m = (d && !atoi(d) ? 0 : MSLF_DIV) | (f && !atoi(f) ? 0 : MSLF_FUNCS);
    int expect = -1;
    if (atomic_compare_exchange_strong(&v, &expect, m) && m)
        MLOG("[experiment] TOTK_MSL_FAST=1: fragment shaders get fast::%s%s%s (math mode unchanged; precompiled shader libraries skipped, pipeline archive in its own folder)",
             m & MSLF_DIV ? "divide" : "", m == (MSLF_DIV | MSLF_FUNCS) ? " and fast::" : "", m & MSLF_FUNCS ? "log2/exp2/sqrt/rsqrt" : "");
    return atomic_load(&v);
}
/* Invariant vertex positions (MTLCompileOptions.preserveInvariance), on by default with TOTK_OBJ_MOTION=1;
   TOTK_PRESERVE_INVARIANCE=0 / 1 turns it off / on regardless. TOTK draws a depth prepass and then the G-buffer pass with
   an EQUAL depth test, the two with different vertex functions. Without TOTK_OBJ_MOTION those functions are compiled by
   the same compiler from MSL that computes the position the same way, and they agree (docs/how-it-works.md, Early
   fragment tests). The per-object motion vertex variant (totk_objmv.h) is a third function, compiled at runtime from
   rewritten source that also stores the position to memory and passes it on as two more varyings, while the prepass's
   function usually comes precompiled from the app's shader-libs (offline toolchain): nothing makes its position
   bit-identical (the translated shaders are full of fma(), whose scheduling may differ), so the EQUAL test failed on
   scattered pixels of the G-buffer draws and textures / meshes flickered (user, 2026-10-23). Every translated vertex
   output is declared [[position, invariant]], and Metal guarantees the same position across functions only when all of
   them are compiled with preserveInvariance. So with it on every translated shader is compiled with it, the precompiled
   shader libraries (built without it) are skipped like another math mode, and pipelines go to an archive folder of their
   own (par_dir). Cost: the first launch with it compiles the shaders at runtime (Metal caches them after that), and
   vertex functions may run a little slower. */
static int totk_preserve_invariance(void) {
    static _Atomic int v = -1; int m = atomic_load(&v);
    if (m >= 0) return m;
    const char *e = getenv("TOTK_PRESERVE_INVARIANCE");
    m = e && *e ? atoi(e) != 0 : mfx_obj_motion_on();
    int expect = -1;
    if (atomic_compare_exchange_strong(&v, &expect, m) && m)
        MLOG("Vertex positions compiled invariant (preserveInvariance%s): precompiled shader libraries skipped, pipeline archive in its own folder",
             e && *e ? ", TOTK_PRESERVE_INVARIANCE=1" : ", for TOTK_OBJ_MOTION; TOTK_PRESERVE_INVARIANCE=0 turns it off");
    return atomic_load(&v);
}
/* TOTK_FRAG_MATH=safe|relaxed|fast (default: whatever TOTK_MATH_MODE gives every stage, i.e. safe): the math mode of
   translated libraries without a vertex function (fragment and compute shaders). Vertex functions keep TOTK_MATH_MODE:
   the depth prepass and the G-buffer pass draw with an EQUAL depth test from different vertex functions, so their
   positions must stay bit-identical (and fast math broke the tile-light vertex shader). Fragment and compute shaders only
   colour pixels, so a relaxed or fast mode there cannot break the depth test, but it can change pixels slightly: it is a
   measurement switch, not a default (the image must stay the base game's). Compile options are part of Metal's own cache
   key, so the first launch with another fragment mode compiles every fragment / compute shader and pipeline again (the
   vertex shaders keep their precompiled libraries); the pipeline archive moves to a folder of its own (par_dir).
   Returns 0 safe, 1 relaxed, 2 fast. */
static int totk_frag_math_mode(void) {
    static _Atomic int v = -1; int m = atomic_load(&v);
    if (m >= 0) return m;
    const char *e = getenv("TOTK_FRAG_MATH");
    m = totk_math_mode();
    if (e && *e) {
        if (!strcmp(e, "safe")) m = 0; else if (!strcmp(e, "relaxed")) m = 1; else if (!strcmp(e, "fast")) m = 2;
        else MDIE("TOTK_FRAG_MATH=%s: expected safe, relaxed or fast", e);
    }
    int expect = -1;
    if (atomic_compare_exchange_strong(&v, &expect, m) && m != totk_math_mode())
        MLOG("[experiment] TOTK_FRAG_MATH=%s: fragment and compute shaders use %s math, vertex shaders keep %s (fragment libraries compiled at runtime, pipeline archive in its own folder)",
             e, m == 2 ? "fast" : m == 1 ? "relaxed" : "safe", totk_math_mode() == 2 ? "fast" : totk_math_mode() == 1 ? "relaxed" : "safe");
    return atomic_load(&v);
}
static int totk_frag_math_differs(void) { return totk_frag_math_mode() != totk_math_mode(); }
/* A translated library with no vertex function (SPIR-V Cross puts the qualifier at the start of a line). A library with
   both stages counts as vertex: its vertex function must keep the vertex math mode. */
static int msl_no_vertex(const char *s, size_t n) {
    static const char k[] = "\nvertex ";
    if (!s) return 0;
    if (n >= 7 && !memcmp(s, "vertex ", 7)) return 0;
    return !memmem(s, n, k, sizeof k - 1);
}
static MTLCompileOptions *totk_precise_opts(void) {
    /* Made once and published only when complete: the warm-up compiles on several threads (2026-10-18), and a thread must
       never get the options before mathMode is set (that would compile with fast math). */
    static MTLCompileOptions *o; static dispatch_once_t once;
    dispatch_once(&once, ^{
        MTLCompileOptions *x = [MTLCompileOptions new];
        int m = totk_math_mode();
        if (@available(macOS 15.0, *)) x.mathMode = m == 2 ? MTLMathModeFast : m == 1 ? MTLMathModeRelaxed : MTLMathModeSafe;
        else x.fastMathEnabled = m == 2;   // no relaxed mode before macOS 15 / iOS 18: relaxed compiles as safe there
        if (totk_preserve_invariance()) x.preserveInvariance = YES;   // see totk_preserve_invariance
        o = x;
    });
    return o;
}
/* The options for a library without a vertex function: totk_precise_opts with TOTK_FRAG_MATH's math mode. */
static MTLCompileOptions *totk_frag_opts(void) {
    static MTLCompileOptions *o; static dispatch_once_t once;
    dispatch_once(&once, ^{
        if (!totk_frag_math_differs()) { o = totk_precise_opts(); return; }
        MTLCompileOptions *x = [totk_precise_opts() copy];
        int m = totk_frag_math_mode();
        if (@available(macOS 15.0, *)) x.mathMode = m == 2 ? MTLMathModeFast : m == 1 ? MTLMathModeRelaxed : MTLMathModeSafe;
        else x.fastMathEnabled = m == 2;
        o = x;
    });
    return o;
}
static MTLCompileOptions *totk_opts_for(NSString *src) {
    if (!totk_frag_math_differs() || !src) return totk_precise_opts();
    const char *c = src.UTF8String;
    return c && msl_no_vertex(c, strlen(c)) ? totk_frag_opts() : totk_precise_opts();
}
/* TOTK_FADD_INLINE (default 0, =1 on; measurement): SPIR-V Cross writes NoContraction adds as a call to
       template<typename T> [[clang::optnone]] T spvFAdd(T l, T r) { return fma(T(1), l, r); }
   (4,571 of 33,275 cached shaders, all fragment). optnone keeps the add from being fused with the multiply before it,
   but it also makes every use a real noinline call in the AIR (seen with xcrun metal -emit-llvm), which blocks the
   front end's optimisation across it (loop unrolling, CSE, hoisting). The replacement is an inline add under
   `#pragma clang fp contract(off)`: the fadd carries no contract flag, and fma(1, l, r) is exactly round(l + r), so the
   result is the same bits. Checked on the GPU (M-series, 2026-10-23) over 4M scalar and 16M vec4 products a*b + c built
   to expose fusion: the inline form gave the separately rounded result every time, in safe and in fast math mode, while
   a plain inline add (control) fused 99.7% of them in fast mode. Cost: the text changes, so Metal's cache misses once on
   these shaders and their pipelines (the precompiled shader-libs are keyed by the unmodified source and stay in use). */
static int msl_fadd_inline_on(void) {
    static _Atomic int v = -1; int m = atomic_load(&v);
    if (m >= 0) return m;
    const char *e = getenv("TOTK_FADD_INLINE"); m = e && atoi(e) != 0;
    int expect = -1;
    if (atomic_compare_exchange_strong(&v, &expect, m) && m) MLOG("[experiment] TOTK_FADD_INLINE=1: SPIR-V Cross's optnone spvFAdd compiled as an inline uncontracted add (pipeline archive in its own folder)");
    return atomic_load(&v);
}
static NSString *msl_fadd_inline(NSString *src) {
    int on = msl_fadd_inline_on();
    static NSString *from = @"[[clang::optnone]] T spvFAdd(T l, T r)\n{\n    return fma(T(1), l, r);\n}",
                    *to = @"static inline __attribute__((always_inline)) T spvFAdd(T l, T r)\n{\n#pragma clang fp contract(off)\n    return l + r;\n}";
    if (!on || !src || ![src containsString:@"[[clang::optnone]] T spvFAdd("]) return src;
    return [src stringByReplacingOccurrencesOfString:from withString:to];
}
/* Compile translated MSL with the precise options. The system compiler service (MTLCompilerService) can be stopped under
   memory pressure in the middle of a compile (iPad, 2026-10-18: "Compilation failed due to an interrupted connection:
   XPC_ERROR_CONNECTION_INTERRUPTED" while the shader warm-up was running); it restarts on the next request, so such a
   failure is retried instead of being taken as a broken shader. */
/* SPIRV-Cross lowers textureGatherOffsets (four gathers at constant offsets) to spvGatherConstOffsets, which always passes a
   component; Metal's depth2d::gather takes none, so a shader that does it on a depth texture did not compile and its draws
   were never made (4 TotK shaders, 2026-10-20). Overloads for depth2d, with the generic helper's result (.w of each).
   The source is patched only for Metal: libraries keep the name of the unpatched source (shader_lib_prebuilt). */
static NSString *msl_fix_depth_gather(NSString *src) {
    if (![src containsString:@"spvGatherConstOffsets"] || ![src containsString:@"depth2d<"]) return src;
    static NSString *fix =
        @"\n// TOTK: depth textures gather without a component\n"
        "#define TOTK_DEPTH_GATHER(SPACE) \\\n"
        "template<typename Toff, typename... Tp> inline float4 spvGatherConstOffsets(const SPACE depth2d<float>& t, sampler s, Toff coffsets, component, Tp... params) \\\n"
        "{ return float4(t.gather(s, params..., coffsets[0]).w, t.gather(s, params..., coffsets[1]).w, t.gather(s, params..., coffsets[2]).w, t.gather(s, params..., coffsets[3]).w); }\n"
        "TOTK_DEPTH_GATHER(device)\nTOTK_DEPTH_GATHER(constant)\nTOTK_DEPTH_GATHER(thread)\n#undef TOTK_DEPTH_GATHER\n\n";
    for (NSString *entry in @[@"\nfragment ", @"\nvertex ", @"\nkernel "]) {
        NSRange r = [src rangeOfString:entry];
        if (r.location != NSNotFound) return [src stringByReplacingCharactersInRange:NSMakeRange(r.location, 0) withString:fix];
    }
    return src;
}
static id<MTLLibrary> totk_msl_library(NSString *src_in, NSError **err) {
    NSError *e = nil;
    NSString *src = msl_fadd_inline(msl_fix_depth_gather(src_in));   // TOTK_FADD_INLINE; depth gathers (upstream)
    MTLCompileOptions *opts = totk_opts_for(src);   // TOTK_FRAG_MATH: fragment / compute libraries may use another math mode
    int fast = totk_msl_fast_mask();
    if (fast && src) {   // TOTK_MSL_FAST: compile the rewritten text; should it not compile, the original is compiled below
        static _Atomic int n, divs, kept, calls, failed;
        const char *c = src.UTF8String; mslf_stats st = {0};
        char *r = c ? totk_msl_fast_rewrite(c, strlen(c), fast, &st) : NULL;
        if (r) {
            NSString *fs = [[NSString alloc] initWithBytesNoCopy:r length:strlen(r) encoding:NSUTF8StringEncoding freeWhenDone:YES];
            id<MTLLibrary> lib = nil;
            for (int attempt = 1; fs; attempt++) {
                lib = [g_dev newLibraryWithSource:fs options:opts error:&e];
                if (lib || ![e.localizedDescription containsString:@"XPC_ERROR_CONNECTION_INTERRUPTED"] || attempt == 4) break;
                usleep((useconds_t)attempt * 100000);
            }
            int k = atomic_fetch_add(&n, 1) + 1, dv = atomic_fetch_add(&divs, st.divs) + st.divs, kp = atomic_fetch_add(&kept, st.divs_kept) + st.divs_kept, cl = atomic_fetch_add(&calls, st.calls) + st.calls;
            if (k == 1 || k % 1000 == 0) MLOG("[experiment] TOTK_MSL_FAST: %d shaders rewritten: %d divides fast, %d kept precise (integer use), %d fast:: calls", k, dv, kp, cl);
            if (lib) { if (err) *err = nil; return lib; }
            if (atomic_fetch_add(&failed, 1) < 5) MLOG("[red] TOTK_MSL_FAST: rewritten shader does not compile (%s); compiling the original", e.localizedDescription.UTF8String);
            e = nil;
        }
    }
    for (int attempt = 1;; attempt++) {
        id<MTLLibrary> lib = [g_dev newLibraryWithSource:src options:opts error:&e];
        BOOL interrupted = !lib && [e.localizedDescription containsString:@"XPC_ERROR_CONNECTION_INTERRUPTED"];
        if (lib || !interrupted || attempt == 4) { if (err) *err = e; return lib; }
        MLOG("[red] Shader compiler service connection interrupted (attempt %d), retrying in %d ms", attempt, attempt * 100);
        usleep((useconds_t)attempt * 100000);
    }
}
/* Patched variants of a translated shader (border colours, missing varyings, layer index, no depth output, MetalFX
   roles), compiled from their rewritten source when a draw first needs them: 80-225 ms each with a cold Metal cache, and
   most of those draws cannot be deferred (occlusion counting and the like, 2026-10-22). On the Mac the source of each one
   compiled here is kept in the shader cache (variants/<SHA-256>.metal); the next packaging compiles them into the app's
   shader-libs with the startup shaders (build_app.py variant_sources), and from then on the library is loaded instead.
   Counted for the long-frame log (mtl_variant_stats): compiled on the submit thread, loaded prebuilt, compiled in the
   background (variant_defer), and draws drawn with the plain functions while a border variant was not ready (pso_get). */
static _Atomic uint64_t g_stat_variant_n, g_stat_variant_ns, g_stat_variant_pre, g_stat_variant_bg, g_stat_variant_plain;
static __thread int g_variant_bg;   // set on variant_defer's queue: its compiles are not the submit thread's
#if !TARGET_OS_IPHONE
static id<MTLLibrary> shader_lib_prebuilt(NSData *src);
static void variant_record(NSData *raw) {
    unsigned char md[CC_SHA256_DIGEST_LENGTH]; CC_SHA256(raw.bytes, (CC_LONG)raw.length, md);
    char hex[2 * sizeof md + 1]; for (size_t i = 0; i < sizeof md; i++) snprintf(hex + 2 * i, 3, "%02x", md[i]);
    NSString *dir = [totk_rt_dir() stringByAppendingPathComponent:@"variants"], *path = [dir stringByAppendingFormat:@"/%s.metal", hex];
    if ([NSFileManager.defaultManager fileExistsAtPath:path]) return;
    [NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];
    if (![raw writeToFile:path atomically:YES]) { static int said; if (!said++) MLOG("[red] Could not save the patched variant's source: %s", path.UTF8String); }
}
#endif
static id<MTLLibrary> variant_library(NSString *src, NSError **err) {
#if !TARGET_OS_IPHONE
    NSData *raw = [src dataUsingEncoding:NSUTF8StringEncoding];
    id<MTLLibrary> pre = raw ? shader_lib_prebuilt(raw) : nil;   // compiled into the app from an earlier run's record
    if (pre) { atomic_fetch_add_explicit(&g_stat_variant_pre, 1, memory_order_relaxed); return pre; }
#endif
    uint64_t t0 = bp_now(); id<MTLLibrary> lib = totk_msl_library(src, err);
    if (g_variant_bg) atomic_fetch_add_explicit(&g_stat_variant_bg, 1, memory_order_relaxed);
    else {
        atomic_fetch_add_explicit(&g_stat_variant_n, 1, memory_order_relaxed);
        atomic_fetch_add_explicit(&g_stat_variant_ns, bp_now() - t0, memory_order_relaxed);
    }
#if !TARGET_OS_IPHONE
    if (lib && raw) variant_record(raw);
#endif
    return lib;
}
void mtl_variant_stats(uint64_t *n, uint64_t *ns, uint64_t *pre, uint64_t *bg, uint64_t *plain) {
    *n = atomic_load(&g_stat_variant_n); *ns = atomic_load(&g_stat_variant_ns); *pre = atomic_load(&g_stat_variant_pre);
    *bg = atomic_load(&g_stat_variant_bg); *plain = atomic_load(&g_stat_variant_plain);
}
/* TOTK (2026-10-15): which words of the NVN driver constant segments c0 / c2 a translated shader reads, scanned from its MSL
   at load (spirv-cross names them <stage>p_c0 / <stage>p_c2: vp_, fp_, cp_). The translation-time scan
   (scripts/shader_service.py drv_reads) matched only fragment shaders (fp_c0) until 2026-10-15, so every vertex and compute
   shader that reads c0 was given the all-zero segment: compute shaders saw 0 thread groups (the occlusion-culling kernel
   ce4993a0 then put all its cells into the first row and left the other 17 rows 0 -- every occlusion query failed and NPCs
   vanished), vertex shaders a point-size limit of 0, and both 0 for the base addresses they add offsets to. Words the replay
   fills (encode_args): c0 storage-buffer table at 0x110 (vertex) / 0x310 (compute) / 0x510 (fragment), 16 bytes per slot
   {address, size}; compute thread-group counts {x, y, z} at 0x200 and uniform-buffer table at 0x210; vertex point-size
   limit at 0x610; c2 texture / sampler handle tables. Anything else reads 0 and is reported. */
static int drv_fillable(int stage, int bank, unsigned off) {
    if (bank == 2) return (off >= 0x20 && off < 0x120) || (off >= 0x168 && off < 0x968);
    switch (stage) {
    case 0: return (off >= 0x110 && off < 0x210) || off == 0x610;
    case 1: return off >= 0x510 && off < 0x610;
    case 5: return off >= 0x200 && off < 0x410;
    default: return 0;
    }
}
/* TOTK 2026-10-16: does the function store through storage binding `name` (spirv-cross names: `(*spvDescriptorSet0.fp_s0)._m0[...] = ...`
   for stores, `&(*spvDescriptorSet0.fp_s1)` for atomics)? The reflection's rw was never set (shader_service.py tested the wrong
   flag bit), and the MSL address space over-approximates (1,140 fragment variants hold a non-const `device` pointer they only
   read), so the stores themselves are looked for. The deferred-lighting quads store a per-tile feedback word the next frame's
   class marker reads; skipping them as "0 samples passed" blacked out the title mural (claude.md "title mural missing"). */
static int msl_stores_through(NSString *src, NSString *name) {
    const char *s = src.UTF8String; if (!s || !name) return 0;
    char pat[160];
    snprintf(pat, sizeof pat, "&(*spvDescriptorSet0.%s)", name.UTF8String);
    if (strstr(s, pat)) return 1;
    snprintf(pat, sizeof pat, "(*spvDescriptorSet0.%s)._m0[", name.UTF8String);
    size_t pl = strlen(pat);
    for (const char *p = strstr(s, pat); p; p = strstr(p, pat)) {
        p += pl; int depth = 1;
        while (*p && depth) { if (*p == '[') depth++; else if (*p == ']') depth--; p++; }
        if (*p == '.') { p++; while (*p == 'x' || *p == 'y' || *p == 'z' || *p == 'w') p++; }
        while (*p == ' ') p++;
        if (p[0] == '=' && p[1] != '=') return 1;
    }
    return 0;
}
static void refl_mark_stores(NvShader *o, NSArray *bs, NSString *src) {
    if (![bs isKindOfClass:[NSArray class]] || (int)bs.count != o->rf.nb) return;   // nvn_refl_from_json keeps the json order 1:1
    for (int i = 0; i < o->rf.nb; i++) {
        nvn_rbind *b = &o->rf.b[i]; if (b->rw || (b->kind != NVN_RB_SBUFP && b->kind != NVN_RB_SBUFU)) continue;
        NSDictionary *d = bs[(NSUInteger)i]; if (![d isKindOfClass:[NSDictionary class]]) continue;
        if (msl_stores_through(src, d[@"msl_name"])) b->rw = 1;
    }
}
/* TOTK (2026-10-22, from upstream PR #159 / nxnative b0a9079): how far into each user uniform slot the shader reads
   (o->cb_ext, bytes; 0 = unknown, the whole binding). A renamed inline update makes a private copy of a uniform binding for
   each draw that reads it (upd_shadow), and the game binds whole 64 KiB blocks it updates in part (upstream measured about
   80 copies and 3.8 MB a frame on 1.4.3). The copy only needs the bytes the shader can read. Bounded only when every use of
   the binding's name in the MSL is a read "<name>)._m0[<integer>]" of the translator's "float4 _m0[4096]" block, or its
   declaration in the argument struct; anything else (a computed / dynamic index, the block passed to a function or taken
   by reference, another block layout, no MSL source) keeps the whole binding. TOTK_CB_EXTENT=1: on (default off). */
