void vc_report(void) {
    registry_lock(); unsigned vn = g_vc.n; registry_unlock();
    MLOG("[view-cache] enabled=%d serials=%u reused=%llu made=%llu stale=%llu", vc_on(), vn, (unsigned long long)g_vc_hit, (unsigned long long)g_vc_new, (unsigned long long)g_vc_stale);
}
/* Texture-pool slots whose cached view still holds a texture of a finalized serial (diagnostic for the readout line). */
static void treg_stale_report(void) {
    unsigned long stale = 0, views = 0; unsigned long long stale_mb = 0;
    registry_lock();
    for (int i = 0; i < g_ntreg; i++) if (g_treg[i].view) { views++; if (serial_is_dead(g_treg[i].t.serial)) { stale++; id<MTLTexture> v = (__bridge id<MTLTexture>)g_treg[i].view; id<MTLTexture> b = v.parentTexture ?: v; stale_mb += b.allocatedSize >> 20; } }
    registry_unlock();
    MLOG("Texture pool slot views: %lu, of which %lu hold textures with a destroyed serial (about %llu MB)", views, stale, stale_mb);
}
/* Finalized serial: drop every texture-pool slot view that still holds its texture. Before this, slots kept the view of a
   finalized texture until the slot was re-registered (over 17,000 slots holding ~11 GB after 20 s of the prologue). */
static void treg_drop_serial(uint64_t serial) {
    registry_lock();
    for (int head; (head = (int)(uintptr_t)nvn_hm_get(&g_view_heads, &serial)); )
        treg_clear_view_locked(head - 1);
    vc_drop_locked(serial);   // TOTK_VIEW_CACHE
    registry_unlock();
}
/* A slot that is no longer sampled never takes tex_by_id's invalidation path. After a CPU upload
   replaces NvPkg storage, that slot can retain its old base (or a view of it) for the entire session.
   Scan after 64 submissions only when replacements occurred. Keep logical descriptors and current
   views; defer dropping old references until commands that could have sampled them finish. */
static void treg_sweep_replaced(void) {
    static uint64_t seen_reuploads;
    if ((g_sub_serial & 63) || seen_reuploads == g_pkg_reuploads) return;
    seen_reuploads = g_pkg_reuploads;
    registry_lock();
    pthread_mutex_lock(&g_smu);
    for (int i = 0; i < g_ntreg; i++) {
        treg_t *r = &g_treg[i]; if (!r->view) continue;
        __unsafe_unretained id holder = hm_get_id(&g_by_serial, &r->t.serial);
        if (![holder isKindOfClass:[NvPkg class]]) continue;
        id<MTLTexture> base = (__bridge id<MTLTexture>)r->view;
        while (base.parentTexture) base = base.parentTexture;
        if (base == ((NvPkg *)holder)->tex) continue;
        treg_clear_view_locked(i);
        g_treg_replaced_views++;
    }
    pthread_mutex_unlock(&g_smu);
    registry_unlock();
}
/* TOTK (iPhone): Metal copies of CPU-pool textures are kept as long as the game keeps the NVNtexture, i.e. for every
   asset loaded around the player. Turning the camera resolves all of them once, and on a 4 GB iPhone the copies alone
   (530 -> 730 MB) pushed the app past its memory limit (killed with SIGKILL after a few camera turns). The pool bytes
   are still in guest memory, so a copy that no submission resolved for a while can be dropped and uploaded again when it
   is used next. Only mirrored copies the GPU never rendered into (pk->owned: the pool bytes are stale) and that are
   larger than the content-hashed small textures are dropped, least recently used first.
   When: iOS, the app's remaining allowance (os_proc_available_memory) below TOTK_TEX_EVICT_LOW_MB (250): drop until
   TOTK_TEX_EVICT_HIGH_MB (350) would be available; copies idle for EVICT_IDLE submissions, or EVICT_IDLE_CRIT below
   TOTK_TEX_EVICT_CRIT_MB (150). With 600 / 850 an iPhone 14 in the world sat at 300-470 MB for minutes: 22,000 copies
   (2.8 GB) dropped in 80 s, 94% of them uploaded again, the main cause of its long frames (2026-10-23). Before that,
   idle copies are made purgeable (pkg_purge_idle): the system takes them only when it needs the memory. Any platform: TOTK_TEX_EVICT_MB=<n> keeps the copies under n MB (tests on the Mac).
   TOTK_TEX_EVICT=0 turns it off. Runs between submissions on the replay thread, every 4 submissions. */
#define EVICT_IDLE 90
#define EVICT_IDLE_CRIT 8
typedef struct { void *pk; uint64_t used, bytes, serial; } evict_cand;
static uint64_t g_pkg_evicted, g_pkg_evicted_mb_x, g_evict_sweeps;
static int evict_cmp(const void *a, const void *b) { uint64_t x = ((const evict_cand *)a)->used, y = ((const evict_cand *)b)->used; return x < y ? -1 : x > y; }
static uint64_t env_mb(const char *name, uint64_t dflt) { const char *e = getenv(name); return (e && *e ? strtoull(e, NULL, 10) : dflt) << 20; }
static uint64_t evict_available(void) {
#if TARGET_OS_IPHONE
    return os_proc_available_memory();
#else
    return 0;
#endif
}
/* TOTK (2026-10-17, long-session memory): how many copies of CPU-pool textures are alive, and how many of them belong to a
   memory pool that is already gone (the game deleted the pool but never finalized the texture object, so mtl_tex_release
   never ran for it). Every 6,000 submits on the replay thread; the ranges are copied under g_smu, the pools looked up
   under g_mu afterwards (the two locks are never held together here). */
static void pkg_orphan_report(void) {
    if (g_sub_serial % 6000) return;
    size_t n = 0, cap = 0; struct { uintptr_t lo, hi; uint64_t bytes; } *v = NULL;
    pthread_mutex_lock(&g_smu);
    for (uint32_t i = 0; i < g_by_serial.cap; i++) {
        __unsafe_unretained id o = (__bridge id)g_by_serial.vals[i];
        if (!o || ![o isKindOfClass:[NvPkg class]]) continue;
        NvPkg *pk = (NvPkg *)o; if (!pk->tex || pk->hi <= pk->lo) continue;
        if (n == cap) { cap = cap ? cap * 2 : 4096; v = realloc(v, cap * sizeof *v); if (!v) MDIE("orphan report"); }
        v[n].lo = pk->lo; v[n].hi = pk->hi; v[n].bytes = pk->tex.allocatedSize; n++;
    }
    pthread_mutex_unlock(&g_smu);
    uint64_t total = 0, orphan_n = 0, orphan_b = 0;
    pthread_mutex_lock(&g_mu);
    for (size_t i = 0; i < n; i++) { total += v[i].bytes; if (!pidx_find_mut(&g_pools, v[i].lo, v[i].hi - v[i].lo)) { orphan_n++; orphan_b += v[i].bytes; } }
    pthread_mutex_unlock(&g_mu);
    free(v);
    MLOG("Asset texture copies as of submit %llu: %zu registered / %llu MB, of which %llu / %llu MB are in deleted memory pools", (unsigned long long)g_sub_serial, n, (unsigned long long)(total >> 20),
         (unsigned long long)orphan_n, (unsigned long long)(orphan_b >> 20));
}
/* TOTK (iPhone): copies idle for PURGE_IDLE submissions are marked purgeable (MTLPurgeableStateVolatile) instead of being
