static inline __attribute__((always_inline)) int tex_view_valid(int tid) {   // caller holds g_rmu
    if (!(tid > 0 && tid < g_ntreg)) return 0;
    treg_t *r = &g_treg[tid];
    if (!r->ok || !r->view || (r->view_pkg && r->view_dirty != treg_stamp(r->view_pkg))) return 0;
    uint64_t sg = g_ser_gen;
    if (r->view_ser == sg) return 1;
    if (r->dead_pending || !tex_ser_fast_on() || totk_life_on() || !ser_unaffected_since(r->view_ser, r->t.serial)) return 0;
    r->used = g_sub_serial; r->view_ser = sg; g_tex_ser_fast_n++; return 1;
}
/* TOTK: textureType of a view tex_fast / tex_by_id returned for tid, from view_tt (a message per bound texture before). */
static inline MTLTextureType treg_view_type(int tid, __unsafe_unretained id<MTLTexture> t) {   // caller holds g_rmu
    return tid > 0 && tid < g_ntreg && (__bridge void *)t == g_treg[tid].view ? (MTLTextureType)g_treg[tid].view_tt : t.textureType;
}
static inline __attribute__((always_inline)) void *tex_fast(int tid) {
    if (tex_view_valid(tid)) return g_treg[tid].view;
    return tex_by_id_p(tid);
}
static inline __attribute__((always_inline)) uint64_t tex_fast_rid(int tid, void **out) {
    if (tex_view_valid(tid)) { if (out) *out = g_treg[tid].view; return g_treg[tid].view_rid; }
    void *t = tex_by_id_p(tid); if (out) *out = t; return t ? ((__bridge id<MTLTexture>)t).gpuResourceID._impl : 0;
}
static MTLSamplerAddressMode wrapm(int w) {
    switch (w) { case 0: case 7: return MTLSamplerAddressModeClampToEdge; case 1: return MTLSamplerAddressModeRepeat;
        case 3: case 2: return MTLSamplerAddressModeMirrorClampToEdge; case 5: case 4: return MTLSamplerAddressModeClampToBorderColor;
        case 6: return MTLSamplerAddressModeMirrorRepeat; }
    return MTLSamplerAddressModeRepeat;
}
static id<MTLSamplerState> samp_by_id(int sid) {   // Caller holds g_rmu
    if (sid < 0 || sid >= g_nsreg || !g_sreg_ok[sid]) { RED_ONCE(12, "sampler id %d not registered", sid); return nil; }
    if (g_sview[sid]) return (__bridge id<MTLSamplerState>)g_sview[sid];
    samp_par p = g_sreg[sid];
    MTLSamplerDescriptor *d = [MTLSamplerDescriptor new];
    d.magFilter = p.magf ? MTLSamplerMinMagFilterLinear : MTLSamplerMinMagFilterNearest;
    d.minFilter = (p.minf == 1 || p.minf == 3 || p.minf == 5) ? MTLSamplerMinMagFilterLinear : MTLSamplerMinMagFilterNearest;
    d.mipFilter = p.minf <= 1 ? MTLSamplerMipFilterNotMipmapped : (p.minf == 2 || p.minf == 3) ? MTLSamplerMipFilterNearest : MTLSamplerMipFilterLinear;
    d.sAddressMode = wrapm(p.ws); d.tAddressMode = wrapm(p.wt); d.rAddressMode = wrapm(p.wr);
    if (samp_border_custom(&p)) {   // the shader returns the border colour outside the texture (fs_fn_border); inside it, edge texels must not blend with a wrong border
        if (d.sAddressMode == MTLSamplerAddressModeClampToBorderColor) d.sAddressMode = MTLSamplerAddressModeClampToEdge;
        if (d.tAddressMode == MTLSamplerAddressModeClampToBorderColor) d.tAddressMode = MTLSamplerAddressModeClampToEdge;
        if (d.rAddressMode == MTLSamplerAddressModeClampToBorderColor) d.rAddressMode = MTLSamplerAddressModeClampToEdge;
    }
    d.lodMinClamp = p.lod_min < 0 ? 0 : p.lod_min; d.lodMaxClamp = p.lod_max;
    d.maxAnisotropy = p.aniso < 1 ? 1 : p.aniso > 16 ? 16 : (NSUInteger)p.aniso;
    /* TOTK: the game's LOD bias (dropped before) plus the user's offset ("lod_bias", hundredths); the user's anisotropy
       ("aniso", TOTK_ANISO or the settings menu, live: totk_post.h) as a minimum for the game's material textures: the
       linearly filtered, mipmapped and repeating samplers (ground, walls, foliage at a grazing angle; the game asks for
       1x everywhere). Clamped samplers keep the game's setting: some read data rather than colour, and anisotropy there
       left bright green pixels along Link's outline in the inventory (upstream PR #87). Point-sampled lookups,
       unmipmapped targets, shadow-compare and min / max samplers keep it too. */
    { float bias = (pp_game_lod_bias() ? p.lod_bias : 0) + atomic_load_explicit(&g_pp_lodb, memory_order_relaxed) * 0.01f;
      if (bias != 0) { if (@available(macOS 26.0, iOS 26.0, *)) d.lodBias = fminf(fmaxf(bias, -16.f), 15.99f); } }
    { int an = atomic_load_explicit(&g_pp_aniso, memory_order_relaxed);
      int rep_s = d.sAddressMode == MTLSamplerAddressModeRepeat || d.sAddressMode == MTLSamplerAddressModeMirrorRepeat;
      int rep_t = d.tAddressMode == MTLSamplerAddressModeRepeat || d.tAddressMode == MTLSamplerAddressModeMirrorRepeat;
      if (an > (int)d.maxAnisotropy && !p.cmp_mode && !p.reduction && p.magf && (p.minf == 3 || p.minf == 5) && rep_s && rep_t &&
          d.minFilter == MTLSamplerMinMagFilterLinear && d.magFilter == MTLSamplerMinMagFilterLinear && d.mipFilter != MTLSamplerMipFilterNotMipmapped)
          d.maxAnisotropy = (NSUInteger)an; }
    if (p.cmp_mode) d.compareFunction = (MTLCompareFunction)(p.cmp_func - 1);
    d.borderColor = p.border[3] > 0.5f ? (p.border[0] > 0.5f ? MTLSamplerBorderColorOpaqueWhite : MTLSamplerBorderColorOpaqueBlack) : MTLSamplerBorderColorTransparentBlack;
    if (p.reduction > 2) die("sampler reduction filter %u unsupported", p.reduction);
    d.reductionMode = (MTLSamplerReductionMode)p.reduction;   // TOTK: NVN AVERAGE/MIN/MAX = Metal WeightedAverage/Minimum/Maximum
    d.supportArgumentBuffers = YES;
    id<MTLSamplerState> s = [g_dev newSamplerStateWithDescriptor:d];
    if (s) { g_sview[sid] = (void *)CFBridgingRetain(s); g_srid[sid] = s.gpuResourceID._impl; }
    return s;
}
static inline __attribute__((always_inline)) void *samp_fast(int sid) {
    if (sid > 0 && sid < g_nsreg && g_sreg_ok[sid] && g_sview[sid]) return g_sview[sid];
    return (__bridge void *)samp_by_id(sid);
}

// ---------- Argument buffer blocks: one block per submission, reclaimed after the GPU completes ----------
@interface NvArena : NSObject { @public id<MTLBuffer> buf; uint64_t gpu, fence; size_t used; uint8_t *cpu; } @end   // cpu: buf.contents, taken once
@implementation NvArena @end
static NSMutableArray<NvArena *> *g_arenas; static NvArena *g_cur_arena; static NSMutableArray<NvArena *> *g_sub_arenas;
static NvArena *arena_new(void) {
    // The for-in loop variable does not retain the object: take a strong reference first and then remove it from the array, otherwise what is returned after the array releases it is a dangling pointer
    uint64_t done = __atomic_load_n(&g_done, __ATOMIC_ACQUIRE);
    for (NvArena *it in g_arenas) if (it->fence && it->fence <= done) {
        if (it->fence > g_pend_reuse_done) {
            static int audit = -1; if (audit < 0) audit = getenv("TOTK_PEND_ARENA_AUDIT") != NULL;
            if (audit) { uintptr_t lo = (uintptr_t)it->buf.contents, hi = lo + it->used;
                for (int i = 0; i < g_npend; i++) if (!g_pend_kind[i] && (uintptr_t)g_pend_src[i] >= lo && (uintptr_t)g_pend_src[i] < hi) {
                    if (++g_pend_arena_hazards <= 12) MLOG("[pend-arena] CPU still references retired arena: fence=%llu cutoff=%llu dst=%#llx pin=%d",
                        (unsigned long long)it->fence, (unsigned long long)g_pend_reuse_done, (unsigned long long)g_pend_lo[i], atomic_load(&g_pend_arena_pin));
                    break;
                }
            }
            if (atomic_load(&g_pend_arena_pin)) continue;
        }
        NvArena *r = it; [g_arenas removeObject:r]; r->fence = 0; r->used = 0; return r;
    }
    NvArena *a = [NvArena new]; a->buf = [g_dev newBufferWithLength:4 << 20 options:MTLResourceStorageModeShared]; a->gpu = a->buf.gpuAddress; a->cpu = (uint8_t *)a->buf.contents; res_add(a->buf); return a;
}
static uint64_t g_arena_epoch; // A cached GPU address is valid only for its submission.
void arena_begin(void) { g_arena_epoch++; if (!g_arenas) { g_arenas = [NSMutableArray array]; g_sub_arenas = [NSMutableArray array]; } g_cur_arena = nil; }
void arena_commit(uint64_t fence) { for (NvArena *a in g_sub_arenas) { a->fence = fence; [g_arenas addObject:a]; } [g_sub_arenas removeAllObjects]; g_cur_arena = nil; }
/* TOTK: the replay's own allocations (argument blocks, uniform copies, update staging) take the arena buffer unretained.
   The out parameter of arena_alloc is __autoreleasing under ARC: every call was a retain + autorelease (an autorelease-pool
   entry) plus the caller's retain / release, about 1.5% of the replay. The buffer is held by its NvArena (g_sub_arenas, then
   g_arenas) until the GPU has completed the submission, longer than any use on the replay thread. cpu / gpu (optional) give
   the block's addresses: buf.contents is an inner-pointer method, so ARC retains and autoreleases its receiver at each use. */
static size_t arena_alloc_u(size_t n, __unsafe_unretained id<MTLBuffer> *buf, uint8_t **cpu, uint64_t *gpu) {
    n = (n + 255) & ~(size_t)255;
    if (!g_cur_arena || g_cur_arena->used + n > (size_t)(4 << 20)) {   // every arena is 4 MiB (arena_new); was a buf.length message per allocation
        pthread_mutex_lock(&g_mu); g_cur_arena = arena_new(); pthread_mutex_unlock(&g_mu);
        [g_sub_arenas addObject:g_cur_arena];
    }
    size_t off = g_cur_arena->used; g_cur_arena->used += n; *buf = g_cur_arena->buf;
    if (cpu) *cpu = g_cur_arena->cpu + off;
    if (gpu) *gpu = g_cur_arena->gpu + off;
    return off;
}
static size_t arena_alloc(size_t n, __strong id<MTLBuffer> *buf) { __unsafe_unretained id<MTLBuffer> b = nil; size_t off = arena_alloc_u(n, &b, NULL, NULL); *buf = b; return off; }

// ---------- Draw state ----------
static struct {
    const prog_t *prog;
    blend_st blend[8]; color_st color; chmask_st chmask; ms_st ms; poly_st poly; ds_st ds;
    va_st attr[16]; int nattr; vs_st stream[16]; int nstream;
    NVNbufferRange vbuf[16];
    p_bind_buf ubo[6][16], ssbo[6][16];
    uint64_t tex[6][128], samp[6][128], img[6][32];
    uint64_t tex_gen[6];   // TOTK: a fresh value of g_tex_gen_seq whenever tex[stage] changes (TEX_CHANGED); saved / restored with S
    uint32_t st_vmask[2], st_wmask[2], st_ref[2];
    p_poly_offset po; float vp[16][4]; float dr[2]; int has_vp; int depth_clamp; int render_disabled; int raster_discard;
    float blend_color[4]; int64_t copy_stride;
} S;
/* TOTK: stage_sig compared 128 texture handles of the stage with its last copy on every draw (a 1 KiB memcmp, 0.13 ms a
   frame in a shrine). Every write to S.tex now gives that stage a fresh, never reused number, so equal numbers mean equal
   handles also after S is saved and restored. TOTK_TEX_GEN_CHECK=1 compares the handles as well and stops on a difference. */
static uint64_t g_tex_gen_seq;
#define TEX_CHANGED(st) (S.tex_gen[st] = ++g_tex_gen_seq)
static int tex_gen_check(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_TEX_GEN_CHECK"); v = e && atoi(e); } return v; }
// No render target set: no colour target and no depth / stencil (a pass of rasterization only, see rp_begin_ex)
static int rt_none(void) {
    if (!R.has_rt || R.rt.depth) return 0;
    for (int i = 0; i < R.rt.n && i < 8; i++) if (R.rt.color[i]) return 0;
    return 1;
}
// The size of such a pass: the extent of viewport 0, else of the scissor (1..16384)
static void noatt_dims(NSUInteger *w, NSUInteger *h) {
    double x1 = 0, y1 = 0;
    if (S.has_vp) { x1 = ceil(fmax(S.vp[0][0], S.vp[0][0] + S.vp[0][2])); y1 = ceil(fmax(S.vp[0][1], S.vp[0][1] + S.vp[0][3])); }
    if ((x1 < 1 || y1 < 1) && R.has_sc) { x1 = (double)R.sc.x + R.sc.w; y1 = (double)R.sc.y + R.sc.h; }
    *w = x1 < 1 ? 1 : x1 > 16384 ? 16384 : (NSUInteger)x1; *h = y1 < 1 ? 1 : y1 > 16384 ? 16384 : (NSUInteger)y1;
}
static void uld_miss(int j) {   // TOTK_ULD: a write to attachment g_sd[j] of the open pass, which was not loaded
    g_uld_miss++; g_uld_reopen = 1; if (g_uld_cur && g_sd[j].idx >= 0 && g_sd[j].idx < 8) { g_uld_cur->streak[g_sd[j].idx] = 0; if (g_uld_cur->hold[g_sd[j].idx] < 64) g_uld_cur->hold[g_sd[j].idx] += 8; }
}
static int uld_draw_writes(NvProg *pr) {   // 1 when this draw writes a colour attachment the open pass did not load (udc_note_draw's rule)
    if (!pr) return 0;
    uint32_t cm = pr->sh[1] ? pr->sh[1]->rf.color_mask : 0; int imgw = 0;
    for (int st = 0; st < 6 && !imgw; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue;
        for (int i = 0; i < sh->rf.nb; i++) if (sh->rf.b[i].kind == NVN_RB_IMG && sh->rf.b[i].rw) { imgw = 1; break; } }
    int hit = 0;
    for (int j = 0; j < g_nsd; j++) { if (!(g_uld_mask >> j & 1)) continue; int x = g_sd[j].idx;
        if (imgw || (x >= 0 && ((((S.chmask.mask >> (4 * x)) & 0xf)) || (cm >> x & 1)))) { uld_miss(j); hit = 1; } }
    return hit;
}
/* TOTK_UDC / TOTK_ULD: a helper clear quad writes colour attachment `index` (ds 0) or depth / stencil (ds 1) only; the
   other attachments stay as they are (marking them written would store a colour attachment the pass did not load). */
static void udc_mark_helper(int index, int ds) { g_udc_noted++;
    for (int i = 0; i < g_nsd; i++) { sd_att *t = &g_sd[i]; if (ds ? t->depth != 0 : (t->depth == 0 && t->idx == index)) { t->wrote = 1; if (!t->wwhy) t->wwhy = 6; } } }
__attribute__((unused)) static void udc_mark_all(void) { g_udc_noted++; for (int i = 0; i < g_nsd; i++) { g_sd[i].wrote = 1; if (!g_sd[i].wwhy) g_sd[i].wwhy = 6; } }   // TOTK_UDC: a helper draw into the open pass (clear quads)
static void udc_note_draw(NvProg *pr) {
    g_udc_noted++;   // TOTK_UDC: this draw's writes are accounted for below
    if (R.has_rt) for (int i = 0; i < R.rt.n && i < 8; i++) if (R.rt.color[i]) { zskip_del(R.rt.color[i]->serial); g_zskip_cand_ok[i] = 0; }   // Zero-source set: once really drawn it is no longer all zeros
    /* TOTK (after D2R Mobile 44a6770): the program's image bindings and fragment colour mask are worked out once per program
       and kept on it (two loops over every binding of every stage on every draw before). */
    if (pr && pr->udc_ok) for (int st = 0; st < 6; st++) if (pr->udc_sh[st] != (__bridge void *)pr->sh[st]) { pr->udc_ok = 0; break; }
    if (pr && !pr->udc_ok) {
        int img = 0, imgw = 0; uint32_t cm = 0;
        for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; pr->udc_sh[st] = (__bridge void *)sh; if (!sh) continue;
            if (st == 1) cm = sh->rf.color_mask;
            for (int i = 0; i < sh->rf.nb; i++) if (sh->rf.b[i].kind == NVN_RB_IMG) { img = 1; if (sh->rf.b[i].rw) imgw = 1; } }
        pr->udc_img = (uint8_t)img; pr->udc_imgw = (uint8_t)imgw; pr->udc_cmask = cm; pr->udc_ok = 1;
    }
    if (pr && pr->udc_img) zskip_clear();   // Image slots are writable: conservatively clear
    int image_write = pr ? pr->udc_imgw : 0;
    uint32_t shader_color_mask = pr ? pr->udc_cmask : 0;
    for (int i = 0; i < g_nsd; i++) {
        sd_att *t = &g_sd[i];
        if (image_write) { t->wrote = 1; t->wwhy = 1; }
        else if (t->depth == 0 && t->idx >= 0 && (((S.chmask.mask >> (4 * t->idx)) & 0xf) || (shader_color_mask >> t->idx & 1))) { t->wrote = 1; t->wwhy = (S.chmask.mask >> (4 * t->idx)) & 0xf ? 2 : 3; }
        else if (t->depth == 1 && S.ds.dw) { t->wrote = 1; t->wwhy = 4; }
        else if (t->depth == 2 && S.ds.st && (S.st_wmask[0] || S.st_wmask[1])
                && (S.ds.fail_f != NVN_STENCIL_OP_KEEP || S.ds.zfail_f != NVN_STENCIL_OP_KEEP || S.ds.zpass_f != NVN_STENCIL_OP_KEEP
                    || S.ds.fail_b != NVN_STENCIL_OP_KEEP || S.ds.zfail_b != NVN_STENCIL_OP_KEEP || S.ds.zpass_b != NVN_STENCIL_OP_KEEP)) { t->wrote = 1; t->wwhy = 5; }
        else continue;
        g_sd_wseq[i] = g_nvbar_seq;   // TOTK_SPLIT_BARRIER: written by this draw, after every barrier so far
    }
}
static void state_reset(void) {
    memset(&S, 0, sizeof S);
    (PSO_DIRTY(), g_dss_dirty = 1);
    for (int i = 0; i < 8; i++) S.blend[i] = (blend_st){i, NVN_BLEND_FUNC_ONE, NVN_BLEND_FUNC_ZERO, NVN_BLEND_FUNC_ONE, NVN_BLEND_FUNC_ZERO, NVN_BLEND_EQUATION_ADD, NVN_BLEND_EQUATION_ADD};
    S.color = (color_st){0, NVN_LOGIC_OP_COPY, NVN_ALPHA_FUNC_ALWAYS}; S.chmask.mask = 0xffffffffu;
    S.poly = (poly_st){NVN_FACE_NONE, NVN_FRONT_FACE_CCW, NVN_POLYGON_MODE_FILL, 0};
    S.ds = (ds_st){0, 1, NVN_DEPTH_FUNC_LESS, 0, NVN_STENCIL_FUNC_ALWAYS, NVN_STENCIL_FUNC_ALWAYS, 1, 1, 1, 1, 1, 1};
    S.st_vmask[0] = S.st_vmask[1] = S.st_wmask[0] = S.st_wmask[1] = 0xff; S.dr[1] = 1;
}

// TOTK: translator answers from the bound state (texture types per slot, image formats, vertex input and
// colour output component classes). Unbound slots are left out; the translator then uses its defaults.
static NSString *fmt_class(int f) {
    switch (f) {
        case 0x03: case 0x08: case 0x0B: case 0x0F: case 0x14: case 0x17: case 0x1B: case 0x20: case 0x23: case 0x27: case 0x2C: case 0x2F: return @"uint";
        case 0x04: case 0x09: case 0x0C: case 0x10: case 0x15: case 0x18: case 0x1C: case 0x21: case 0x24: case 0x28: case 0x2D: case 0x30: return @"sint";
        default: return @"float";
    }
}
static NSString *target_name(int t) {
    switch (t) { case 0: return @"1d"; case 2: return @"3d"; case 3: return @"1darray"; case 4: return @"2darray"; case 5: return @"2dms";
                 case 6: return @"2dmsarray"; case 8: return @"cube"; case 9: return @"cubearray"; case 10: return @"buffer"; default: return @"2d"; }
}
static NSString *image_format(int f) {
    switch (f) {
        case 0x01: return @"R8Unorm"; case 0x0D: return @"R8G8Unorm"; case 0x25: return @"R8G8B8A8Unorm"; case 0x27: return @"R8G8B8A8Uint";
        case 0x05: return @"R16Float"; case 0x11: return @"R16G16Float"; case 0x29: return @"R16G16B16A16Float"; case 0x08: return @"R16Uint"; case 0x2C: return @"R16G16B16A16Uint";
        case 0x0A: return @"R32Float"; case 0x16: return @"R32G32Float"; case 0x2E: return @"R32G32B32A32Float"; case 0x0B: return @"R32Uint"; case 0x0C: return @"R32Sint";
        case 0x17: return @"R32G32Uint"; case 0x2F: return @"R32G32B32A32Uint"; case 0x3D: return @"R10G10B10A2Unorm"; case 0x3F: return @"R11G11B10Float";
        default: return nil;
    }
}
static const treg_t *bound_tex(uint64_t h) { int tid = (int)(h & 0xfffff); return tid > 0 && tid < g_ntreg && g_treg[tid].ok ? &g_treg[tid] : NULL; }
static int bound_target(const treg_t *r) { return r->has_v && r->v.set_target ? r->v.target : r->t.d.target; }
static NSDictionary *rt_answers(int st) {
    NSMutableDictionary *tex = [NSMutableDictionary dictionary], *img = [NSMutableDictionary dictionary], *attr = [NSMutableDictionary dictionary], *fout = [NSMutableDictionary dictionary];
    registry_lock();   /* nested on this thread or wait for a different owner */
    for (int r = 0; r < 128; r++) if (S.tex[st][r]) { const treg_t *t = bound_tex(S.tex[st][r]); if (!t) continue;
        /* TOTK: a depth-format texture (NVN 0x32..0x36) sampled through a plain texture slot must be declared depth2d in MSL
           (Metal gives no data for a depth texture read as texture2d, and depth formats cannot be viewed as colour);
           the answer carries a _depth suffix so the translation is a separate variant and the MSL is rewritten. */
        int f = t->has_v && t->v.set_format ? t->v.format : t->t.d.format; NSString *name = target_name(bound_target(t));
        tex[@(r).stringValue] = f >= 0x32 && f <= 0x36 ? [name stringByAppendingString:@"_depth"] : name; }
    for (int r = 0; r < 32; r++) if (S.img[st][r]) { const treg_t *t = bound_tex(S.img[st][r]); if (!t) continue;
        int f = t->has_v && t->v.set_format ? t->v.format : t->t.d.format; NSString *fn = image_format(f);
        img[@(r).stringValue] = fn ? @{@"type": target_name(bound_target(t)), @"fmt": fn} : @{@"type": target_name(bound_target(t))}; }
    registry_unlock();
    if (st == 0) for (int i = 0; i < S.nattr && i < 16; i++) attr[@(i).stringValue] = fmt_class(S.attr[i].fmt);
    if (st == 1 && R.has_rt) for (int i = 0; i < R.rt.n && i < 8; i++) if (R.rt.color[i]) fout[@(i).stringValue] = fmt_class(R.rt.has_cview[i] && R.rt.cview[i].set_format ? R.rt.cview[i].format : R.rt.color[i]->d.format);
    return @{@"tex": tex, @"img": img, @"attr": attr, @"fout": fout};
}
// TOTK: value class of the bound state a translation depends on (fragment outputs per render target, vertex attributes).
static int cls_of(int f) { switch (f) {
    case 0x03: case 0x08: case 0x0B: case 0x0F: case 0x14: case 0x17: case 0x1B: case 0x20: case 0x23: case 0x27: case 0x2C: case 0x2F: return 1;
    case 0x04: case 0x09: case 0x0C: case 0x10: case 0x15: case 0x18: case 0x1C: case 0x21: case 0x24: case 0x28: case 0x2D: case 0x30: return 2;
    default: return 0; } }
static const treg_t *bound_tex(uint64_t h);
/* stage_sig (TOTK_SIG_INCR): take the registry lock; keep it and answer 1 when no registration happened since gen was read
   (texture / sampler registrations bump g_reg_gen while holding it), so the per-slot answers kept for gen still hold. */
static int g_sig_incr_locked;
static int sig_incr_locked(uint64_t gen) {
