        case 0x57: return MTLVertexFormatUChar2; case 0x58: return MTLVertexFormatChar2;
        case 0x59: return MTLVertexFormatUShort2; case 0x5A: return MTLVertexFormatShort2;
        case 0x5B: return MTLVertexFormatUInt2; case 0x5C: return MTLVertexFormatInt2;
        case 0x5D: return MTLVertexFormatUChar3; case 0x5E: return MTLVertexFormatChar3;
        case 0x5F: return MTLVertexFormatUShort3; case 0x60: return MTLVertexFormatShort3;
        case 0x61: return MTLVertexFormatUInt3; case 0x62: return MTLVertexFormatInt3;
        case 0x63: return MTLVertexFormatUChar4; case 0x64: return MTLVertexFormatChar4;
