/* Diagnostics must capture the immutable bytes actually bound to the GPU, not just the
   guest address which another game thread may already have recycled. The per-GPU-address
   suffix also keeps distinct inline updates of the same guest address within one pass. */
static const uint8_t *bound_uniform_bytes(uint64_t gpu, size_t size, id<MTLBuffer> original) {
    ubc_wait_all();   // TOTK_UB_COPY_THREAD: the shadow may still be filled by the worker
    uint64_t begin = original.gpuAddress, length = original.length;
    if (gpu >= begin && gpu - begin <= length && size <= length - (gpu - begin))
        return (const uint8_t *)original.contents + (gpu - begin);
    for (NvArena *a in g_sub_arenas) {
        if (gpu >= a->gpu && gpu - a->gpu <= a->used && size <= a->used - (gpu - a->gpu))
            return (const uint8_t *)a->buf.contents + (gpu - a->gpu);
    }
    return NULL; // e.g. the special UI motion matrix ring: do not label live bytes as bound bytes
}
static int arg_epoch_safe(NvShader *sh) {
    if (!sh->ab_epoch_ok) {
        sh->ab_epoch_ok = 1;
        for (int i = 0; i < sh->rf.nb; i++) {
            const nvn_rbind *b = &sh->rf.b[i];
            // Indirect pointers and writable bindings have replay-time side effects.
            if (b->rw || b->kind == NVN_RB_IMG || b->kind == NVN_RB_SBUFU) { sh->ab_epoch_ok = -1; break; }
        }
    }
    return sh->ab_epoch_ok > 0;
}
static arg_epoch_key arg_epoch_current(int stage) {
    return (arg_epoch_key){g_pass.serial, g_arena_epoch, g_args_epoch[stage], g_reg_gen,
        g_ser_gen, nvn_dirty_now(), g_usnap_drops, (uint64_t)stage | ((uint64_t)drvfill_on() << 8) | ((uint64_t)usnap_on() << 9)};
}
static int tex_slot_binding(const nvn_rbind *b) {
    return b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF ||
        b->kind == NVN_RB_SAMP || b->kind == NVN_RB_SAMPT;
}
static int tex_slots_diagnostics(void) {
    static int active = -1;
    if (active < 0) active = getenv("DM_NVN_TEXPNG_FS") != NULL || getenv("DM_NVN_FLASHHDR") != NULL;
    return active;
}
/* TOTK_CBUF_CACHE (default on; =0 off, =2 verify every hit against the full path), 2026-10-23. A uniform-buffer binding
   resolves to the same GPU address every time its range is bound until something it depends on changes: the pool table
   (g_pool_gen), the renamed inline updates (their log g_upd_seq / g_nupd, and the private-copy list starting over), the
   submission's uniform snapshot (the submission, its entry count, the copies dropped by GPU writes). Material draws
   rebind per-object blocks on nearly every draw, so encode_args rebuilt the whole argument block and resolved every
   uniform range again (pool lookup, update-log query, snapshot lookup: encode_args was 21% of the translate thread in the
   Korok Forest profile, about half of it in those three). The last result per (address, size) is kept with the context
   it was computed in (read before the lookup, so a change during it only makes the entry miss later) and answers a
   binding whose context is unchanged. Not used for the UI matrix patch (vertex cb0 with g_ui_moff), the pass dump,
   DM_RES_CHECK or DM_GFXUSE recording (they need the side effects of the full path). */
