}

static void fz_probe_cov2(const p_set_rt *r2, const uint8_t *first, const int8_t *p2map, const uint8_t *clr, int n1, int n) {
    static typeof(S) Ssave; memcpy(&Ssave, &S, sizeof S); typeof(R) Rsave = R;
    const p_draw *fdw = g_fd_dw; const p_draw_idx *fdi = g_fd_di; int fdwhy = g_fd_why;
    int pso_dirty = g_pso_dirty, dss_dirty = g_dss_dirty;
    op_hdr fh; memcpy(&fh, first, sizeof fh);
    g_fd_dw = fh.op == OP_DRAW ? (const p_draw *)(first + 8) : NULL;
    g_fd_di = fh.op == OP_DRAW_IDX ? (const p_draw_idx *)(first + 8) : NULL;
    R.rt = *r2; R.has_rt = 1;
    fz_cursor cur = {.p = g_exec_next};
    for (;;) {
        const uint8_t *q; op_hdr hq; const void *aq;
        if (!fz_next(&cur, &q, &hq, &aq)) break;
        if (q == first) break;
        if (hq.op == OP_DRAW || hq.op == OP_DRAW_IDX || hq.op == OP_SET_RT || hq.op == OP_CLEAR_COLOR || hq.op == OP_CLEAR_DS) continue;
        state_op(hq.op, aq);
    }
    for (int j = n1; j < n && j < 8; j++) {
        int k = -1;
        for (int q = 0; q < 8; q++) if (p2map[q] == j) { k = q; break; }
        if (k < 0 || clr[k] || !r2->color[k]) continue;
        uint64_t ser; int level, slice;
        rt_sub(r2, k, &ser, &level, &slice);
        (void)ser; (void)slice;
        g_fz.cov2[j] = (uint8_t)first_draw_covers(k, tex_mtl(r2->color[k]), (NSUInteger)level);
    }
    memcpy(&S, &Ssave, sizeof S); args_dirty_all(); R = Rsave;
    g_fd_dw = fdw; g_fd_di = fdi; g_fd_why = fdwhy;
    g_pso_dirty = pso_dirty; g_pso_state_gen++; g_dss_dirty = dss_dirty;
}

static int fz_load_covers(int i, id<MTLTexture> t, NSUInteger level) {
    if (g_fz.active && g_fz.phase == 1 && i >= g_fz.n1) return g_fz.cov2[i];
    return first_draw_covers(i, t, level);
}

// Probe wrap-up: for every attachment changed to clear to the sentinel color, read back that level / layer, compare pixel by pixel with a same-format 1x1 sentinel pixel, and count what remains (> 0 means the coverage proof is wrong, report a failure)
static void lp_finish(void) {
    id<MTLCommandBuffer> dcb = q_cb();
    NSArray *ps = g_lp; g_lp = nil;
    for (NSArray *e in ps) {
        id<MTLTexture> t = e[0]; NSUInteger lv = [e[1] unsignedIntegerValue], sl = [e[2] unsignedIntegerValue];
        NSUInteger W = MAX(t.width >> lv, 1), H = MAX(t.height >> lv, 1), bpp = (NSUInteger)(att_bytes(t, lv) / (W * H));
        MTLTextureDescriptor *rd = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:t.pixelFormat width:1 height:1 mipmapped:NO];
        rd.usage = MTLTextureUsageRenderTarget; rd.storageMode = MTLStorageModePrivate;
        id<MTLTexture> ref = [g_dev newTextureWithDescriptor:rd];
        MTLRenderPassDescriptor *pd = [MTLRenderPassDescriptor renderPassDescriptor];
        pd.colorAttachments[0].texture = ref; pd.colorAttachments[0].loadAction = MTLLoadActionClear; pd.colorAttachments[0].storeAction = MTLStoreActionStore;
        pd.colorAttachments[0].clearColor = [e[6] intValue] == 3 ? MTLClearColorMake(NAN, NAN, NAN, NAN) : [e[6] intValue] == 2 ? MTLClearColorMake(0.777, 0.222, 0.555, 0.888) : MTLClearColorMake(0.123, 0.456, 0.789, 0.321);
        [[dcb renderCommandEncoderWithDescriptor:pd] endEncoding];
        id<MTLBuffer> bt = [g_dev newBufferWithLength:W * H * bpp options:MTLResourceStorageModeShared], br = [g_dev newBufferWithLength:bpp options:MTLResourceStorageModeShared];
        id<MTLBlitCommandEncoder> b = [dcb blitCommandEncoder];
        [b copyFromTexture:t sourceSlice:sl sourceLevel:lv sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(W, H, 1) toBuffer:bt destinationOffset:0 destinationBytesPerRow:W * bpp destinationBytesPerImage:W * H * bpp];
        [b copyFromTexture:ref sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(1, 1, 1) toBuffer:br destinationOffset:0 destinationBytesPerRow:bpp destinationBytesPerImage:bpp];
    enc_b_end(b);
        unsigned long long pass = [e[3] unsignedLongLongValue], ser = [e[5] unsignedLongLongValue]; int idx = [e[4] intValue];
        [dcb addCompletedHandler:^(id<MTLCommandBuffer> c) { (void)c;
            const uint8_t *p = bt.contents, *r = br.contents; uint64_t left = 0; char at[96] = ""; size_t ao = 0;
            for (NSUInteger k = 0; k < W * H; k++) if (!memcmp(p + k * bpp, r, bpp)) { if (left++ < 4) ao += snprintf(at + ao, sizeof at - ao, " (%lu,%lu)", (unsigned long)(k % W), (unsigned long)(k / W)); }
            if (left) MLOG("[red] Skippable-load probe: pass %llu c%d ser=%llu lv%lu sl%lu %lux%lu %llu sentinel pixels left, first positions%s", pass, idx, ser, (unsigned long)lv, (unsigned long)sl, (unsigned long)W, (unsigned long)H, (unsigned long long)left, at);
            else MLOG("Skippable-load probe: pass %llu c%d ser=%llu lv%lu sl%lu %lux%lu fully covered (0 sentinels left)", pass, idx, ser, (unsigned long)lv, (unsigned long)sl, (unsigned long)W, (unsigned long)H);
        }];
    }
    cb_commit(dcb);
}
/* TOTK (2026-10-17): the replay state that outlives a submit and holds texture copies of recordings (hle_nvn.c pin_sweep):
   the current render targets, which the next submit's first SetRenderTargets compares by serial (rt_same). Everything
   else holding them (cube groups, deferred and fused passes, layer merges) ends with its pass or submit. */
void mtl_pin_refs(void (*mark)(const void *)) {
    if (!R.has_rt) return;
    for (int i = 0; i < R.rt.n && i < 8; i++) mark(R.rt.color[i]);
    mark(R.rt.depth);
}
void mtl_probe_pin_rt(const tex_t *t) { memset(&R.rt, 0, sizeof R.rt); R.has_rt = t != NULL; R.rt.n = t ? 1 : 0; R.rt.color[0] = t; }
static int rt_same(const p_set_rt *a, const p_set_rt *b) {   // Same set of targets: compare by texture serial and view (not by object pointer: the game may copy texture objects by value)
    if (a->n != b->n || !a->depth != !b->depth || (a->depth && a->depth->serial != b->depth->serial) || a->has_dview != b->has_dview) return 0;
    if (a->has_dview && memcmp(&a->dview, &b->dview, sizeof a->dview)) return 0;
    for (int k = 0; k < a->n && k < 8; k++) {
        if (!a->color[k] != !b->color[k] || (a->color[k] && a->color[k]->serial != b->color[k]->serial) || a->has_cview[k] != b->has_cview[k]) return 0;
        if (a->has_cview[k] && memcmp(&a->cview[k], &b->cview[k], sizeof a->cview[k])) return 0;
    }
    return 1;
}
// Experimental RT range candidate: only ignore positive nlevels differences not used by the actual render attachments; other fields stay word-for-word identical.
#define NVN_RT_RANGE_IMPL 1
static int rt_range_shape(const p_set_rt *a, const p_set_rt *b) {
    if (a->n != 1 || b->n != 1 || !a->color[0] || !b->color[0] || !a->has_cview[0] || !b->has_cview[0] ||
        !a->depth != !b->depth || a->has_dview != b->has_dview ||
        (a->has_dview && memcmp(&a->dview,&b->dview,sizeof a->dview))) return 0;
    const tex_t *x=a->color[0], *y=b->color[0];
    if (!x->serial || x->serial != y->serial || x->d.target != NVN_TEXTURE_TARGET_2D || y->d.target != NVN_TEXTURE_TARGET_2D ||
        x->d.samples > 1 || y->d.samples > 1 || tex_mirrored(x) || tex_mirrored(y) ||
        memcmp(&x->d,&y->d,sizeof x->d) || x->mem != y->mem || x->pool != y->pool || x->off != y->off) return 0;
    const view_t *v=&a->cview[0], *w=&b->cview[0]; int levels=x->d.levels;
    if (!v->set_levels || !w->set_levels || v->base_level < 0 || v->base_level >= levels ||
        v->nlevels <= 0 || v->nlevels > levels-v->base_level || w->nlevels <= 0 || w->nlevels > levels-v->base_level ||
        (v->set_layers && (v->min_layer || v->nlayers != 1)) || (v->set_format && v->format != x->d.format) ||
        (v->set_target && v->target != NVN_TEXTURE_TARGET_2D)) return 0;
    view_t cv=*w; cv.nlevels=v->nlevels;
    if (memcmp(v,&cv,sizeof cv)) return 0;
    if (a->depth) { const tex_t *d=a->depth,*e=b->depth;
        if (!d->serial || d->serial != e->serial || d->d.target != NVN_TEXTURE_TARGET_2D || e->d.target != NVN_TEXTURE_TARGET_2D ||
            d->d.samples > 1 || e->d.samples > 1 || tex_mirrored(d) || tex_mirrored(e) ||
            memcmp(&d->d,&e->d,sizeof d->d) || d->mem != e->mem || d->pool != e->pool || d->off != e->off) return 0;
        int dl=a->has_dview && a->dview.set_levels ? a->dview.base_level : 0;
        if (dl < 0 || dl >= d->d.levels || mip_extent(d->d.width,dl) < mip_extent(x->d.width,v->base_level) ||
            mip_extent(d->d.height,dl) < mip_extent(x->d.height,v->base_level)) return 0; }

    return v->nlevels != w->nlevels;
}
#define NVN_RT_RANGE_DEPTH_IMPL 1
static void rt_range_note_depth(void) { if (rt_range_on() && S.ds.dw) g_pass.range_depth_nonro=1; }
static int rt_range_same(const p_set_rt *a, const p_set_rt *b) {
    if (!rt_range_on() || !g_enc || g_fz.active || g_pass.range_external || g_pass.range_depth_nonro || !S.ds.dt || S.ds.dw || S.ds.st || g_enc_mode != 4 || !g_pass.hd || g_pass.hs ||
        (g_vis_on && !g_enc_has_vis) || g_pass.reg_gen != g_reg_gen || g_pass.ser_gen != g_ser_gen || g_pass.range_dirty != nvn_dirty_now() || !rt_range_shape(a,b) || !b->depth) return 0;
    id<MTLTexture> color=tex_mtl(b->color[0]), depth=tex_mtl(b->depth);
    int lv=b->cview[0].base_level;
    return mip_extent(color.width,lv) == g_pass.tw && mip_extent(color.height,lv) == g_pass.th &&
        color == g_pass.range_color && depth == g_pass.range_depth && color.textureType == MTLTextureType2D &&
        depth.textureType == MTLTextureType2D && color.sampleCount == 1 && depth.sampleCount == 1 &&
        g_pass.reg_gen == g_reg_gen && g_pass.ser_gen == g_ser_gen && g_pass.range_dirty == nvn_dirty_now();
}
static int draw_samples_rt(NvProg *pr) {   // Sampled attachments keep the original conservative ser-level guard, not split by level/layer
    uint64_t rs[9]; int nr = 0;
    for (int k = 0; k < R.rt.n && k < 8; k++) if (R.rt.color[k]) rs[nr++] = R.rt.color[k]->serial;
    if (R.rt.depth) rs[nr++] = R.rt.depth->serial;
    if (!pr) return 1;
    for (int st = 0; st < 5; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
            if (b->kind == NVN_RB_IMG) h = b->reg < 32 && sh->stage < 6 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = b->reg < 128 && sh->stage < 6 ? S.tex[sh->stage][b->reg] : 0; else continue;
            int tid = (int)(h & 0xfffff); if (!tid) continue;
            registry_lock(); uint64_t ser = tid < g_ntreg && g_treg[tid].ok ? g_treg[tid].t.serial : 0; registry_unlock();
            for (int j = 0; j < nr; j++) if (ser && ser == rs[j]) return 1; } }
    return 0;
}
// The whole render pass's need for depth / stencil (bits: 1 depth 2 stencil; 3 = both needed or cannot be proven). Starting from the draw that opens the render pass, scan in real replay order to the end of the render pass:
// the attached clears and this draw's state are counted first; later draws accumulate by their depth-stencil state; anything unprovable such as a mid-pass clear or nesting too deep is treated as both needed
/* TOTK: a fragment function with a [[depth]] output needs the pass to keep its depth attachment (Metal refuses the pipeline otherwise),
   even when depth test and write are off. */
static int prog_ps_writes_depth(const prog_t *pg) { if (!pg) return 0; __unsafe_unretained NvProg *pr = prog_get(pg); return pr && pr->sh[1] && pr->sh[1]->writes_depth; }
static int pass_ds_need(void) {
    int need = (R.clear_d || S.ds.dt || S.ds.dw || prog_ps_writes_depth(S.prog) ? 1 : 0) | (R.clear_s || S.ds.st ? 2 : 0);
    if (!R.rt.depth || need == 3 || !g_exec_next || g_ret_n > 16) {
        PD("S %llu no-lookahead depth=%d clear_d=%d clear_s=%d dt=%d dw=%d st=%d next=%d ret=%d", g_stat_pass + 1, R.rt.depth != NULL, R.clear_d, R.clear_s, (int)S.ds.dt, (int)S.ds.dw, (int)S.ds.st, g_exec_next != NULL, g_ret_n);
        return 3;
    }
    ds_st ds = S.ds; g_ds_why = -1; g_ds_scanned = 0; g_ds_need = need;
    int r = ds_scan(g_exec_next, &ds, 0);
    for (int k = g_ret_n - 1; r == DS_RET && k >= 0; k--) r = ds_scan(g_ret[k], &ds, 0);
    for (int k = 0; r == DS_RET && k < g_nrest; k++) r = ds_scan((const uint8_t *)g_rest[k], &ds, 0);
    int out = r == DS_USED ? 3 : g_ds_need;
    PD("S %llu lookahead result=%d need=%d (1 depth 2 stencil) why=%d scanned %d returns %d handles left %d", g_stat_pass + 1, r, out, g_ds_why, g_ds_scanned, g_ret_n, g_nrest);
    return out;
}
// Pure-clear render pass hoisting: when a render pass is opened, scan forward, and if the shape is "several draws of this render pass -> several groups (SetRenderTargets + only clears) -> back to the same targets as this render pass",
// then hoist those groups of clears to execute before this render pass and skip them at their original positions, and on returning to the same targets the same-target continuation picks up -- this render pass's attachments are no longer stored whole and loaded again for the clears sandwiched in between
// (character select page: grunge and particles both draw 28 / 27 level 0 + depth, with only levels 1 and 2 cleared in between).
// Equivalence conditions (hoist only if all hold, otherwise leave as-is): the scan range has only draws, state and these clears, no copies / dispatches / texture clears / sub-lists; the cleared subresources (texture + level + layer)
// are disjoint from this render pass's attachments; the cleared textures are neither on any current texture / image slot nor bound within the scan range (conservative: regardless of whether the program samples them); the scissor at the time of the clear covers the whole block (same requirement as executing at the original position)
static uint64_t h_ser(uint64_t h) { int tid = (int)(h & 0xfffff); return tid ? atomic_load_explicit(&g_tser[tid], memory_order_relaxed) : 0; }
/* TOTK: a draw that samples an attachment of its own pass. The Switch renders straight to memory, so the sample sees what
   the pass drew before it; an Apple GPU keeps the pass's pixels in tile memory until the pass ends, and the sample sees
   what memory held when the pass began. TOTK's ground decals read the G-buffer albedo and normals they blend into: they read
   the last frame's G-buffer instead, which turns into rings smeared around Link while the camera moves (still, the two
   frames agree). att_unstored_read is true when such a draw would miss pixels still in tile memory; ending the pass there
   stores them. A run of sampling draws shares one pass: the game records no barrier between its decals, so they are not
   ordered against each other on the Switch either, and a split per decal would store and reload the G-buffer 56 times. */
#define ATT_READS_MAX 8
static int has_ser(const uint64_t *s, int n, uint64_t v) { for (int i = 0; i < n; i++) if (s[i] == v) return 1; return 0; }
#define ATT_SER_BIT(ser) (UINT64_C(1) << (((uint64_t)(ser) * UINT64_C(0x9E3779B97F4A7C15)) >> 58))
/* The serials of the textures the draw samples that are attachments: of the current targets or of the open encoder (which
   can hold more, e.g. a merged pass). By serial, not slot: the encoder's attachment order need not be the targets' order. */
/* The sampled texture / image slots of the program's stages, taken from the reflection once per sh[] (ar_*): the draw path
   then reads only those slots instead of walking every binding of every stage. */
static void ar_learn(NvProg *pr) {
    unsigned n = 0;
    for (int st = 0; st < 5 && n < 255; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh->stage >= 6) continue;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i];
            int img = b->kind == NVN_RB_IMG; if (!img && b->kind != NVN_RB_TEX) continue;
            if (b->reg >= (img ? 32 : 128)) continue;
            if (n == 32) { n = 255; break; }
            pr->ar_st[n] = (uint8_t)sh->stage; pr->ar_reg[n] = (uint8_t)b->reg; pr->ar_img[n] = (uint8_t)img; n++; } }
    pr->ar_n = (uint8_t)n;
    for (int st = 0; st < 6; st++) pr->ar_sh[st] = (__bridge void *)pr->sh[st];
}
/* TOTK_BARRIER_NARROW=1: the wait for earlier vertex and fragment work, before the first draw of a narrow-started pass that
   needs it (see bar_narrow). Unknown stages or bindings count as needing it. */
static void bar_learn(NvProg *pr) {
    pr->bar_vs = pr->bar_wr = 0;
    for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; pr->bar_sh[st] = (__bridge void *)sh; if (!sh) continue;
        int vertex_side = sh->stage != 1;   // 0 vertex, 2-4 geometry / tessellation; 1 fragment
        for (int i = 0; i < sh->rf.nb; i++) { int k = sh->rf.b[i].kind;
            int reads = k == NVN_RB_TEX || k == NVN_RB_IMG || k == NVN_RB_TBUF || k == NVN_RB_SBUFP || k == NVN_RB_SBUFU || k == NVN_RB_SAMPT;
            int writes = k == NVN_RB_IMG || ((k == NVN_RB_SBUFP || k == NVN_RB_SBUFU) && sh->rf.b[i].rw);   // rw: read_write / write / device access
            if (vertex_side && reads) pr->bar_vs = 1;
            if (writes) pr->bar_wr = 1; } }
}
static void bar_draw(id<MTL4RenderCommandEncoder> en, NvProg *pr) {
    if (bar_narrow() != 1) return;
    if (!pr) { if (!g_bar_waited) goto wait; return; }
    { int same = 1; for (int st = 0; st < 6; st++) if (pr->bar_sh[st] != (__bridge void *)pr->sh[st]) { same = 0; break; }
      if (!same) bar_learn(pr); }
    if (pr->bar_wr) g_bar_cur = 1;
    if (g_bar_waited || !(pr->bar_vs || g_bar_prior)) return;
wait:
    g_bar_waited = 1; g_bar_prior = 0; g_bar_waits++;
    if (rs_using(en)) rs_put((nvn_encode_packet){.op = RS_VERTEX_WAIT, .u = {(uint64_t)bar_vis()}}, 0);
    else [en barrierAfterQueueStages:MTLStageVertex | MTLStageFragment beforeStages:MTLStageVertex visibilityOptions:bar_vis()];
    if (g_bar_waits == 1 || g_bar_waits % 20000 == 0) MLOG("[barrier] narrow passes: %llu of %llu render passes waited for earlier work before a vertex-side read", (unsigned long long)g_bar_waits, (unsigned long long)g_bar_passes);
}
static int draw_att_reads(NvProg *pr, uint64_t out[ATT_READS_MAX]) {
    uint64_t cand[18]; int nc = 0, n = 0;
    if (R.has_rt) { for (int k = 0; k < R.rt.n && k < 8; k++) if (R.rt.color[k]) cand[nc++] = R.rt.color[k]->serial;
                    if (R.rt.depth) cand[nc++] = R.rt.depth->serial; }
    if (g_enc) for (int i = 0; i < g_nsd; i++) cand[nc++] = g_sd[i].ser;
    if (!pr || !nc) return 0;
    /* TOTK: a one-word filter of the candidate serials in front of the list search (has_ser over up to 18 candidates for
       every sampled slot was ~2.5% of the replay; nearly every sampled texture is no attachment). A clear bit means the
       serial is not a candidate; a set bit runs the search. */
    uint64_t cbits = 0; for (int i = 0; i < nc; i++) cbits |= ATT_SER_BIT(cand[i]);
    int same = 1; for (int st = 0; st < 6; st++) if (pr->ar_sh[st] != (__bridge void *)pr->sh[st]) { same = 0; break; }
    if (!same) ar_learn(pr);
    if (pr->ar_n != 255) {
        for (unsigned i = 0; i < pr->ar_n; i++) {
            uint64_t h = pr->ar_img[i] ? S.img[pr->ar_st[i]][pr->ar_reg[i]] : S.tex[pr->ar_st[i]][pr->ar_reg[i]];
            uint64_t ser = h ? h_ser(h) : 0;
            if (ser && (cbits & ATT_SER_BIT(ser)) && has_ser(cand, nc, ser) && !has_ser(out, n, ser) && n < ATT_READS_MAX) out[n++] = ser; }
        return n;
    }
    for (int st = 0; st < 5; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh->stage >= 6) continue;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
            if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX) h = b->reg < 128 ? S.tex[sh->stage][b->reg] : 0; else continue;
            uint64_t ser = h ? h_ser(h) : 0;
            if (ser && has_ser(cand, nc, ser) && !has_ser(out, n, ser) && n < ATT_READS_MAX) out[n++] = ser; } }
    return n;
}
/* TOTK_ATT_STORE=0 turns the store-before-sample off (A/B; the decals ghost again) */
static int att_store_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_ATT_STORE"); on = !(e && !strcmp(e, "0")); } return on; }
static int att_unstored_read(const uint64_t *rs, int n) {
    if (!n) return 0;
    if (!g_enc) {   // no pass open: only a clear still pending lands after the sample
        for (int k = 0; k < R.rt.n && k < 8; k++) if (R.clear_c[k] && R.rt.color[k] && has_ser(rs, n, R.rt.color[k]->serial)) return 1;
        return (R.clear_d || R.clear_s) && R.rt.depth && has_ser(rs, n, R.rt.depth->serial);
    }
    for (int i = 0; i < g_nsd; i++)   // not loaded: cleared, or covered by its first draw
        if (has_ser(rs, n, g_sd[i].ser) && (!g_sd[i].load || (g_sd_plain >> i & 1))) return 1;
    return 0;
}
/* TOTK_SPLIT_BARRIER (default 0; idea and measurements from sunsssyc/Ryujinx_Optime e5d8c07 / 1417564): on the Switch a draw
   that samples a render target of its own pass without a Barrier() since the write is served stale data, and the game issues
   a real barrier (TextureBarrier / Barrier with INVALIDATE_TEXTURE) where it needs fresh pixels. So a samples-drawn-att split
   is only needed when a barrier came between the attachment's last write and this read. =1 lets such a draw into the open
   pass when every attachment it reads that is still only in tile memory: was loaded at pass open (the stale read then sees
   the pass's starting contents), got no barrier since its last write, and is RGBA8 / BGRA8 (sRGB too). =2 also takes
   attachments cleared at pass open (the stale read sees the previous contents of memory, not the clear). Ryujinx_Optime's
   limits: RG11B10Float showed banding along the tile grid on water (a partial render flushes some tiles mid-pass), RGB10A2
   excluded with it, R32Float (Ultrahand's depth / picking chain) broke grabbing; depth is never taken. Metal: the attachment
   stays bound as a sampled texture of the same encoder, exactly as Ryujinx_Optime does; there is no intra-pass barrier
   that makes tile contents visible to texture reads on Apple GPUs (memoryBarrierWithScope:RenderTargets is not supported
   there), so the read sees memory: undefined by the Metal spec, the pass-start contents in practice. Not while a deferred /
   cube-group / fused / layered / ranged pass is replayed (their draws are reordered against the barriers). */
enum { SB_BAR = 1, SB_FMT = 2, SB_DEPTH = 4, SB_CLEARED = 8, SB_KIND = 16 };
static int split_barrier(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_SPLIT_BARRIER"); v = e ? atoi(e) : 0;
    if (v) MLOG("[experiment] TOTK_SPLIT_BARRIER=%d: a draw sampling an RGBA8 / BGRA8 attachment its pass drew stays in the pass unless the game issued a barrier since the write%s", v, v >= 2 ? " (cleared attachments too)" : ""); } return v; }
static const char *sb_fmt_name(MTLPixelFormat pf) {
    switch (pf) { case MTLPixelFormatRGBA8Unorm: return "RGBA8Unorm"; case MTLPixelFormatRGBA8Unorm_sRGB: return "RGBA8sRGB"; case MTLPixelFormatBGRA8Unorm: return "BGRA8Unorm";
        case MTLPixelFormatBGRA8Unorm_sRGB: return "BGRA8sRGB"; case MTLPixelFormatR32Float: return "R32Float"; case MTLPixelFormatRGB10A2Unorm: return "RGB10A2Unorm";
        case MTLPixelFormatRG11B10Float: return "RG11B10Float"; case MTLPixelFormatRGBA16Float: return "RGBA16Float"; case MTLPixelFormatRG16Float: return "RG16Float";
        case MTLPixelFormatR16Float: return "R16Float"; case MTLPixelFormatR8Unorm: return "R8Unorm"; case MTLPixelFormatRG8Unorm: return "RG8Unorm"; default: return NULL; } }
/* Why the attachments rs (the ones att_unstored_read stores for) cannot be read stale: SB_* bits, 0 = all can. */
static unsigned sb_classify(const uint64_t *rs, int n, char *desc, size_t dn) {
    unsigned why = 0; int o = 0; if (desc && dn) desc[0] = 0;
    if (!g_enc) return SB_KIND | SB_CLEARED;   // a pending clear, no pass open
    if (g_defer_replaying || g_cg.replaying || g_fz.active || g_lay.active || g_rt_range_active) why |= SB_KIND;
    for (int i = 0; i < g_nsd; i++) { const sd_att *t = &g_sd[i];
        if (!has_ser(rs, n, t->ser) || !(!t->load || (g_sd_plain >> i & 1))) continue;
        int bar = g_sd_wseq[i] != g_nvbar_seq; const char *fn = "depth";
        if (bar) why |= SB_BAR;
        if (t->depth) why |= SB_DEPTH;
        else {
            if (!t->load) why |= SB_CLEARED;
            int j = -1; for (int m = 0; m < R.rt.n && m < 8; m++) if (R.rt.color[m] && R.rt.color[m]->serial == t->ser) { j = m; break; }
            id<MTLTexture> tx = j >= 0 ? tex_mtl(R.rt.color[j]) : nil; MTLPixelFormat pf = tx ? tx.pixelFormat : MTLPixelFormatInvalid;
            fn = sb_fmt_name(pf); if (!fn) fn = "other";
            if (pf != MTLPixelFormatRGBA8Unorm && pf != MTLPixelFormatRGBA8Unorm_sRGB && pf != MTLPixelFormatBGRA8Unorm && pf != MTLPixelFormatBGRA8Unorm_sRGB) why |= SB_FMT; }
        if (desc && o < (int)dn - 48) o += snprintf(desc + o, dn - o, "%s%s:%s:b%d", o ? ";" : "", fn, t->load ? "load" : "clear", bar); }
    return why;
}
/* Counts and logs a samples-drawn-att split point; returns 1 when TOTK_SPLIT_BARRIER lets the draw stay in the pass. Classes
   (g_sb_n): 0 skippable, 1 barriered, 2 depth, 3 other format, 4 cleared 8-bit only, 5 pass kind / no pass. */
static int sb_note(NvProg *pr, const uint64_t *rs, int n) {
    char d[160]; unsigned why = sb_classify(rs, n, d, sizeof d); int mode = split_barrier();
    int skip = mode && !(why & ~(mode >= 2 ? (unsigned)SB_CLEARED : 0u));
    int cls = !why ? 0 : why & SB_KIND ? 5 : why & SB_BAR ? 1 : why & SB_DEPTH ? 2 : why & SB_FMT ? 3 : 4;
    g_sb_n[cls]++; if (skip) g_sb_skip++;
    static int nlog; if (nlog < 24 && getenv("TOTK_DEBUG_LOG")) { nlog++;
        MLOG("[split-barrier] F%llu pass %llu fs %s reads [%s] class %d%s (last barrier bits %#x, %llu barriers so far)", (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass,
             pr && pr->sh[1] ? pr->sh[1]->key : "-", d, cls, skip ? " skipped" : "", g_nvbar_bits, (unsigned long long)g_nvbar_seq); }
    PD("M %llu split-barrier reads [%s] class %d%s", g_stat_pass, d, cls, skip ? " skipped: stays in the pass" : "");
    return skip;
}
static void sb_log_frame(void) {
    uint64_t f = atomic_load(&g_cur_frame); if (f < g_sb_frame0 + 600) return;
    double nf = (double)(f - g_sb_frame0);
    MLOG("[totk] [split-barrier] frames %llu-%llu per frame: %.1f NVN barriers (bits seen %#x); samples-drawn-att points %.1f: unbarriered RGBA8/BGRA8 loaded %.1f, barriered %.1f, depth %.1f, other format %.1f, cleared 8-bit %.1f, pass kind %.1f; skipped %.1f (TOTK_SPLIT_BARRIER=%d)",
         (unsigned long long)g_sb_frame0, (unsigned long long)f, g_sb_bar_n / nf, g_nvbar_frame_bits,
         (g_sb_n[0] + g_sb_n[1] + g_sb_n[2] + g_sb_n[3] + g_sb_n[4] + g_sb_n[5]) / nf, g_sb_n[0] / nf, g_sb_n[1] / nf, g_sb_n[2] / nf, g_sb_n[3] / nf, g_sb_n[4] / nf, g_sb_n[5] / nf, g_sb_skip / nf, split_barrier());
    g_sb_frame0 = f; memset(g_sb_n, 0, sizeof g_sb_n); g_sb_skip = g_sb_bar_n = 0; g_nvbar_frame_bits = 0;
}
/* TOTK_ATT_FB=1 (alias TOTK_FB_FETCH=1; default off): a draw whose fragment stage samples colour attachments of its own pass
   reads them from the tile ([[color(n)]], nvn_fbread.h) wherever the sampled texel is the fragment's own pixel, instead of
   the pass being stored and reopened first. Ported from upstream PR #155 (feeeei), extended to continued passes.
   TOTK_ATT_FB_WRITTEN=1 also reads slots the draw itself writes (PR #155's behaviour, which fixes the overlapping-decal
   squares); by default such a slot keeps the store, because a tile read there also sees the same draw's earlier fragments. */
static int att_fb_on(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("TOTK_ATT_FB"), *f = getenv("TOTK_FB_FETCH"); on = (e && !strcmp(e, "1")) || (f && !strcmp(f, "1"));
        if (on) MLOG("TOTK_ATT_FB=1: draws read the attachments of their own pass from the tile at their own pixel (fb-fetch)"); }
    return on;
}
static int att_fb_written_ok(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_ATT_FB_WRITTEN"); on = e && !strcmp(e, "1"); } return on; }
static const char *g_fb_why;   // why att_fb_take left a draw's attachment reads alone (pass-end diagnostics), NULL = took them all
/* Whether colour slot j of the draw is written: declared by the fragment function and not masked off. */
static int draw_writes_slot(NvShader *fs, int j) { return j >= 0 && j < 8 && (fs_color_outs(fs) >> j & 1) && ((S.chmask.mask >> (4 * j)) & 0xf); }
/* The colour attachments among rs (the attachments the draw samples, draw_att_reads) that its fragment stage can read from the
   tile instead: each is sampled only by plain sample calls of the fragment stage, through a view that is the attachment itself
   (level 0, layer 0, its format), at the same colour index in the open encoder, and (unless TOTK_ATT_FB_WRITTEN=1) is not
   written by the draw. They are removed from rs, so they no longer store the pass first; returns the fragment function for
   the draw, or nil (rs unchanged, g_fb_why says why). *all: every attachment the draw binds anywhere was taken. */
static id<MTLFunction> att_fb_take(NvProg *pr, uint64_t *rs, int *n, int *all) {
    NvShader *fs = pr ? pr->sh[1] : nil; *all = 0; g_fb_why = NULL;
#define FB_NO(w) do { g_fb_why = (w); g_fb_refused++; return nil; } while (0)
    if (!att_fb_on()) { g_fb_why = "off"; return nil; }
    if (!*n) return nil;
    if (!fs) FB_NO("no-fs");
    /* (upstream, 2026-10-25) A fragment shader that writes depth can read the tile too when the draw's pass has its depth
       plane: pso_desc takes the variant (whole source, depth output kept) instead of fs_fn_without_depth only when k->dfmt is
       0. The decals that write depth (b626c0ae at Kakariko, 65 draws a frame) were stored and reloaded around: two G-buffer
       stores and loads (~190 MB) a frame. */
    if (fs->writes_depth && !(R.rt.depth && (!g_enc || g_pass.hd))) FB_NO("depth-out");
    if (!R.has_rt || g_pso_lmap || g_mfx.role || g_fz.active || g_lay.active || g_rt_range_active) FB_NO("pass-kind");
    { float bc[8][4]; int ba[8], bn; unsigned bx[8]; samp_par bp[8]; if (border_key(fs, 1, bc, ba, bx, bp, &bn)) FB_NO("border"); }   // one specialised fragment function per draw (a border variant)
    int aid[8], att[8], k = 0, nt = 0; uint64_t took[8];
    for (int i = 0; i < fs->rf.nb; i++) { const nvn_rbind *b = &fs->rf.b[i]; uint64_t h;
        if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[1][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = b->reg < 128 ? S.tex[1][b->reg] : 0; else continue;
        uint64_t ser = h ? h_ser(h) : 0;
        if (!ser || !has_ser(rs, *n, ser)) continue;
        if (b->kind != NVN_RB_TEX) FB_NO("not-texture");
        if (k == 8) FB_NO("too-many");
        int j = -1; for (int m = 0; m < R.rt.n && m < 8; m++) if (R.rt.color[m] && R.rt.color[m]->serial == ser) { j = m; break; }
        if (j < 0) FB_NO("depth-att");
        if (!att_fb_written_ok() && draw_writes_slot(fs, j)) FB_NO("written");   // Ryujinx_Optime's rule: never tile-read a slot the draw writes
        uint64_t s_; int lv, sl; rt_sub(&R.rt, j, &s_, &lv, &sl);
        if (lv || sl) FB_NO("level-layer");
        if (g_enc) {   // the open encoder (continued or not) must hold this texture at colour index j, level 0 layer 0
            int ok = 0; for (int q = 0; q < g_nsd; q++) if (!g_sd[q].depth && g_sd[q].ser == ser && g_sd[q].idx == j && !g_sd[q].lv && !g_sd[q].sl) ok = 1;
            if (!ok) FB_NO("enc-slot"); }
        int tid = (int)(h & 0xfffff); void *tv_ = NULL; if (tid) tex_fast_rid(tid, &tv_); __unsafe_unretained id<MTLTexture> tv = (__bridge id<MTLTexture>)tv_;
        uint32_t apf = tv.parentTexture ? (uint32_t)tv.parentTexture.pixelFormat : (uint32_t)tv.pixelFormat; uint8_t swz[4];   // as fz_p2_draw
        if (R.rt.has_cview[j] && R.rt.cview[j].set_format && !(nvn_fmt_to_mtl(R.rt.cview[j].format, &apf, swz) && apf)) FB_NO("view");
        if (!tv || tv.textureType != MTLTextureType2D || (tv.parentTexture && (tv.parentRelativeLevel || tv.parentRelativeSlice)) || tv.pixelFormat != (MTLPixelFormat)apf) FB_NO("view");
        aid[k] = b->aid; att[k] = j; k++;
        if (!has_ser(took, nt, ser)) took[nt++] = ser;
    }
    if (!k) FB_NO("none");
    for (int st = 0; st < 5; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh == fs || sh->stage >= 6) continue;   // other stages read memory
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
            if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = b->reg < 128 ? S.tex[sh->stage][b->reg] : 0; else continue;
            if (h && has_ser(took, nt, h_ser(h))) FB_NO("other-stage"); } }
    id<MTLFunction> fn = fs_fn_fbread(fs, aid, att, k);
    if (fn) { int o = 0; g_pso_fbrec[0] = 0; for (int i = 0; i < k && o < (int)sizeof g_pso_fbrec - 24; i++) o += snprintf(g_pso_fbrec + o, sizeof g_pso_fbrec - o, "%d:%d;", aid[i], att[i]); }
    if (!fn) FB_NO("msl");
#undef FB_NO
    int m = 0; for (int i = 0; i < *n; i++) if (!has_ser(took, nt, rs[i])) rs[m++] = rs[i];
    *n = m;
    if (!m) {   // every attachment bound in any slot of any stage (draw_samples_rt's walk, typed buffers too) was taken
        uint64_t cand[18]; int nc = 0;
        for (int q = 0; q < R.rt.n && q < 8; q++) if (R.rt.color[q]) cand[nc++] = R.rt.color[q]->serial;
        if (R.rt.depth) cand[nc++] = R.rt.depth->serial;
        if (g_enc) for (int q = 0; q < g_nsd && nc < 18; q++) cand[nc++] = g_sd[q].ser;
        int rest = 0;
        for (int st = 0; st < 5 && !rest; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh->stage >= 6) continue;
            for (int i = 0; i < sh->rf.nb && !rest; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
                if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = b->reg < 128 ? S.tex[sh->stage][b->reg] : 0; else continue;
                uint64_t ser = h ? h_ser(h) : 0; if (ser && has_ser(cand, nc, ser) && !has_ser(took, nt, ser)) rest = 1; } }
        *all = !rest;
    }
    g_fb_draws++; return fn;
}
/* Pass-end diagnostics for samples-drawn-att: per attachment the draw still samples, "c<index>:<format>:w<write mask>:o<declared
   output>" (d = depth / stencil, ? = not in the targets), and why the tile read did not take it. Interned, because the
   TOTK_PASS_GPU table keeps the pointer until the frame is written. */
static const char *att_split_why(const char *base, NvProg *pr, const uint64_t *rs, int n) {
    char b[256]; int o = snprintf(b, sizeof b, "%s[", base);
    NvShader *fs = pr ? pr->sh[1] : nil;
    for (int i = 0; i < n && o < (int)sizeof b - 40; i++) {
        int j = -1; for (int m = 0; m < R.rt.n && m < 8; m++) if (R.rt.color[m] && R.rt.color[m]->serial == rs[i]) { j = m; break; }
        if (j < 0) { o += snprintf(b + o, sizeof b - o, "%s%s", i ? ";" : "", R.rt.depth && R.rt.depth->serial == rs[i] ? "d" : "?"); continue; }
        id<MTLTexture> t = tex_mtl(R.rt.color[j]); MTLPixelFormat pf = t ? t.pixelFormat : MTLPixelFormatInvalid; const char *fn = NULL;
        switch (pf) { case MTLPixelFormatR32Float: fn = "R32Float"; break; case MTLPixelFormatRGBA8Unorm: fn = "RGBA8Unorm"; break; case MTLPixelFormatRGBA8Unorm_sRGB: fn = "RGBA8sRGB"; break;
            case MTLPixelFormatBGRA8Unorm: fn = "BGRA8Unorm"; break; case MTLPixelFormatRGB10A2Unorm: fn = "RGB10A2Unorm"; break; case MTLPixelFormatRG11B10Float: fn = "RG11B10Float"; break;
            case MTLPixelFormatRGBA16Float: fn = "RGBA16Float"; break; case MTLPixelFormatRG16Float: fn = "RG16Float"; break; case MTLPixelFormatR16Float: fn = "R16Float"; break;
            case MTLPixelFormatRG16Unorm: fn = "RG16Unorm"; break; case MTLPixelFormatR8Unorm: fn = "R8Unorm"; break; case MTLPixelFormatRG8Unorm: fn = "RG8Unorm"; break; default: break; }
        char fb[16]; if (!fn) { snprintf(fb, sizeof fb, "fmt%lu", (unsigned long)pf); fn = fb; }
        o += snprintf(b + o, sizeof b - o, "%sc%d:%s:w%x:o%d", i ? ";" : "", j, fn, (unsigned)((S.chmask.mask >> (4 * j)) & 0xf), fs ? (fs_color_outs(fs) >> j & 1) : 0);
    }
    if (o < (int)sizeof b - 24) snprintf(b + o, sizeof b - o, "]fb=%s", !att_fb_on() ? "off" : g_fb_why ? g_fb_why : "partial");
    static char *tab[512]; static int nt;
    for (int i = 0; i < nt; i++) if (!strcmp(tab[i], b)) return tab[i];
    if (nt == 512) return base;
    return tab[nt++] = strdup(b);
}
// ---------- Store lookahead index: at the start of a submit do one linear scan in replay order and record events per texture; when a render pass ends, binary-search each attachment for "the first valid event afterwards" to decide ----------
// Replaces the original "scan the whole remainder forward at every render pass end" (pass count x command count, 49 render passes per frame in camp). Cross-checked per attachment against the original scan: after 0 mismatches over the 17 pages of the screenshot gate + a camp run with about 340,000 attachment decisions (about 46,000 redundant), the original scan was removed.
// Events (seq = replay sequence number): READ a draw / dispatch reads this texture per program reflection; ATT it is a current attachment at a draw; CLEAR cleared as a whole block while an attachment; COPY / CLRTEX either end of a copy / the cleared texture.
// Decision (the first valid event decides): READ / COPY / CLRTEX -> needed; ATT whose SetRenderTargets is after the render pass end -> needed (load); CLEAR with the same -> redundant; no event -> needed.
// On any uncertainty (replay sequence number does not match the index, nesting too deep) the index is invalidated and all remaining render passes of this submit store (storing is always correct, it just saves less bandwidth).
typedef struct { uint32_t seq, rtseq; uint64_t ser; const uint8_t *op; uint16_t lv, sl; uint8_t kind, plane, anyls, why; } sdx_ev;   // plane 0 color 8 depth-stencil (ATT) 1 depth 2 stencil (CLEAR)
enum { SDX_READ = 1, SDX_NEED, SDX_ATT, SDX_CLEAR };
#define SDX_NONE 0xffffffffu
static sdx_ev *g_sdx, *g_sdx_tmp; static uint32_t g_sdx_n, g_sdx_cap; static int g_sdx_ok;   // Index valid
// Candidate textures (those that have been attachments) -> buckets: open addressing; a texture that has not yet been an attachment when an event occurs is irrelevant to any render pass that ended before then, so it is not recorded
#define SDX_HB 2048
static uint64_t g_sdx_hk[SDX_HB]; static uint16_t g_sdx_hb[SDX_HB]; static uint32_t g_sdx_nb, g_sdx_bcnt[SDX_HB + 1], g_sdx_bst[SDX_HB + 1];
static int sdx_bucket(uint64_t ser, int add) {   // Returns the bucket number; returns -1 if not in the set (and not adding); invalidates the index when full
    if (!ser) return -1;
    for (uint32_t i = (uint32_t)(ser * 0x9E3779B97F4A7C15ull >> 53), n = 0; n < SDX_HB; i = (i + 1) & (SDX_HB - 1), n++) {
        if (g_sdx_hk[i] == ser) return g_sdx_hb[i];
        if (!g_sdx_hk[i]) { if (!add) return -1; if (g_sdx_nb >= SDX_HB / 2) { g_sdx_ok = 0; return -1; } g_sdx_hk[i] = ser; g_sdx_hb[i] = (uint16_t)g_sdx_nb; return (int)g_sdx_nb++; }
    }
    return -1;
}
static const uint8_t **g_sdx_op; static uint32_t g_sdx_nop, g_sdx_opcap;
static uint32_t g_exec_seq;   // Sequence number of the current operation during replay
static uint64_t g_pp_slot[6][160]; static const prog_t *g_pp_prog; static const p_set_rt *g_pp_rt; static uint32_t g_pp_rtseq;
static uint32_t *g_rtx_seq, *g_drx_seq; static uint32_t g_rtx_n, g_rtx_cap, g_drx_n, g_drx_cap;   // This submit's SET_RT / draw sequence number tables (used by the pre-screen of the readable tile merge)
static void seq_push(uint32_t **v, uint32_t *n, uint32_t *cap, uint32_t x) { if (*n == *cap) { *cap = *cap ? *cap * 2 : 1024; *v = realloc(*v, *cap * sizeof **v); } (*v)[(*n)++] = x; }
static void sdx_ev_add(sdx_ev e) { if (sdx_bucket(e.ser, 0) < 0) return; if (g_sdx_n == g_sdx_cap) { g_sdx_cap = g_sdx_cap ? g_sdx_cap * 2 : 4096; g_sdx = realloc(g_sdx, g_sdx_cap * sizeof *g_sdx); g_sdx_tmp = realloc(g_sdx_tmp, g_sdx_cap * sizeof *g_sdx); } g_sdx[g_sdx_n++] = e; }
static void sdx_lvsl(const view_t *v, int hv, uint16_t *lv, uint16_t *sl) { *lv = (uint16_t)(hv && v->set_levels ? v->base_level : 0); *sl = (uint16_t)(hv && v->set_layers ? v->min_layer : 0); }
static int g_sdx_ren = 1;   // TOTK: render-enable state along the walk (SetRenderEnable / conditional, see cond_eval)
static void sdx_walk(const uint8_t *p, int depth) {
    if (depth > 64) { g_sdx_ok = 0; return; }
    for (uint32_t guard = 0; guard < 4000000 && p && g_sdx_ok; guard++) {
        op_hdr h; memcpy(&h, p, sizeof h); const void *a = p + 8;
        if (g_sdx_nop == g_sdx_opcap) { g_sdx_opcap = g_sdx_opcap ? g_sdx_opcap * 2 : 16384; g_sdx_op = realloc(g_sdx_op, g_sdx_opcap * sizeof *g_sdx_op); }
        uint32_t seq = g_sdx_nop; g_sdx_op[g_sdx_nop++] = p;
        switch (h.op) {
            case OP_END: return;
            case OP_JUMP: { const uint8_t *t; memcpy(&t, a, 8); p = t; continue; }
            case OP_CALL: { uint64_t t; memcpy(&t, a, 8); sdx_walk((const uint8_t *)t, depth + 1); break; }
            case OP_SET_RT: { const p_set_rt *r = a; g_pp_rt = r; g_pp_rtseq = seq; seq_push(&g_rtx_seq, &g_rtx_n, &g_rtx_cap, seq);
                for (int k = 0; k < r->n && k < 8; k++) if (r->color[k]) sdx_bucket(r->color[k]->serial, 1);
                if (r->depth) sdx_bucket(r->depth->serial, 1);
                break; }
            case OP_RENDER_ENABLE: g_sdx_ren = ((const p_flag *)a)->value; break;
            case OP_RENDER_COND: g_sdx_ren = cond_eval(a, p); break;
            case OP_CLEAR_COLOR: { const p_clear_color *c = a; const p_set_rt *r = g_pp_rt;
                if (!g_sdx_ren) break;   // TOTK: this clear will not run
                if (!r || (c->mask & 0xf) != 0xf || c->index < 0 || c->index >= r->n || c->index >= 8 || !r->color[c->index]) break;
                uint16_t lv, sl; sdx_lvsl(&r->cview[c->index], r->has_cview[c->index], &lv, &sl); int last = -1;   // When the same subresource is attached at several indices, the last one counts
                for (int k = 0; k < r->n && k < 8; k++) { uint16_t l2, s2; if (!r->color[k] || r->color[k]->serial != r->color[c->index]->serial) continue; sdx_lvsl(&r->cview[k], r->has_cview[k], &l2, &s2); if (l2 == lv && s2 == sl) last = k; }
                if (last == c->index) sdx_ev_add((sdx_ev){seq, g_pp_rtseq, r->color[c->index]->serial, p, lv, sl, SDX_CLEAR, 0, 0, 0});
                break; }
            case OP_CLEAR_DS: { const p_clear_ds *c = a; const p_set_rt *r = g_pp_rt; if (!g_sdx_ren || !r || !r->depth) break;
                uint16_t lv, sl; sdx_lvsl(&r->dview, r->has_dview, &lv, &sl);
                if (c->depth_mask) sdx_ev_add((sdx_ev){seq, g_pp_rtseq, r->depth->serial, p, lv, sl, SDX_CLEAR, 1, !r->has_dview, 0});
                if ((c->stencil_mask & 0xff) == 0xff) sdx_ev_add((sdx_ev){seq, g_pp_rtseq, r->depth->serial, p, lv, sl, SDX_CLEAR, 2, !r->has_dview, 0});
                break; }
            case OP_BIND_TEX: case OP_BIND_IMG: { const p_bind_handles *b = a; int base = h.op == OP_BIND_IMG ? 128 : 0, lim = h.op == OP_BIND_IMG ? 32 : 128;
                if (b->stage < 6 && b->first >= 0 && b->first + b->n <= lim) for (int k = 0; k < b->n; k++) g_pp_slot[b->stage][base + b->first + k] = h_ser(b->h[k]);
                break; }
            case OP_BIND_PROGRAM: g_pp_prog = ((const p_bind_program *)a)->prog; break;
            case OP_DRAW: case OP_DRAW_IDX: case OP_DISPATCH: {
                if (h.op != OP_DISPATCH) seq_push(&g_drx_seq, &g_drx_n, &g_drx_cap, seq);
                __unsafe_unretained NvProg *pr = g_pp_prog ? prog_get(g_pp_prog) : nil;
                if (!pr) { for (int st = 0; st < 6; st++) for (int k = 0; k < 160; k++) if (g_pp_slot[st][k]) sdx_ev_add((sdx_ev){seq, 0, g_pp_slot[st][k], p, 0, 0, SDX_READ, 0, 0, 1}); }
                else for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || (h.op == OP_DISPATCH) != (st == 5)) continue;
                    for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; int k = b->kind == NVN_RB_IMG ? 128 + b->reg : (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) ? b->reg : -1;
                        if (k < 0 || k >= 160 || sh->stage < 0 || sh->stage >= 6) continue; uint64_t ser = g_pp_slot[sh->stage][k];
                        if (ser) sdx_ev_add((sdx_ev){seq, 0, ser, p, 0, 0, SDX_READ, 0, 0, 1}); } }
                const p_set_rt *r = g_pp_rt;
                if (h.op != OP_DISPATCH && r) {
                    for (int k = 0; k < r->n && k < 8; k++) if (r->color[k]) { uint16_t lv, sl; sdx_lvsl(&r->cview[k], r->has_cview[k], &lv, &sl); sdx_ev_add((sdx_ev){seq, g_pp_rtseq, r->color[k]->serial, p, lv, sl, SDX_ATT, 0, 0, 2}); }
                    if (r->depth) { uint16_t lv, sl; sdx_lvsl(&r->dview, r->has_dview, &lv, &sl); sdx_ev_add((sdx_ev){seq, g_pp_rtseq, r->depth->serial, p, lv, sl, SDX_ATT, 8, !r->has_dview, 2}); }
                }
                break; }
            case OP_COPY_T2T: { const p_copy_t2t *c = a; if (c->src) sdx_ev_add((sdx_ev){seq, 0, c->src->serial, p, 0, 0, SDX_NEED, 0, 0, 3}); if (c->dst) sdx_ev_add((sdx_ev){seq, 0, c->dst->serial, p, 0, 0, SDX_NEED, 0, 0, 3}); break; }
            case OP_COPY_T2B: case OP_COPY_B2T: { const p_copy_b2t *c = a; if (c->tex) sdx_ev_add((sdx_ev){seq, 0, c->tex->serial, p, 0, 0, SDX_NEED, 0, 0, 3}); break; }
            case OP_CLEAR_TEX: { const p_clear_tex *c = a; if (c->tex) sdx_ev_add((sdx_ev){seq, 0, c->tex->serial, p, 0, 0, SDX_NEED, 0, 0, 4}); break; }
            default: break;
        }
        p += h.size;
    }
}
void mtl_sub_index(const uint64_t *h, int n) {   // Start of submit (hle_nvn.c QueueSubmitCommands): build this submit's store lookahead index
    g_xv_ntouch = 0; g_sdx_n = g_sdx_nop = 0; g_rtx_n = g_drx_n = 0; g_exec_seq = 0; g_sdx_ok = tbdr_piece(TB_STORE) || tbdr_piece(TB_DEFER) || tbdr_piece(TB_FUSE);
    uint64_t tb_t0 = g_sdx_ok ? clock_gettime_nsec_np(CLOCK_UPTIME_RAW) : 0;
    if (!g_sdx_ok) { g_xv_n = 0; g_xv_block = 1; return; }   // Index unavailable: clear the ledger and add nothing in this submit (the next touch cannot be verified)
    g_xv_block = 0;
    memset(g_sdx_hk, 0, sizeof g_sdx_hk); g_sdx_nb = 0;
    for (int i = 0; i < g_xv_n; i++) sdx_bucket(g_xv[i].ser, 1);   // Textures in the ledger enter the candidate set: otherwise, when one is only sampled and not used as an attachment in this submit, its read events are not indexed and the fallback cannot see them
    if (R.has_rt) { for (int k = 0; k < R.rt.n && k < 8; k++) if (R.rt.color[k]) sdx_bucket(R.rt.color[k]->serial, 1); if (R.rt.depth) sdx_bucket(R.rt.depth->serial, 1); }   // The targets at the start of the submit (the first draw may reopen the render pass without going through SetRenderTargets)
    g_pp_prog = S.prog; g_pp_rt = NULL; g_pp_rtseq = SDX_NONE;
    for (int st = 0; st < 6; st++) { for (int k = 0; k < 128; k++) g_pp_slot[st][k] = S.tex[st][k] ? h_ser(S.tex[st][k]) : 0;
                                     for (int k = 0; k < 32; k++) g_pp_slot[st][128 + k] = S.img[st][k] ? h_ser(S.img[st][k]) : 0; }
    g_sdx_ren = 1;
    for (int i = 0; i < n && g_sdx_ok; i++) sdx_walk((const uint8_t *)h[i], 0);
    if (!g_sdx_ok) { g_tb_ns[TB_IDX] += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - tb_t0; return; }
    // Counting sort into buckets: events are appended in sequence-number order, and within the same sequence number READ precedes ATT (the same draw is judged for reads first, then attachments), so after a stable scatter each bucket is ordered
    memset(g_sdx_bcnt, 0, (g_sdx_nb + 1) * sizeof *g_sdx_bcnt);
    for (uint32_t i = 0; i < g_sdx_n; i++) g_sdx_bcnt[sdx_bucket(g_sdx[i].ser, 0)]++;
    for (uint32_t b = 0, acc = 0; b <= g_sdx_nb; b++) { g_sdx_bst[b] = acc; acc += b < g_sdx_nb ? g_sdx_bcnt[b] : 0; }
    for (uint32_t b = 0; b < g_sdx_nb; b++) g_sdx_bcnt[b] = g_sdx_bst[b];
    for (uint32_t i = 0; i < g_sdx_n; i++) g_sdx_tmp[g_sdx_bcnt[sdx_bucket(g_sdx[i].ser, 0)]++] = g_sdx[i];
    sdx_ev *t = g_sdx; g_sdx = g_sdx_tmp; g_sdx_tmp = t;
    g_tb_hit[TB_IDX]++; g_tb_ns[TB_IDX] += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - tb_t0;
    xv_forward();
}
static void sdx_seq(const uint8_t *p) {   // Every operation in mtl_exec: check the sequence number against the index (on mismatch invalidate, and store everything for the rest)
    if (!g_sdx_ok) return;
    if (g_exec_seq >= g_sdx_nop || g_sdx_op[g_exec_seq] != p) { RED_ONCE(40, "store lookahead index does not match replay order (seq %u / %u); the rest of this submit's passes all store", g_exec_seq, g_sdx_nop); g_sdx_ok = 0; return; }
    g_exec_seq++;
}
static int sdx_decide(uint8_t st[9]) {   // st[i]: 2 redundant; otherwise why << 2 (the reason it is needed, same as sd_need). Returns 0 = index unavailable
    if (!g_sdx_ok || !g_exec_cur || !g_exec_seq || g_sdx_op[g_exec_seq - 1] != g_exec_cur) return 0;
    uint32_t P = g_exec_seq - 1;
    for (int i = 0; i < g_nsd; i++) { const sd_att *t = &g_sd[i]; st[i] = 5 << 2;
        int b = sdx_bucket(t->ser, 0); if (b < 0) continue;   // Not in the candidate set: no related event at all in this submit -> undecided after scanning to the end, needed
        uint32_t lo = g_sdx_bst[b], end = g_sdx_bst[b + 1], hi = end;   // First seq >= P in the bucket
        while (lo < hi) { uint32_t m = (lo + hi) / 2; if (g_sdx[m].seq < P) lo = m + 1; else hi = m; }
        for (uint32_t j = lo; j < end; j++) { const sdx_ev *e = &g_sdx[j];
            if (g_hoist_n && hoist_skipped(e->op)) continue;
            if (e->kind == SDX_READ || e->kind == SDX_NEED) { st[i] = (uint8_t)(e->why << 2); break; }
            if (e->rtseq == SDX_NONE || e->rtseq < P || (g_hoist_n && hoist_skipped(g_sdx_op[e->rtseq]))) continue;   // This target was set before the render pass ended: not re-set as an attachment after the render pass ended, so it does not count
            int hit = t->depth ? (e->kind == SDX_ATT ? e->plane == 8 : e->plane == t->depth) && (e->anyls || (e->lv == t->lv && e->sl == t->sl))
                               : e->plane == 0 && e->lv == t->lv && e->sl == t->sl;
            if (!hit) continue;
            st[i] = e->kind == SDX_CLEAR ? 2 : (uint8_t)(2 << 2); break; }
    }
    return 1;
}
static void xv_forward(void) {
    if (!g_xv_n) return;
    if (!g_sdx_ok) { g_xv_n = 0; g_xv_block = 1; return; }
    for (int i = 0; i < g_xv_n;) {
        xv_ent *e = &g_xv[i]; int b = sdx_bucket(e->ser, 0), action = 0;
        if (b >= 0) for (uint32_t j = g_sdx_bst[b]; j < g_sdx_bst[b + 1]; j++) { sdx_ev *v = &g_sdx[j];
            if (v->kind == SDX_READ || v->kind == SDX_NEED) { xv_ent copy = *e; xv_violation(&copy, "submit lookahead read/need"); action = 2; break; }
            if (v->lv != e->lv || v->sl != e->sl) continue;
            if (v->kind == SDX_CLEAR) { xv_good(e); action = 1; break; }
            if (v->kind == SDX_ATT) break;
        }
        if (!action) i++;
    }
}
static void rt_sub(const p_set_rt *r, int k, uint64_t *ser, int *lv, int *sl) {   // Subresource of attachment k (0–7 color, 8 depth)
    const tex_t *t = k == 8 ? r->depth : r->color[k]; const view_t *v = k == 8 ? &r->dview : &r->cview[k]; int hv = k == 8 ? r->has_dview : r->has_cview[k];
    *ser = t ? t->serial : 0; *lv = hv && v->set_levels ? v->base_level : 0; *sl = hv && v->set_layers ? v->min_layer : 0;
}
static void hoist_try(void) {
    if (g_hoist_n || !g_exec_next) return;
    typedef struct { const uint8_t *rt_op; const p_set_rt *rt; uint8_t clear_c[8]; MTLClearColor cc[8]; uint8_t clear_d, clear_s; double cd; uint32_t cs;
                     p_scissor sc; int has_sc; const uint8_t *ops[8]; int nops; } grp;
    grp G[4]; int ng = 0, in_grp = 0; p_scissor sc = R.sc; int has_sc = R.has_sc;
    // The binding set needed for "the cleared texture is not on any slot": the table is looked up only when a hoistable clear group is really found and we are back to this render pass's targets (the vast majority of render passes never get that far).
    // Handles bound within the scan range are noted first and converted to texture serials together with the current slots at lookup time; the scan only reads commands and the current slots S do not change meanwhile, so the result is the same as checking at the start
    uint64_t bh[512]; int nbh = 0;
    const uint8_t *p = g_exec_next;
    for (int guard = 0; guard < 200000; guard++) {
        op_hdr h; memcpy(&h, p, sizeof h); const void *a = p + 8;
        switch (h.op) {
            case OP_END: case OP_CALL: case OP_COPY_T2T: case OP_COPY_B2T: case OP_COPY_T2B: case OP_CLEAR_TEX: case OP_DISPATCH: return;
            case OP_JUMP: { const uint8_t *t; memcpy(&t, a, 8); p = t; continue; }
            case OP_DRAW: case OP_DRAW_IDX: if (in_grp) return; break;
            case OP_SCISSOR: sc = *(const p_scissor *)a; has_sc = 1; break;
            case OP_RENDER_ENABLE: if (!((const p_flag *)a)->value) return; break;   // TOTK: clears recorded while rendering is disabled do not run
            case OP_RENDER_COND: if (!cond_eval(a, p)) return; break;
            case OP_BIND_TEX: case OP_BIND_IMG: { const p_bind_handles *b = a; for (int k = 0; k < b->n && k < 32 && nbh < 512; k++) if (b->h[k]) bh[nbh++] = b->h[k]; break; }
            case OP_CLEAR_COLOR: case OP_CLEAR_DS: {
                if (!in_grp || G[ng - 1].nops >= 8) return;
                grp *g = &G[ng - 1];
                if (h.op == OP_CLEAR_COLOR) { const p_clear_color *c = a;
                    if (c->index < 0 || c->index >= g->rt->n || !g->rt->color[c->index] || c->mask != 0xf) return;
                    const tex_t *t = g->rt->color[c->index];
                    if (has_sc && !(sc.x <= 0 && sc.y <= 0 && sc.x + sc.w >= (int)t->d.width && sc.y + sc.h >= (int)t->d.height)) return;
                    g->clear_c[c->index] = 1; g->cc[c->index] = MTLClearColorMake(c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]); }
                else { const p_clear_ds *c = a; if (!g->rt->depth) return;
                    if (c->depth_mask) { g->clear_d = 1; g->cd = c->depth; } if (c->stencil_mask) { g->clear_s = 1; g->cs = (uint32_t)c->stencil; } }
                g->sc = sc; g->has_sc = has_sc; g->ops[g->nops++] = p; break; }
            case OP_SET_RT: { const p_set_rt *r = a;
