    if (g_nwide == WIDE_MAX) MDIE("too many GPU-widened index buffers in one submit");
    id<MTLBuffer> wb; size_t wo; widen_u8_gpu(gpu, (uint32_t)di->count, &wb, &wo);   /* arena buffers live until the submit completes */
