    if (g_anom[k].n == g_anom[k].cap) {
        uint32_t c = g_anom[k].cap ? g_anom[k].cap * 2 : 4096; anom_draw *d = realloc(g_anom[k].d, c * sizeof *d);
        if (!d) MDIE("anomaly ring allocation"); g_anom[k].d = d; g_anom[k].cap = c;
    }
