    a->first = dw ? dw->first : 0; a->count = dw ? dw->count : di->count; a->inst = dw ? 1 : di->instances; a->bv = di ? di->base_vertex : 0;
    a->ib = di ? di->ibuf : 0; a->vb0 = S.vbuf[0].address;
