    if (R.rt.depth) { const tex_t *x = R.rt.depth; a->rt[2] = (anom_tex){x->serial, (uint64_t)x->mem, NULL, x->d.width, x->d.height, x->d.format}; }
    a->nrt = (uint8_t)(R.rt.n < 2 ? R.rt.n : 2);
