        void *mb; uint64_t mo; if (!mtl_addr(S.vbuf[st].address + off, n, &mb, &mo)) continue;
        a->vh[a->nvs] = anom_hash((const uint8_t *)(uintptr_t)(S.vbuf[st].address + off), n); a->vlen[a->nvs++] = (uint32_t)n;
    }
