        for (int z = 0; z < nz; z++) nvn_bc1_to_astc_image(src + z * img, row, (uint32_t)bw4, (uint32_t)hb, (uint8_t *)buf.contents + z * arow * hb, bc1_rgba(t->d.format));
        id<MTLCommandBuffer> cb = q_cb(); id<MTLBlitCommandEncoder> b = enc_b_begin(cb);
