    TotkCommitOptions *o = [TotkCommitOptions new]; [o addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
        failed = fb.error != nil; if (failed) MLOG("[red] [anom] GPU readback failed: %s", fb.error.localizedDescription.UTF8String);
